"""
Live Interview Assistant
================================

A grounded recall aid over YOUR OWN knowledge (an Obsidian vault + resume).

Design contract (this is what keeps the tool legitimate):
  * It answers ONLY from your notes/resume.
  * If nothing relevant is found, it returns an honest, professional
    "I haven't worked hands-on with X" response -- it never invents experience.

Retrieval is semantic (Google Gemini embeddings). Answers are generated by a
configurable provider (Gemini by default -- cheapest and reuses the same key; OpenRouter
optional). Spend is capped by the owner in Google Cloud -- there is NO in-app budget logic.
A localhost web overlay (stdlib http.server) transcribes a spoken question in the browser
and streams a first-person answer back onto the screen.

Optional: a Windows WASAPI loopback listener can transcribe the *interviewer's* audio
(what plays out of your speakers) using the SAME Gemini key as a cloud STT. That path is
fully decoupled from /ask and only activates when you call /listen/start.

This script is fully self-contained: config loading, retrying HTTP session, semantic
index, retrieval, answer generation, JD focus-steering, loopback STT, and the web server
all live here. (It originated in a separate notes-tooling repo and reuses those proven
config/session patterns, but has no dependency on it.)

Config keys read from config.json (interview block), with sensible defaults:
  vault_path, resume_path, embed_model, embed_dim, answer_provider, answer_model,
  top_k, min_score, port,
  adjacent_margin   (0.08)  -- band below min_score that counts as "adjacent"
  jd_path           ("job_description.md")
  stt_model         ("gemini-3.1-flash-lite")  -- audio $0.50/M; 3.5-flash is $1.50/M
  stt_sample_rate   (16000)
  silence_threshold (0.012)  -- RMS energy above which a frame counts as speech
  silence_hangover_ms (600)  -- trailing silence that finalizes an utterance (also live-tunable
                                in the Settings panel; shorter = snappier, merge recombines pauses)

CLI:
  python interview_assistant.py --build-index          # build/refresh the semantic index
  python interview_assistant.py --rebuild              # force a full re-embed
  python interview_assistant.py --ask "your question"  # one-shot grounded answer (prep/testing)
  python interview_assistant.py --serve [--port 8765]  # launch the live voice overlay
"""

