class SetupError(Exception):
    """A problem the USER must fix (missing config, no index, no API key).

    Separated from ordinary exceptions so the entry point can print it plainly. A newcomer
    who has just cloned the repo should read one actionable line, not eight frames of stack
    that end in the actionable line."""


def default_config_path() -> Path:
    return Path(__file__).parent / "config.json"


def inspect_vault(raw: str, script_dir: Path, interview: Optional[dict] = None) -> dict:
    """Report what the app would actually index at this path, WITHOUT indexing anything.

    Editing `vault_path` by hand and running a one-hour build to discover the path was wrong, or
    that 4,000 of the notes are a plugin's cache, is a bad first hour. This answers the three
    questions that decide whether the path is right -- does it exist, how many notes, and which
    top-level folders (which are what the tier map is written against) -- in a few milliseconds."""
    out = {"path": raw, "exists": False, "files": 0, "chars": 0, "folders": [], "error": ""}
    raw = str(raw or "").strip().strip('"')
    if not raw:
        out["error"] = "No path given."
        return out
    p = Path(raw)
    if not p.is_absolute():
        p = script_dir / p
    out["resolved"] = str(p)
    if not p.exists():
        out["error"] = "That folder does not exist."
        return out
    if not p.is_dir():
        out["error"] = "That is a file, not a folder."
        return out
    out["exists"] = True

    excl = {n.lower() for n in SKIP_DIR_NAMES} | {
        str(x).lower() for x in ((interview or {}).get("vault_exclude") or [])}
    per_folder: Dict[str, int] = {}
    files = chars = 0
    for f in p.rglob("*.md"):
        if _excluded(f, excl):
            continue
        files += 1
        try:
            chars += f.stat().st_size
        except OSError:
            pass
        rel = f.relative_to(p).parts
        per_folder[rel[0] if len(rel) > 1 else "(root)"] = \
            per_folder.get(rel[0] if len(rel) > 1 else "(root)", 0) + 1
        if files > 50000:      # a runaway path (a whole drive) must not hang the request
            out["error"] = "More than 50,000 notes found -- is this the right folder?"
            break
    out["files"] = files
    out["chars"] = chars
    # Rough only. Calibrated against this machine's real vault: 15.5M chars -> 20,636 chunks, i.e.
    # ~750 chars per chunk. Heading-aware chunking means the true number depends on how the notes
    # are structured, so this is presented as an order of magnitude, not a promise.
    out["est_chunks"] = int(chars / 750) if chars else 0
    out["est_usd"] = round(chars / EMBED_CHARS_PER_TOK / 1_000_000 * EMBED_USD_PER_MTOK, 2)
    out["folders"] = [{"name": k, "files": v}
                      for k, v in sorted(per_folder.items(), key=lambda kv: -kv[1])[:40]]
    if not files:
        out["error"] = "No .md files found under that folder."
    return out


def save_vault_path(raw: str, cfg_path: Path) -> None:
    """Write vault_path back into config.json, preserving everything else in the file.

    Rewritten from the file on disk rather than from the in-memory config, so the comment-style
    `_`-prefixed keys the example ships with survive the round trip."""
    raw = str(raw or "").strip().strip('"')
    try:
        data = json.loads(cfg_path.read_text(encoding="utf-8")) if cfg_path.exists() else {}
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    iv = data.get("interview")
    if not isinstance(iv, dict):
        iv = {}
    iv["vault_path"] = raw
    data["interview"] = iv
    tmp = cfg_path.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(data, indent=2), encoding="utf-8")
    os.replace(tmp, cfg_path)


def pick_folder_dialog() -> str:
    """Native folder picker via tkinter (stdlib). Returns "" when unavailable or cancelled.

    Only ever offered to a LOOPBACK client: the dialog opens on the machine running the server, so
    on the phone mirror it would pop a window on the laptop that nobody is looking at."""
    try:
        import tkinter
        from tkinter import filedialog
    except Exception:
        return ""
    try:
        root = tkinter.Tk()
        root.withdraw()
        root.attributes("-topmost", True)
        path = filedialog.askdirectory(title="Choose your notes folder")
        root.destroy()
        return path or ""
    except Exception:
        return ""


def load_config(path: Path) -> dict:
    if not path.exists():
        example = path.parent / "config.example.json"
        hint = (f"Copy the example:  copy {example.name} {path.name}"
                if example.exists() else
                'Create it with at least:  {"interview": {"vault_path": "C:/path/to/your/vault"}}')
        raise SetupError(f"No config file at {path}." + chr(10) + "  " + hint)
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        raise SetupError(f"{path.name} is not valid JSON ({e})." + chr(10) +
                         "  A trailing comma or a missing quote is the usual cause.") from None


def _api_error(kind: str, status: int, text: str, cfg: Optional[dict] = None) -> str:
    """A message a user can act on, instead of the provider's raw JSON.

    401/403 and most 400s on this API mean the key is wrong, disabled, or billing is off.
    Dumping the raw error body in the answer pane tells a newcomer nothing they can use."""
    env_name = (((cfg or {}).get("gemini") or {}).get("api_key_env") or GEMINI_KEY_ENV)
    if status in (400, 401, 403):
        return (f"The API rejected the request (HTTP {status}). The usual cause is an "
                f"invalid or disabled Gemini key, or billing not enabled on that Google Cloud "
                f"project. The key comes from {env_name} when that is set, otherwise from "
                f"Settings > AI providers & API keys." + chr(10) + f"  Details: {text[:200]}")
    # A project SPENDING CAP also answers 429, but waiting a moment does nothing: every call fails
    # until the cap is raised or the month resets. Found 30 Sep 2026, when the owner's $3 cap ran
    # out and the app said "wait a moment and ask again".
    if status == 429 and re.search(r"spend(?:ing)? cap", text or "", re.I):
        return ("Your Google Cloud project has reached its monthly spending cap (HTTP 429), so "
                "every Gemini call fails until the cap is raised or the month resets. Raise it "
                "at https://ai.studio/spend." + chr(10) + f"  Details: {text[:200]}")
    if status == 429:
        return ("Rate limited by the API (HTTP 429). Wait a moment and ask again."
                + chr(10) + f"  Details: {text[:200]}")
    if status >= 500:
        return (f"The API is having trouble (HTTP {status}). This is on their side; "
                f"retry shortly." + chr(10) + f"  Details: {text[:200]}")
    return f"Gemini {kind} error {status}: {text[:300]}"


# The key comes from the ENVIRONMENT, never from config.json.
#
# Why a dedicated variable name rather than the conventional GEMINI_API_KEY: that name is already
# taken on this machine by a different project, and silently inheriting another app's key is exactly
# the failure this change exists to prevent -- one key shared across several apps made a month of
# spend impossible to attribute to the app that caused it. One app, one key, one name.
GEMINI_KEY_ENV = "INTERVIEW_ASSISTANT_GEMINI_KEY"


def get_gemini_settings(cfg: dict, script_dir: Optional[Path] = None) -> dict:
    """The Gemini key, resolved like every other provider's (resolve_provider_key): the environment
    variable first, then a key entered in Settings for this run, then one saved there with
    "Remember on this machine" (api_keys.json, plaintext, opt-in).

    Until 30 Sep 2026 this read ONLY the environment variable, while Settings offered a Gemini row
    with Add key and Remember. A key typed there was verified, reported as saved, and never used.
    Gemini is the one key every user needs, so it is also the one a first-time user most needs to
    be able to enter without learning setx."""
    gemini = cfg.get("gemini", {})
    env_name = (gemini.get("api_key_env") or GEMINI_KEY_ENV).strip()
    api_key, source = resolve_provider_key("gemini", cfg, script_dir or Path(__file__).parent)
    if api_key:
        # A leftover plaintext key in config.json is a live secret sitting in a file, and it is
        # never read: say so once so it gets deleted rather than lingering.
        if gemini.get("api_key"):
            _warn_once("config_key_ignored",
                       f"  ! config.json still contains gemini.api_key -- IGNORED. Delete that "
                       f"line; the key comes from {env_name} or from Settings.")
        return {"api_key": api_key, "source": source}
    if gemini.get("api_key"):
        raise SetupError(
            f"gemini.api_key in config.json is no longer used.\n"
            f"  Add the key in Settings > AI providers & API keys, or set it (once, in a normal "
            f"shell) with:\n"
            f'      setx {env_name} "your-key-here"\n'
            f"  then open a NEW terminal and delete gemini.api_key from config.json.")
    raise SetupError(
        f"No Gemini API key. Start the app and add it in Settings > AI providers & API keys, "
        f"or set the {env_name} environment variable:\n"
        f'      setx {env_name} "your-key-here"\n'
        f"  then open a NEW terminal (setx only affects shells started after it).")


_WARNED: set = set()


def _warn_once(tag: str, message: str) -> None:
    if tag not in _WARNED:
        _WARNED.add(tag)
        print(message)


# ============================================================
# PROVIDER REGISTRY + KEY STORE (v3.15)
# ============================================================
#
# Gemini stays the default and nothing about it changes. What is new is that the answer model may
# come from another vendor, chosen in the UI, and that a key can be supplied WITHOUT setx.
#
# THE ENV VAR NAMES ARE DELIBERATELY NAMESPACED. `OPENAI_API_KEY` and `ANTHROPIC_API_KEY` are
# already set on this machine by other tools, and silently spending another project's key is the
# exact failure that made a month of Gemini spend impossible to attribute (see the v3.8 notes).
# One app, one key, one project -- so this app reads INTERVIEW_ASSISTANT_<PROVIDER>_KEY and never
# the conventional name.
#
# Key resolution order, first hit wins:
#   1. the provider's environment variable   -- recommended; nothing on disk
#   2. a key entered in the UI for THIS RUN  -- memory only, gone when the server stops
#   3. api_keys.json                         -- only if the user explicitly ticked "remember"
# (3) is a real tradeoff and is opt-in for that reason: it is a plaintext secret in a file, which is
# what v3.8 removed. It exists because "edit an environment variable and restart your terminal" is a
# genuinely bad first-run experience, and a git-ignored file the user consciously chose is a smaller
# problem than a key pasted into config.json. The UI says so at the point of choosing.

KEYS_STORE_NAME = "api_keys.json"

# MODEL ORDER IS PART OF THE CONTRACT: within every provider group, entries run
# CHEAPEST-AND-FASTEST FIRST and most-capable last. Gemini already read that way and Claude read
# the opposite way, which made the dropdown mean two different things depending on where you
# looked. The third tuple element is an explicit RANK (0 = cheapest/fastest) and both consumers
# SORT by it, so the order no longer depends on anyone writing the list out in the right sequence.
#
# The rule is deliberately "cheapest first" rather than "best first": the fast tier is the right
# default for a grounded-RAG interview aid (the retrieved notes do most of the work, and time to
# first token is what decides whether the answer is useful), so the sensible pick is at the top of
# every group and escalating is a deliberate downward move.
MODEL_RANK_FAST, MODEL_RANK_MID, MODEL_RANK_TOP = 0, 1, 2

