DEFAULT_PROVIDER = "gemini"

# Keys pasted into the UI without "remember" live here and nowhere else.
_RUNTIME_KEYS: Dict[str, str] = {}


def keys_store_path(script_dir: Path) -> Path:
    return script_dir / KEYS_STORE_NAME


def load_keys_store(script_dir: Path) -> dict:
    p = keys_store_path(script_dir)
    if not p.exists():
        return {}
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        print(f"WARNING: {p.name} is not valid JSON; ignoring it.", flush=True)
        return {}


def save_keys_store(script_dir: Path, data: dict) -> None:
    p = keys_store_path(script_dir)
    tmp = p.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(data or {}, indent=2), encoding="utf-8")
    os.replace(tmp, p)


def provider_env_name(provider: str, cfg: Optional[dict] = None) -> str:
    """Config may rename the variable; the namespaced default is what ships."""
    spec = PROVIDERS.get(provider) or {}
    override = ((cfg or {}).get(provider) or {}).get("api_key_env")
    return str(override or spec.get("env") or "").strip()


def resolve_provider_key(provider: str, cfg: Optional[dict] = None,
                         script_dir: Optional[Path] = None) -> Tuple[str, str]:
    """Return (key, source) where source is 'env' | 'session' | 'file' | '' (absent)."""
    env_name = provider_env_name(provider, cfg)
    if env_name:
        val = (os.environ.get(env_name) or "").strip()
        if val:
            return val, "env"
    val = (_RUNTIME_KEYS.get(provider) or "").strip()
    if val:
        return val, "session"
    if script_dir is not None:
        val = str((load_keys_store(script_dir).get(provider) or "")).strip()
        if val:
            return val, "file"
    return "", ""


def set_provider_key(provider: str, key: str, persist: bool, script_dir: Path) -> str:
    """Store a key for this run, and on disk only when the user asked. Returns the new source."""
    key = str(key or "").strip()
    store = load_keys_store(script_dir)
    if not key:
        _RUNTIME_KEYS.pop(provider, None)
        if store.pop(provider, None) is not None:
            save_keys_store(script_dir, store)
        return ""
    if persist:
        # Deliberately NOT also in _RUNTIME_KEYS: the runtime dict is checked first, so keeping a
        # copy there would make resolve_provider_key report "session" for a key that is actually on
        # disk -- the UI would say "this run only" about something that survives a restart.
        _RUNTIME_KEYS.pop(provider, None)
        store[provider] = key
        save_keys_store(script_dir, store)
        return "file"
    _RUNTIME_KEYS[provider] = key
    if store.pop(provider, None) is not None:
        save_keys_store(script_dir, store)
    return "session"


def mask_key(key: str) -> str:
    key = str(key or "")
    if len(key) <= 12:
        return "*" * len(key)
    return key[:6] + "..." + key[-4:]


def split_model_id(qualified: str) -> Tuple[str, str]:
    """'anthropic:claude-opus-5' -> ('anthropic', 'claude-opus-5').

    A BARE id (no prefix) means the configured provider, so every config and ui_settings.json
    written before this existed keeps working untouched."""
    raw = str(qualified or "").strip()
    if ":" in raw:
        head, _, tail = raw.partition(":")
        head = head.strip().lower()
        if head in PROVIDERS and tail.strip():
            return head, tail.strip()
    return "", raw


def _ranked_models(provider: str) -> List[tuple]:
    """A provider's models, cheapest-and-fastest first. Sorting here (rather than trusting the
    order the list happens to be written in) is what stopped Gemini reading cheap-first while
    Claude read cheap-last. Stable, so equal ranks keep their declared order."""
    models = (PROVIDERS.get(provider) or {}).get("models", [])
    return sorted(models, key=lambda t: t[2] if len(t) > 2 else MODEL_RANK_MID)


def provider_missing_package(provider: str) -> str:
    """The pip package this provider needs but does not have, or "" when it is ready."""
    if (PROVIDERS.get(provider) or {}).get("kind") != "anthropic":
        return ""
    try:
        import anthropic  # noqa: F401
    except ImportError:
        return "anthropic"
    return ""


# Optional packages, the feature each one turns on, and its pip name. requirements.txt installs them
# all; this list is how the app tells someone who installed less what is off and how to turn it on
# (the owner's condition for shipping one requirements file, 30 Sep 2026). Checked with find_spec,
# which does not import: importing them all measured 5.6s, 3.8s of it the anthropic package alone.
OPTIONAL_FEATURES = [
    ("numpy", "numpy", "interviewer transcription and fast search"),
    ("soundcard", "SoundCard", "interviewer transcription"),
    ("websocket", "websocket-client", "reading questions off the screen"),
    ("PIL", "pillow", "the screenshot fallback for screen questions"),
    ("pynput", "pynput", "hotkeys that work while the app is hidden"),
    ("pypdf", "pypdf", "CV import from PDF"),
    ("docx", "python-docx", "CV import from Word"),
    ("qrcode", "qrcode", "the QR code to pair your phone"),
    ("cryptography", "cryptography", "HTTPS for the phone"),
    ("anthropic", "anthropic", "answers from Claude models"),
]


_FEATURES_OFF: Optional[List[dict]] = None


def features_off() -> List[dict]:
    """[{feature, package}] for every optional package that is not installed. Computed once per
    process: a package installed while the app runs only takes effect after a restart anyway."""
    global _FEATURES_OFF
    if _FEATURES_OFF is not None:
        return _FEATURES_OFF
    import importlib.util
    off = []
    for module, package, feature in OPTIONAL_FEATURES:
        try:
            present = importlib.util.find_spec(module) is not None
        except Exception:
            present = False
        if not present:
            off.append({"feature": feature, "package": package})
    _FEATURES_OFF = off
    return off


def features_off_line(off: List[dict]) -> str:
    """One sentence naming what is off and the command that turns it all on, or "" when nothing is."""
    if not off:
        return ""
    n = len(off)
    return (f"{n} feature{'s are' if n != 1 else ' is'} off: "
            + ", ".join(f["feature"] for f in off)
            + ". Turn everything on with: pip install -r requirements.txt")


def providers_public(cfg: Optional[dict] = None, script_dir: Optional[Path] = None) -> List[dict]:
    """Provider list for the UI. NEVER returns a key -- only whether one exists, where it came
    from, and a masked preview. A settings page that can read a secret back out is a settings page
    that leaks it to anything that can reach the port."""
    out: List[dict] = []
    saved = load_keys_store(script_dir) if script_dir is not None else {}
    for pid, spec in PROVIDERS.items():
        key, src = resolve_provider_key(pid, cfg, script_dir)
        out.append({
            "id": pid,
            "label": spec["label"],
            "env": provider_env_name(pid, cfg),
            "signup": spec.get("signup", ""),
            "has_key": bool(key),
            "key_source": src,
            # A key typed with "Remember" stays on disk even after the environment variable is set,
            # and the env var then wins -- so without this the UI had no way to show, or delete, a
            # plaintext secret it was no longer using.
            "saved_copy": bool(str(saved.get(pid) or "").strip()),
            "session_copy": bool((_RUNTIME_KEYS.get(pid) or "").strip()),
            "masked": mask_key(key) if key else "",
            "can_list": bool(spec.get("can_list")),
            "warn": spec.get("warn", ""),
            "needs_package": provider_missing_package(pid),
            "models": [{"value": qualify_model_id(pid, m), "label": lab}
                       for m, lab, _r in _ranked_models(pid)],
        })
    return out


def qualify_model_id(provider: str, model: str) -> str:
    return f"{provider}:{model}" if provider and provider != DEFAULT_PROVIDER else model


def get_interview_settings(cfg: dict, script_dir: Path) -> dict:
    iv = cfg.get("interview", {})
    resume_path = iv.get("resume_path", "resume.md")
    return {
        "vault_path": iv.get("vault_path", ""),
        "resume_path": resume_path,
        "embed_model": iv.get("embed_model", "gemini-embedding-001"),
        "embed_dim": int(iv.get("embed_dim", 768)),
        "answer_provider": iv.get("answer_provider", "gemini").strip().lower(),
        "answer_model": iv.get("answer_model", "gemini-3.1-flash-lite"),
        "top_k": int(iv.get("top_k", 6)),
        "min_score": float(iv.get("min_score", 0.65)),
        "adjacent_margin": float(iv.get("adjacent_margin", 0.08)),
        "port": int(iv.get("port", 8765)),
        "jd_path": iv.get("jd_path", "job_description.md"),
        "stt_model": iv.get("stt_model", "gemini-3.1-flash-lite"),
        "stt_sample_rate": int(iv.get("stt_sample_rate", 16000)),
        "silence_threshold": float(iv.get("silence_threshold", 0.012)),
        "silence_hangover_ms": int(iv.get("silence_hangover_ms", 1500)),
        # How long a speaker must be quiet before we transcribe the not-yet-sent tail. Small on
        # purpose: it only has to outlast the gaps INSIDE speech, not decide the end of a question.
        # 0 disables it (pre-v3.12 behaviour).
        "partial_tail_flush_ms": int(iv.get("partial_tail_flush_ms", 250)),
        # How often (ms) an in-progress utterance gets a live partial transcription.
        "partial_stt_interval_ms": int(iv.get("partial_stt_interval_ms", 2500)),
        # Listening auto-stop guards. Transcription is the only cost here that accrues WITHOUT a
        # question being asked, so both are on by default; 0 disables either one.
        #   idle  -- no speech for this long => stop (tidy-up; a quiet room bills nothing anyway).
        #   max   -- total listening wall-clock => stop. THIS is the one that catches audio left
        #            playing (a lecture/call/video), which never looks idle to the VAD.
        "stt_idle_stop_minutes": float(iv.get("stt_idle_stop_minutes", 10)),
        "stt_max_session_minutes": float(iv.get("stt_max_session_minutes", 90)),
        # Price used for the on-screen estimate only (flash audio input, USD per 1M tokens).
        "stt_audio_usd_per_1m": float(iv.get("stt_audio_usd_per_1m", STT_AUDIO_USD_PER_1M)),
        # Screen context (Path A). Reads the ACTIVE browser tab's text over CDP -- opt-in, on demand,
        # zero cost when unused. `screen_url_hint` pins a domain when several tabs are open.
        "screen_enabled": bool(iv.get("screen_enabled", True)),
        "screen_cdp_url": str(iv.get("screen_cdp_url", CDP_DEFAULT_URL)),
        # List of URL substrings that identify an interview platform. Only breaks ties -- never
        # outranks the focused, visible tab -- so adding a platform can't hijack a different one.
        "screen_url_hint": (iv.get("screen_url_hint")
                            if isinstance(iv.get("screen_url_hint"), list)
                            else [iv["screen_url_hint"]] if iv.get("screen_url_hint") else []),
        "screen_max_chars": int(iv.get("screen_max_chars", 20000)),
        # Below this many characters the read is treated as a FAILURE, not a short answer, so the
        # screenshot fallback takes over instead of the model answering from a page shell. 0 = off.
        "screen_min_chars": int(iv.get("screen_min_chars", 80)),
        # Vault provenance tiers (v3.0). Folder->tier map, exclusion list, and the ceiling margin.
        # Absent vault_tiers ⇒ tier gating off (today's behaviour).
        "vault_tiers": iv.get("vault_tiers") or {},
        "vault_exclude": list(iv.get("vault_exclude") or []),
        "tier_ceiling_margin": float(iv.get("tier_ceiling_margin", 0.0)),
        # Optional curated scoping-question bank fed to /clarify (NOT indexed). Empty/absent ⇒ the
        # generic clarify prompt. Kept out of the vault so it can't crowd out technical retrieval.
        "scoping_bank_path": iv.get("scoping_bank_path", "reference-notes/REF-Scoping-Questions-Bank.md"),
        # Pro thinking budgets (see PRO_THINKING_BUDGETS). Depth-tied; optional config override
        # merges over the code defaults.
        "pro_thinking_budgets": dict(iv.get("pro_thinking_budgets") or {}),
        # Which index file this config owns (see _set_index_basename).
        "index_path": _set_index_basename(iv.get("index_path")),
    }


# Every config gets to own its own index file. The default is unchanged, so nothing existing moves;
# but WITHOUT this, pointing config.json at a different vault and running --build-index silently
# overwrites the previous vault's index -- and since the per-chunk vector cache lives INSIDE that
# file, the old vault then costs a full re-embed (~$0.46 and about an hour on a real vault) to get
# back. The bundled demo config sets its own name for exactly that reason.
#
# It is a module global rather than a parameter because save_index/load_index/load_vector_index take
# only script_dir, and threading config through them (and every caller) to fix a path would be a much
# wider change to the serving path than the problem warrants.
_INDEX_BASENAME = "interview_index.json"


def _set_index_basename(name: Optional[str]) -> str:
    global _INDEX_BASENAME
    name = str(name or "").strip()
    if name:
        if not name.lower().endswith(".json"):
            name += ".json"
        _INDEX_BASENAME = name
    return _INDEX_BASENAME


def index_path(script_dir: Path) -> Path:
    return script_dir / _INDEX_BASENAME


def vectors_path(script_dir: Path) -> Path:
    return script_dir / (_INDEX_BASENAME[:-5] + ".vectors.npy")


# ============================================================
# RUNTIME UI SETTINGS (persisted, git-ignored)
# ============================================================
#
# Small settings layer the overlay can change at runtime without editing config.json:
#   answer_model (str) -- overrides interview.answer_model from config when set
#   humanize     (bool) -- warmer/natural tone addendum for grounded/adjacent answers
# Persisted next to the script in ui_settings.json.

# Curated Gemini answer models offered in the settings UI (the current effective model is
# always added even if it's not in this list).
# Ordered cheapest-and-fastest first, because that is also the best default here.
# PRICES ($/1M in/out, 13 Aug 2026) and MEASURED TTFT (N=5, terse) -- pick on evidence, not recency:
#   gemini-3.1-flash-lite  0.25 / 1.50   857ms   <- default: faster AND cheaper than 2.5-flash was
#   gemini-3.5-flash       1.50 / 9.00  1169ms   <- 5x the input price for no measurable quality gain
#   gemini-pro-latest      1.25 / 10.00 6631ms   <- hard questions only; ~6s stall, see below
# The retired gemini-2.5-flash was 0.30 / 2.50 at ~1030ms, so 3.1-flash-lite beats it on both axes.
CURATED_ANSWER_MODELS = [
    "gemini-3.1-flash-lite",   # default: cheapest AND fastest; accepts thinkingBudget:0
    "gemini-3.5-flash",        # heavier flash tier; 5x the price, quality A/B showed no gain
    "gemini-pro-latest",       # quality tier; thinking is MANDATORY, and it is slow (~6.6s TTFT)
]

# Models Google has retired -- selecting one 404s ("no longer available"). Scrubbed from any
# persisted/override value so a stale ui_settings.json can never wedge the answer path.
#
# The WHOLE 2.5 family died here on 13 Aug 2026 with "no longer available to NEW USERS". Note the
# wording: it is per-PROJECT, not global. Older projects were grandfathered, so this app kept working
# for months and then broke the instant its key moved to a freshly-created project. ListModels is no
# help -- it still advertises 2.5, and only a real generateContent call reveals the 404.
DEPRECATED_ANSWER_MODELS = {"gemini-2.0-flash", "gemini-1.5-flash", "gemini-1.5-pro", "gemini-pro",
                            "gemini-2.5-flash", "gemini-2.5-flash-lite", "gemini-2.5-pro"}

# Models VERIFIED (by a live generateContent probe, 13 Aug 2026) to accept thinkingBudget:0, i.e.
# thinking fully OFF so the entire output budget reaches the visible answer. EXACT names only --
# "gemini-3.5-flash-lite" is a different model from "gemini-3.5-flash" and rejects budget 0, so
# substring matching here would produce a 400.
THINKING_OFF_MODELS = {
    "gemini-3.5-flash",
    "gemini-3.1-flash-lite",
    "gemini-3-flash-preview",
    "gemini-2.5-flash",        # retired, kept so an old pinned config still behaves correctly
    "gemini-2.5-flash-lite",
}


def ui_settings_path(script_dir: Path) -> Path:
    return script_dir / "ui_settings.json"


def load_ui_settings(script_dir: Path) -> dict:
    """Load persisted UI settings; returns {} if the file is missing.

    A CORRUPT file is NOT silently ignored. It is logged and moved aside to
    `ui_settings.json.corrupt`, then defaults are used. Rationale: a settings file that stops
    working with NO error is exactly the silent failure that hides a real problem -- every
    setting reverts to default (humanize off, depth balanced) with no signal. Moving it aside
    also stops the next /settings save from overwriting -- and permanently discarding -- content
    the user might want to recover. Self-healing: once moved, later reads see no file and the
    warning fires only once."""
    p = ui_settings_path(script_dir)
    with UI_SETTINGS_LOCK:
        try:
            raw = p.read_text(encoding="utf-8")
        except FileNotFoundError:
            return {}
        try:
            data = json.loads(raw)
            return data if isinstance(data, dict) else {}
        except Exception as e:
            print(f"WARNING: {p.name} is not valid JSON ({e}); moving it to "
                  f"{p.name}.corrupt and falling back to defaults.", flush=True)
            try:
                p.replace(p.with_name(p.name + ".corrupt"))
            except Exception:
                pass
            return {}


# One lock for every read and write of ui_settings.json (15 Sep 2026). The save used to be
# write_text, which truncates the file and then writes it. A /settings request reading in between
# saw an EMPTY file, declared it corrupt, moved it aside, and every saved setting fell back to
# default. Found by qa/frontend_check.py changing settings back to back: six "not valid JSON"
# warnings in one run. Laptop and phone saving at the same moment could do the same. The write is
# now a temp file plus os.replace, under this lock; the lock also matters on Windows, where
# replacing a file another thread has open for reading fails. Reentrant, so /settings can hold it
# across its whole load-change-save.
UI_SETTINGS_LOCK = threading.RLock()


def save_ui_settings(script_dir: Path, settings: dict) -> None:
    p = ui_settings_path(script_dir)
    with UI_SETTINGS_LOCK:
        tmp = p.with_name(p.name + ".tmp")
        tmp.write_text(json.dumps(settings or {}, indent=2), encoding="utf-8")
        os.replace(tmp, p)


def _is_dead_model(value: str) -> bool:
    """Retired-model scrub. Only Gemini ids are in the list, so a qualified id for another provider
    is never scrubbed -- we do not police other vendors' catalogues."""
    provider, model = split_model_id(value)
    if provider and provider != "gemini":
        return False
    return model in DEPRECATED_ANSWER_MODELS


def effective_answer_model(cfg: dict, script_dir: Path) -> str:
    """UI-settings override if present and non-empty, else the config value.

    The value may be a BARE model id (the configured provider answers it -- every pre-v3.15 config
    and ui_settings.json is exactly this) or a qualified `provider:model`.

    BOTH sources are scrubbed against DEPRECATED_ANSWER_MODELS. Scrubbing only the override used to
    leave a retired model in config.json able to wedge every answer with a 404 -- exactly what
    happened when the 2.5 family was withdrawn. The final fallback is the first curated Gemini
    model, so there is always a live model to answer with."""
    ui = load_ui_settings(script_dir)
    override = ui.get("answer_model")
    if isinstance(override, str) and override.strip() and not _is_dead_model(override.strip()):
        chosen = override.strip()
        # Same wedge, different cause: a persisted choice naming a provider with NO key usable
        # blocks every answer until someone edits ui_settings.json by hand. A retired model is
        # already scrubbed here; a keyless provider deserves the same treatment. Warned, not
        # silent, and it starts working again the moment a key is added.
        prov, _m = split_model_id(chosen)
        if prov and prov != DEFAULT_PROVIDER and not resolve_provider_key(prov, cfg, script_dir)[0]:
            _warn_once("keyless_provider_" + prov,
                       f"  ! answer model '{chosen}' needs a {prov} key and none is available -- "
                       f"falling back to the configured default. Add one in Settings.")
        else:
            return chosen
    configured = (get_interview_settings(cfg, script_dir)["answer_model"] or "").strip()
    if configured and not _is_dead_model(configured):
        return configured
    if configured:
        _warn_once("dead_config_model",
                   f"  ! interview.answer_model '{configured}' has been retired by Google -- "
                   f"falling back to {CURATED_ANSWER_MODELS[0]}. Update config.json.")
    return CURATED_ANSWER_MODELS[0]


def answer_model_catalog() -> List[dict]:
    """Everything the UI can offer, qualified and grouped. Gemini ids stay BARE so the value the
    UI persists is byte-identical to what pre-v3.15 wrote."""
    out: List[dict] = []
    for pid, spec in PROVIDERS.items():
        for mid, label, _rank in _ranked_models(pid):
            out.append({"value": qualify_model_id(pid, mid), "label": label,
                        "provider": pid, "group": spec["label"]})
    return out


def valid_answer_model(value: str) -> bool:
    """Accept anything that names a known provider, or a bare non-retired Gemini id.

    Deliberately NOT a whitelist of ids: OpenAI and OpenRouter serve hundreds of models that change
    weekly, and a whitelist would silently reject the one the user actually wants. The provider
    prefix is the part that must be real, because it decides which key and which wire format."""
    value = str(value or "").strip()
    if not value or _is_dead_model(value):
        return False
    provider, model = split_model_id(value)
    if provider:
        return bool(model)
    return bool(model)


def effective_humanize(cfg: dict, script_dir: Path) -> bool:
    return bool(load_ui_settings(script_dir).get("humanize", False))


# Answer detail level -- how much depth/structure the answer carries. See depth_profile().
# 'terse' ("To the point") is the minimalist floor: one or two sentences, nothing else. It is
# deliberately FIRST so it reads as the shortest end of the scale.
VALID_DEPTHS = ("terse", "concise", "balanced", "deep")

# Depth levels offered as one-tap segments on the controls strip. 'deep' is deliberately absent --
# it is rarely used and lives in the Settings panel instead, keeping the strip to the live levers.
STRIP_DEPTHS = ("terse", "concise", "balanced")

DEPTH_LABELS = {
    "terse": "To the point",
    "concise": "Concise",
    "balanced": "Balanced",
    "deep": "Deep",
}


def effective_depth(cfg: dict, script_dir: Path) -> str:
    d = str(load_ui_settings(script_dir).get("depth", "balanced")).lower()
    return d if d in VALID_DEPTHS else "balanced"


# GROUNDING MODE -- how far the answer may travel beyond the vault. The owner's explicit call; the
# default is unchanged behaviour. In EVERY mode the model is still forbidden to claim personal
# hands-on experience that the CONTEXT does not show -- that line never moves. What changes is
# whether a question with NO usable vault backing gets an honest "no experience" reply or a general
# knowledge answer.
#   strict -- today's contract: nothing retrieved => the honest no-experience reply.
#   assist -- vault first; ONLY when the retrieval is 'ungrounded' does it answer from general
#             knowledge, clearly badged so the candidate knows the answer has no vault backing.
#   open   -- answer every question from general knowledge, using any retrieved CONTEXT as a
#             preferred source. This is a content generator; the badge says so on every answer.
VALID_GROUNDING = ("strict", "assist", "open")

GROUNDING_LABELS = {
    "strict": "Vault only",
    "assist": "Vault + AI",
    "open": "AI",
}


def effective_grounding(cfg: dict, script_dir: Path) -> str:
    g = str(load_ui_settings(script_dir).get("grounding", "strict")).lower()
    return g if g in VALID_GROUNDING else "strict"


# Answer ALTITUDE -- doer (commands/vendors are the answer) vs lead (checkpoints/categories, suppress
# flags/vendors unless asked). Makes the app role-agnostic instead of baking one JD's altitude in.
VALID_MODES = ("lead", "doer")


def effective_mode(cfg: dict, script_dir: Path) -> str:
    m = str(load_ui_settings(script_dir).get("mode", "lead")).lower()
    return m if m in VALID_MODES else "lead"


# Interview ROLE -- an OPTIONAL discipline lens. "general" is the default and appends nothing, so
# the app behaves exactly as it did before this feature existed. A role only steers WHICH
# CONTEXT-supported material gets foregrounded and how it is framed; like the JD, it never licenses
# a fact that isn't in the retrieved CONTEXT.
VALID_ROLES = ("general", "architect", "security", "grc")

ROLE_LABELS = {
    "general": "General (no role lens)",
    "architect": "Solution Architect",
    "security": "Security / Cyber",
    "grc": "GRC / Audit",
}


def effective_role(cfg: dict, script_dir: Path) -> str:
    r = str(load_ui_settings(script_dir).get("role", "general")).lower()
    return r if r in VALID_ROLES else "general"


# Display/cue toggles. These were localStorage-only, which meant they were the ONE part of the
# Settings panel that could not mirror between the laptop and the phone -- the app is no longer
# single-client, so they are persisted server-side like every other setting. Keys map to the
# overlay's toggles; the defaults preserve the previous client-side defaults exactly.
UI_FLAG_DEFAULTS = {"show_sources": False, "convo_context": True,
                    "opener": False, "scope_cue": False}


def effective_ui_flags(cfg: dict, script_dir: Path) -> dict:
    ui = load_ui_settings(script_dir)
    return {k: bool(ui.get(k, d)) for k, d in UI_FLAG_DEFAULTS.items()}


def effective_hangover_ms(cfg: dict, script_dir: Path) -> int:
    """Interviewer-pause duration (ms) that finalizes an utterance -- UI override else config."""
    ui = load_ui_settings(script_dir).get("silence_hangover_ms")
    if isinstance(ui, (int, float)) and ui > 0:
        return int(ui)
    return get_interview_settings(cfg, script_dir)["silence_hangover_ms"]


# Phrases that mean the interviewer explicitly wants steps / commands / implementation detail.
# Only these let CONCISE break out of spoken-prose form (see depth_profile). Deliberately tight --
# a plain design question ("how would you connect X to Y") must NOT trigger it.
_DETAIL_REQUEST_PATTERNS = [
    r"\bwalk me through\b", r"\bstep[\s-]?by[\s-]?step\b", r"\bwhat(?:'s| are| is)? the steps\b",
    r"\bexact steps\b", r"\bimplementation steps\b", r"\bthe steps\b",
    r"\bin (?:more )?detail\b", r"\bmore detail(?:s|ed)?\b", r"\belaborate\b", r"\bdeep[\s-]?dive\b",
    r"\bhow exactly\b", r"\bexactly how\b", r"\bshow me (?:the |how)\b", r"\bgo deeper\b",
    r"\bwhich commands?\b", r"\bwhat commands?\b", r"\bthe commands?\b", r"\bcommand line\b",
    r"\bsyntax\b", r"\bcli\b", r"\bcode\b", r"\bconfig(?:uration)? (?:file|snippet)\b",
    r"\btell me more\b", r"\bbreak (?:it|that) down\b",
]
_DETAIL_REQUEST_RE = re.compile("|".join(_DETAIL_REQUEST_PATTERNS), re.I)


def wants_detail(question: str) -> bool:
    """True when the interviewer explicitly asked for steps/commands/implementation detail.
    Evaluated on the ORIGINAL question (what was actually asked), not the condensed query."""
    return bool(_DETAIL_REQUEST_RE.search(question or ""))


# An interviewer asking "how would you do X" wants the ANSWER, not a disclosure of what the
# candidate has or hasn't operated. Volunteering "I haven't done this hands-on, but..." on every
# out-of-experience question reads as a running apology. So the disclosure is GATED: it fires only
# when the interviewer actually probes experience. When they do, the answer must be plainly honest
# -- this narrows WHEN provenance is spoken, it never licenses claiming experience that is absent.
_EXPERIENCE_PROBE_PATTERNS = [
    r"\bhave you (?:ever |actually |personally )?(?:worked|work|done|used|use|run|ran|built|build"
    r"|deployed|deploy|configured|configure|managed|manage|implemented|implement|administered"
    r"|supported|migrated|designed)\b",
    r"\bdo you have\b[^?]{0,40}\b(?:experience|exposure|background|hands[- ]?on)\b",
    r"\bhands[- ]?on experience\b",
    r"\b(?:what|how much|how many years)\b[^?]{0,40}\bexperience\b",
    r"\byour experience (?:with|in|of)\b",
    r"\bhave you (?:ever )?(?:been|had)\b[^?]{0,30}\b(?:responsible|exposure|experience)\b",
    r"\bin (?:a )?production\b[^?]{0,40}\b(?:have you|did you|do you)\b",
    r"\b(?:did|have) you\b[^?]{0,40}\bin production\b",
    r"\bare you (?:certified|experienced)\b",
    r"\bhow long have you\b",
    r"\bever (?:worked|used|done|run|deployed|configured|managed) (?:with|on|in)?\b",
]
_EXPERIENCE_PROBE_RE = re.compile("|".join(_EXPERIENCE_PROBE_PATTERNS), re.I)


def asks_about_experience(question: str) -> bool:
    """True when the interviewer DIRECTLY probes hands-on experience ("do you have hands-on
    experience with X", "have you done that in production"). Local regex, ~0ms, same cheap-signal
    approach as wants_detail(). Gates the provenance disclosure, nothing else."""
    return bool(_EXPERIENCE_PROBE_RE.search(question or ""))


# ============================================================
# QUESTION CLASSIFICATION (local, ~0ms; foundation for the opener strip + Phase-3/4 doctrine)
# ============================================================
# A regex classifier that labels the interviewer's question into one response class. It is LOCAL
# (no API call) and ADVISORY -- the opener strip reads it to decide whether/what to prompt, and the
# human always decides. A question can match several buckets, so the precedence order in
# classify_question() is deliberate. This is the same cheap-signal approach as wants_detail().

QUESTION_CLASSES = ("direct_factual", "behavioural", "ambiguous", "design", "scenario")

# Behavioural: "tell me about a time you..." -- distinctive openers, checked first.
_CLASS_BEHAVIOURAL_RE = re.compile(
    r"\btell me about a time\b|\ba time when you\b|\bhave you ever\b"
    r"|\bdescribe (?:a|your) (?:\w+ )?(?:time|situation|scenario|challenge|project|failure|conflict|decision|problem)\b"
    r"|\bgive (?:me )?an example of (?:a )?(?:time|when|situation)\b"
    r"|\bwalk me through a (?:time|project|situation|challenge)\b"
    r"|\btell me about (?:a|your) (?:\w+ )?(?:project|challenge|failure|conflict|decision|accomplishment)\b", re.I)

# Ambiguous / high-stakes: security incidents & recovery that cannot be answered cold -- these
# MERIT clarifying questions, so they outrank the plain scenario bucket.
_CLASS_AMBIGUOUS_RE = re.compile(
    r"\bransomware\b|\bmalware\b|\bbreach(?:ed)?\b|\bhacked\b|\bcompromis(?:e|ed|ing)\b"
    r"|\binfect(?:ed|ion)?\b|\bexfiltrat|\bdata (?:loss|breach)\b|\bdisaster\b|\bincident\b"
    r"|\bhow long (?:would|will|does|to)\b.*\b(?:recover|restore|back up|back online)\b"
    r"|\bencrypted (?:by|our|the|all)\b", re.I)

# Design / architecture: "how would you design/architect/connect/scale X".
_CLASS_DESIGN_RE = re.compile(
    r"\bhow would you (?:design|architect|build|structure|set up|connect|scale|deploy|migrate)\b"
    r"|\bdesign (?:a|an|the|me)\b|\barchitect (?:a|an|the)\b|\bhow do you scale\b"
    r"|\bhow would you approach (?:building|designing|scaling)\b", re.I)

# Direct/factual: short lookups. Tight, so it does not swallow scenario/design questions.
_CLASS_FACTUAL_RE = re.compile(
    r"^\s*(?:what(?:'s| is| are)?|which|who|when|where|name the|define)\b"
    r"|\bequivalent (?:of|to|in|for)\b|\bstands? for\b|\bdifference between\b"
    r"|\bwhat does\b.*\bdo\b|\bwhat(?:'s| is)? the (?:port|default|purpose|command) (?:for|of)\b", re.I)

# Scenario / troubleshooting: something is broken/slow and you must investigate.
_CLASS_SCENARIO_RE = re.compile(
    r"\bhow (?:do|would) you (?:resolve|fix|troubleshoot|diagnose|handle|investigate|debug|deal with|approach)\b"
    r"|\b(?:is|are|keeps?|gets?)\b.*\b(?:slow|down|failing|timing out|unreachable|crashing)\b"
    r"|\bsometimes\b.*\b(?:times? out|fails?|slow|loads?)\b|\bwon'?t (?:start|boot|load|connect|respond)\b"
    r"|\busers? (?:report|complain|can'?t|are unable)\b|\bnot working\b|\bkeeps? (?:crashing|failing|restarting)\b"
    r"|\bhow (?:do|would) you (?:respond to|recover)\b", re.I)

# Concept questions: "why does X", "how does X work", "explain X", "describe X". They matched no class
# and fell through to 'scenario', whose doctrine orders a first-person APPROACH voice, so a concept
# came back narrated as if the candidate were the system ("By requiring a PIN first, I'm narrowing the
# search"; BGP as "I check the weight"). Measured on 12 concept questions: 9 got that order (28 Sep
# 2026). Only when the question does not address the candidate: "how do you...", "why would you..."
# are about the candidate, and keep the voice. Checked AFTER the scenario patterns, so a real
# troubleshooting question that starts with "why" ("why is the VM slow?") stays a scenario.
_CLASS_CONCEPT_RE = re.compile(
    r"^\s*(?:why\b|how (?:does|do|is|are|can)\b|explain\b|describe\b|what happens\b)", re.I)
_ADDRESSES_CANDIDATE_RE = re.compile(r"\b(?:you|your|yours|yourself)\b", re.I)


# ============================================================
# DOCTRINE DISPATCH (v3.0 Phase 4) — per-class SHAPE/VOICE + per-mode ALTITUDE
# ============================================================
# Appended to the answer prompt. Fixes the altitude problem a mock interviewer flagged for three sessions
# (name the checkpoint not the flag; the category not the vendor, unless asked) role-agnostically
# via the doer/lead mode, and gives scenario/design/ambiguous answers a first-person APPROACH voice
# instead of the neutral-textbook reading the balance check exposed. Three orthogonal axes:
# depth = how long · class = what shape/voice · mode = what altitude. Precedence for altitude:
# an explicit "walk me through the commands" (detail_requested) > mode default.
_DOCTRINE_SHAPE = {
    "scenario": "SHAPE: answer as the ORDER you would investigate in (the checkpoints), and name the "
                "coordination / ownership step -- who you would bring in. Restore-service-first where it applies.",
    "ambiguous": "SHAPE: this is high-stakes and under-specified -- lead by naming the one or two things "
                 "you would establish first, then give the shape of your approach.",
    "design": "SHAPE: state your key assumptions, then the approach and the main trade-off.",
}
_APPROACH_CLASSES = ("scenario", "ambiguous", "design")


# A role is a LENS, not a licence. It changes which CONTEXT-supported material leads and how it is
# framed -- exactly the bounded steering the JD already does. Deliberately short: long prompts lose
# to retrieval gravity (the reverted item-4 experiment), so each is a couple of concrete rules.
ROLE_GUIDANCE = {
    "architect": (
        "ROLE LENS -- SOLUTION ARCHITECT. Lead with the REQUIREMENTS and CONSTRAINTS the answer turns "
        "on, then the design, then the TRADE-OFF you are accepting and what it costs (e.g. consistency "
        "vs availability, cost vs latency, simplicity vs scale). Name the failure mode the design "
        "guards against. Prefer data flow, scaling limits and boundaries over product configuration. "
        "State an assumption explicitly rather than silently picking one."
    ),
    "security": (
        "ROLE LENS -- SECURITY. Lead with the RISK: what is exposed, the blast radius, and what an "
        "attacker gains. Then the control, framed as detect / contain / recover, and where it sits in "
        "defence-in-depth. Prefer least-privilege and reduce-the-attack-surface reasoning. Say what "
        "you would preserve for forensics before changing anything."
    ),
    "grc": (
        "ROLE LENS -- GRC / AUDIT. Lead with the CONTROL OBJECTIVE (the outcome required), then the "
        "control that achieves it, then how you would EVIDENCE it to an auditor -- what artefact, "
        "produced by whom, covering what period. Name the risk owner and who ACCEPTS residual risk "
        "(the business, not security). Where a framework applies, name it precisely. Prefer "
        "design-vs-operating-effectiveness reasoning over tooling."
    ),
}


def role_block(role: str) -> str:
    """Optional per-role lens. '' for 'general', so an unset role is byte-identical to pre-Roles."""
    return ROLE_GUIDANCE.get((role or "general").lower(), "")


def doctrine_block(qclass: str, altitude: str, detail_requested: bool) -> str:
    """The per-class + per-mode doctrine appended to a content answer prompt. '' for direct_factual
    /behavioural (answer immediately / tell the vault story -- no doctrine needed)."""
    parts: List[str] = []
    if qclass in _APPROACH_CLASSES:
        parts.append("VOICE: answer in the FIRST PERSON as the approach you would take (\"I'd start by "
                     "...\"). This is your reasoning, NOT a claim of hands-on experience (that is shown "
                     "separately by the badge).")
        parts.append(_DOCTRINE_SHAPE[qclass])
    if detail_requested:
        parts.append("ALTITUDE: the interviewer explicitly asked for detail -- you MAY name the exact "
                     "commands, flags, and tools from the CONTEXT.")
    elif altitude == "doer":
        parts.append("ALTITUDE: this is a HANDS-ON role -- name the exact commands, flags, file paths, "
                     "tools and product names from the CONTEXT; the specifics are the answer.")
    else:  # lead
        parts.append("ALTITUDE: speak as a LEAD, not a doer. Name the CHECKPOINT and the CATEGORY, NOT "
                     "the exact command, flag, file path, or vendor product -- EVEN IF the CONTEXT "
                     "contains them. Say \"check whether the DNS service is running and its resolver "
                     "configuration\", NOT \"/etc/resolv.conf\" or \"systemd-resolved status\"; say "
                     "\"a SIEM\", NOT \"QRadar\". If they want the commands or the product name they'll "
                     "ask. Exception: if the active job description names a specific product, you may name it.")
    return ("\n\n" + "\n".join(parts)) if parts else ""


def classify_question(question: str) -> str:
    """Label the question into one of QUESTION_CLASSES. Local, ~0ms, advisory.
    Precedence: behavioural > ambiguous (high-stakes) > design > direct_factual > scenario > concept.
    Unmatched defaults to 'scenario' -- it earns a neutral scoping opener, never a confident stall
    in front of a one-line factual answer (that miscue is the one we most want to avoid). A concept
    question that matched nothing else and does not address the candidate is 'direct_factual', so it
    gets a plain explanation instead of the first-person approach voice (see _CLASS_CONCEPT_RE)."""
    q = question or ""
    if _CLASS_BEHAVIOURAL_RE.search(q):
        return "behavioural"
    if _CLASS_AMBIGUOUS_RE.search(q):
        return "ambiguous"
    if _CLASS_DESIGN_RE.search(q):
        return "design"
    if _CLASS_FACTUAL_RE.search(q):
        return "direct_factual"
    if _CLASS_SCENARIO_RE.search(q):
        return "scenario"
    if _CLASS_CONCEPT_RE.search(q) and not _ADDRESSES_CANDIDATE_RE.search(q):
        return "direct_factual"
    return "scenario"


def depth_profile(depth: str, detail_requested: bool = False) -> dict:
    """Detail level -> retrieval breadth (top_k), output budget, and a guidance block appended to
    the grounded/adjacent system prompt. Ranges from rapid-fire to a NotebookLM-like structured
    brief WITHOUT ever loosening grounding (all depths stay CONTEXT-only, first person).

    CONCISE is spoken PROSE by default (an interview answer is said out loud, not read as bullets).
    It escalates to structure + exact commands ONLY when the interviewer explicitly asked for them
    (detail_requested), so the dropdown doesn't have to be touched mid-interview.

    TERSE is the minimalist floor: the single direct answer in one or two sentences, named
    specifically, then stop. Everything else waits for the interviewer to ask a follow-up."""
    if depth == "terse" and not detail_requested:
        return {"top_k": 6, "max_tokens": 220, "guidance": (
            "\n\nDETAIL LEVEL -- TO THE POINT (this is the STRICTEST instruction in this prompt; "
            "it overrides every shape, voice, altitude and role instruction that follows or "
            "precedes it):\n"
            "- Answer in ONE sentence. TWO only if the answer is genuinely meaningless without the "
            "second. Roughly 15-40 words TOTAL.\n"
            "- Give the DIRECT answer only: name the specific mechanism, technology, or action from "
            "the CONTEXT that actually answers the question. That name IS the answer.\n"
            "- NO preamble, NO restating the question, NO assumptions list, NO trade-off discussion, "
            "NO caveats, NO 'it depends', NO bullets, NO headings, NO summary, NO offer to expand.\n"
            "- Do NOT explain WHY unless the question asked why. Do NOT list steps unless the "
            "question asked for steps.\n"
            "- The interviewer will ask a follow-up if they want more. Withholding detail here is "
            "CORRECT behaviour, not an incomplete answer.\n"
            "Example of the required register -- Q: 'How would you migrate a live VLAN subnet to an "
            "NSX overlay with no downtime?' A: 'I'd use an NSX L2 bridge, which puts the VLAN and "
            "the Geneve segment in one broadcast domain so workloads move without changing IPs.'")}
    if depth == "concise" or depth == "terse":
        if detail_requested:
            return {"top_k": 12, "max_tokens": 2000, "guidance": (
                "\n\nDETAIL LEVEL -- CONCISE, BUT THE INTERVIEWER EXPLICITLY ASKED FOR DETAIL: "
                "Break out of prose form for this one answer. Give a single short spoken lead-in "
                "sentence, then the concrete detail as ordered bullets or 2-3 '### ' mini-sections, "
                "including the EXACT commands, flags, service names and steps AS THEY APPEAR in the "
                "CONTEXT. Be specific and sequential like a senior engineer walking someone through "
                "it. Never invent a command, flag, or step that is not in the CONTEXT.")}
        return {"top_k": 6, "max_tokens": 500, "guidance": (
            "\n\nDETAIL LEVEL -- CONCISE: Reply as ONE flowing spoken paragraph of about 80-100 "
            "words (~25-35 seconds out loud). Write it exactly as the candidate would SAY it: "
            "NO bullet points, NO numbered lists, NO headings, NO code blocks or command syntax. "
            "You MAY bold the key technical terms. Name the specific technologies from the CONTEXT "
            "naturally inside the sentences. Cover the 2-3 most important points and STOP -- do not "
            "add a summary, do not restate anything, do not pad to fill space.")}
    if depth == "deep":
        return {"top_k": 12, "max_tokens": 3000, "guidance": (
            "\n\nDETAIL LEVEL -- DEEP: Open with a 2-3 sentence spoken answer the candidate can say "
            "out loud, THEN give a structured brief: 2-4 short headed mini-sections (use '### ' "
            "headings) or grouped bullets that pull the SPECIFIC technologies, exact steps, named "
            "tools, and distinctions that appear in the CONTEXT (e.g. exact service names, commands, "
            "and the difference between related options). Be concrete and specific like a senior "
            "engineer briefing -- never generic filler. Still first person, still ONLY from the CONTEXT.")}
    return {"top_k": 8, "max_tokens": 1600, "guidance": (  # balanced (default)
        "\n\nDETAIL LEVEL -- BALANCED: A ~2-sentence spoken opener, then 4-5 specific bullets that "
        "NAME the actual tools, commands, and steps from the CONTEXT (not generic statements). "
        "Concrete over vague; still scannable enough to say out loud.")}


def settings_payload(cfg: dict, script_dir: Path) -> dict:
    """Shape returned by GET/POST /settings."""
    model = effective_answer_model(cfg, script_dir)
    catalog = answer_model_catalog()
    if model not in [m["value"] for m in catalog]:
        # A custom id the user typed (OpenAI/OpenRouter serve far more than any list can hold).
        prov, _m = split_model_id(model)
        catalog.insert(0, {"value": model, "label": model + "  (custom)",
                           "provider": prov or DEFAULT_PROVIDER,
                           "group": (PROVIDERS.get(prov or DEFAULT_PROVIDER) or {}).get("label", "Custom")})
    provider, _ = resolve_answer(cfg, script_dir)
    return {
        "answer_model": model,
        # `models` stays a flat list of ids: the pre-v3.15 shape, so an older client still works.
        "models": [m["value"] for m in catalog],
        "model_catalog": catalog,
        "answer_provider": provider,
        "providers": providers_public(cfg, script_dir),
        "humanize": effective_humanize(cfg, script_dir),
        "depth": effective_depth(cfg, script_dir),
        "depths": list(VALID_DEPTHS),
        # Which depths get a one-tap strip segment, and their display names. 'deep' is intentionally
        # not on the strip (rarely used) -- the Settings dropdown still offers every depth.
        "strip_depths": list(STRIP_DEPTHS),
        "depth_labels": dict(DEPTH_LABELS),
        "grounding": effective_grounding(cfg, script_dir),
        "groundings": [{"id": g, "label": GROUNDING_LABELS.get(g, g)} for g in VALID_GROUNDING],
        "mode": effective_mode(cfg, script_dir),
        "modes": list(VALID_MODES),
        "silence_hangover_ms": effective_hangover_ms(cfg, script_dir),
        "role": effective_role(cfg, script_dir),
        "roles": [{"id": r, "label": ROLE_LABELS.get(r, r)} for r in VALID_ROLES],
        # Optional packages not installed, so Settings can say what is off and how to turn it on.
        "features_off": features_off(),
        **effective_ui_flags(cfg, script_dir),
    }


# ============================================================
# JOB DESCRIPTION (persisted focus-steering text)
# ============================================================

def jd_file_path(cfg: dict, script_dir: Path) -> Path:
    interview = get_interview_settings(cfg, script_dir)
    p = Path(interview["jd_path"])
    if not p.is_absolute():
        p = script_dir / p
    return p


# ============================================================
# PROFILES: position + JD + resume, chosen before an interview (v3.13)
# ============================================================
# The resume used to be INDEXED alongside the vault, which produced a silent-staleness bug that
# cost a real interview: config.json pointed at a new resume, but answers still came from 17
# embedded chunks of the OLD one because the index had not been rebuilt. Nothing in the UI said so.
#
# So the resume is no longer indexed. The ACTIVE resume is injected verbatim into every answer as
# its own labelled block. Consequences, all deliberate:
#   * staleness becomes impossible -- there is no second copy to fall out of date,
#   * switching resumes is instant, which is what makes multiple profiles worth having,
#   * "tell me about yourself" always has the resume, instead of hoping retrieval surfaces it.
# Cost is ~2k tokens/answer (measured on a real 7.9KB resume: $0.0005 per answer at flash-lite
# rates, about 2 cents for a whole interview).
#
# This does NOT loosen grounding. The resume was always a grounded source; only the delivery
# changed, and verbatim is stricter than similarity-retrieved fragments of the same document.
PROFILE_STORE_NAME = "profiles.json"
RESUME_DIR_NAME = "resumes"
MAX_RESUME_CHARS = 24000        # a resume, not a portfolio; keeps the per-answer cost bounded


def _store_path(script_dir: Path) -> Path:
    return script_dir / PROFILE_STORE_NAME


def _resume_dir(script_dir: Path) -> Path:
    d = script_dir / RESUME_DIR_NAME
    d.mkdir(exist_ok=True)
    return d


def load_store(script_dir: Path) -> dict:
    """The profile/resume store. Never raises; a corrupt file degrades to an empty store."""
    p = _store_path(script_dir)
    if p.exists():
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(d, dict):
                d.setdefault("resumes", [])
                d.setdefault("profiles", [])
                d.setdefault("active_profile", "")
                d.setdefault("active_resume", "")
                return d
        except Exception:
            pass
    return {"resumes": [], "profiles": [], "active_profile": "", "active_resume": ""}


def save_store(script_dir: Path, store: dict) -> None:
    p = _store_path(script_dir)
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(store, indent=2, ensure_ascii=False), encoding="utf-8")
    os.replace(tmp, p)


def _new_id(prefix: str) -> str:
    return prefix + secrets.token_hex(5)


def _strip_code_fence(text: str) -> str:
    """Drop a wrapping ```markdown fence the model sometimes adds."""
    t = (text or "").strip()
    if t.startswith("```"):
        lines = t.split(chr(10))
        if lines and lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        t = chr(10).join(lines).strip()
    return t


def _pdf_link_annotations(blob: bytes) -> List[str]:
    """URLs from the PDF's link annotations.

    Worth doing even when the page has no extractable text at all: a CV printed with its text
    converted to outlines still carries working hyperlinks as annotations, and the vision pass
    can only transcribe the VISIBLE label ("LinkedIn"), not the address behind it.
    """
    try:
        import pypdf
    except Exception:
        return []
    out: List[str] = []
    try:
        rd = pypdf.PdfReader(io.BytesIO(blob))
        for pg in rd.pages:
            for a in (pg.get("/Annots") or []):
                try:
                    u = (a.get_object().get("/A") or {}).get("/URI")
                except Exception:
                    continue
                if u and u not in out:
                    out.append(str(u))
    except Exception:
        pass
    return out[:20]


def _pdf_text_local(blob: bytes) -> Tuple[str, int]:
    """(text, pages) via pypdf. Returns '' when the PDF carries no real text layer."""
    import pypdf
    rd = pypdf.PdfReader(io.BytesIO(blob))
    pages = [(p.extract_text() or "") for p in rd.pages]
    return "\n\n".join(t.strip() for t in pages if t.strip()), len(pages)


def _pdf_to_markdown_via_model(blob: bytes, cfg: dict, script_dir: Path) -> Tuple[str, str]:
    """Transcribe a PDF by SIGHT when it has no text layer. Returns (markdown, error).

    Gemini accepts application/pdf directly, so this needs no local renderer and no extra
    dependency. Measured on a real 3-page CV whose text had been flattened to vector outlines
    (0 extractable characters): 8,845 characters of correct markdown in 10s for about 2 cents,
    with all 22 checked sections, employers, dates and certifications intact.
    """
    try:
        settings = get_gemini_settings(cfg)
    except Exception as e:
        return "", f"Cannot reach the model to read this PDF: {str(e)[:120]}"
    prompt = ("Transcribe this CV into clean GitHub-flavoured Markdown. Preserve the real reading "
              "order, headings, bullet lists, and the dates beside each role. Do not summarise, "
              "reorder, invent or omit anything. Output only the markdown.")
    body = {"contents": [{"role": "user", "parts": [
                {"text": prompt},
                {"inline_data": {"mime_type": "application/pdf",
                                 "data": base64.b64encode(blob).decode()}}]}],
            "generationConfig": {"temperature": 0}}
    thinking, out_tokens = _thinking_and_output(SCREENSHOT_MODEL, 8000, 512)
    body["generationConfig"]["maxOutputTokens"] = out_tokens
    if thinking is not None:
        body["generationConfig"]["thinkingConfig"] = thinking
    try:
        r = shared_session().post(
            f"https://generativelanguage.googleapis.com/v1beta/models/{SCREENSHOT_MODEL}:generateContent",
            headers={"x-goog-api-key": settings["api_key"], "Content-Type": "application/json"},
            json=body, timeout=300)
        if r.status_code != 200:
            return "", f"The model could not read that PDF (HTTP {r.status_code})."
        d = r.json()
    except Exception as e:
        return "", f"Reading that PDF failed: {str(e)[:120]}"
    txt = "".join(p.get("text", "") for c in d.get("candidates", [])
                  for p in c.get("content", {}).get("parts", []))
    txt = re.sub(r"^```[a-z]*\n|\n```$", "", txt.strip())
    return txt, ("" if txt.strip() else "The model returned nothing for that PDF.")


# How much real text a PDF must yield per page before we trust the local extractor. A CV page has
# hundreds of characters; the failure this guards against produced 99 characters across a whole
# page -- bullet glyphs and two date strings -- which looked like success to the old code.
PDF_MIN_CHARS_PER_PAGE = 200


def resume_to_markdown(filename: str, blob: bytes, cfg: Optional[dict] = None,
                       script_dir: Optional[Path] = None) -> Tuple[str, str]:
    """Convert an uploaded resume to markdown. Returns (text, warning). Never raises.

    The warning is not decoration. A PDF resume is very often TWO-COLUMN, and every text extractor
    walks it in reading order, interleaving the columns into nonsense -- which, silently accepted,
    would poison every answer. So the caller must show this text for review before it goes live.
    """
    ext = Path(filename or "").suffix.lower()
    if ext in (".md", ".markdown", ".txt", ""):
        return blob.decode("utf-8", "replace"), ""
    if ext == ".pdf":
        try:
            import pypdf  # noqa: F401
        except Exception:
            return "", "PDF support needs the 'pypdf' package (pip install pypdf)."
        try:
            text, pages = _pdf_text_local(blob)
        except Exception as e:
            text, pages = "", 0
            if not cfg:
                return "", f"Could not read that PDF: {str(e)[:120]}"
        # A PDF whose text was flattened to vector outlines (printing "as image", or a scan)
        # yields almost nothing -- pypdf, pdfplumber and PyMuPDF all fail identically, because
        # there is no text to extract. Fall back to reading it by SIGHT.
        thin = len(text) < PDF_MIN_CHARS_PER_PAGE * max(1, pages)
        if thin and cfg is not None:
            md, err = _pdf_to_markdown_via_model(blob, cfg, script_dir or Path("."))
            if md.strip():
                links = _pdf_link_annotations(blob)
                if links:
                    # Outlined text loses the href, so hand the real addresses back separately
                    # rather than leaving the bare domains the vision pass can see.
                    md += "\n\n<!-- links recovered from the PDF -->\n" + \
                          "\n".join("- " + u for u in links)
                return md, ("This PDF had no readable text layer (%d characters across %d pages), "
                            "so it was transcribed by reading the pages. Check names, numbers and "
                            "dates before saving." % (len(text), pages))
            if not text.strip():
                return "", err or ("This PDF has no text layer and could not be read. Export it "
                                   "again without flattening the text, or paste the markdown.")
        if not text.strip():
            return "", ("This PDF has no extractable text -- its text was flattened to outlines or "
                        "scanned. Export it again as real text, or paste the markdown below.")
        return text, ("Extracted from PDF - check the order of the text. Multi-column resumes come "
                      "out interleaved, and headings lose their formatting. Fix it here before saving.")
    if ext in (".docx", ".docm"):
        try:
            import docx
        except Exception:
            return "", "Word support needs the 'python-docx' package (pip install python-docx)."
        try:
            d = docx.Document(io.BytesIO(blob))
        except Exception as e:
            return "", f"Could not read that Word file: {str(e)[:120]}"
        out = []
        for para in d.paragraphs:
            t = (para.text or "").strip()
            if not t:
                continue
            style = (getattr(para.style, "name", "") or "").lower()
            if style.startswith("heading"):
                lvl = "".join(c for c in style if c.isdigit()) or "2"
                out.append("#" * min(6, max(1, int(lvl))) + " " + t)
            elif style.startswith("list"):
                out.append("- " + t)
            else:
                out.append(t)
        for tbl in d.tables:                       # skills grids are often tables
            for row in tbl.rows:
                cells = [c.text.strip() for c in row.cells if c.text.strip()]
                if cells:
                    out.append("- " + " · ".join(cells))
        return "\n\n".join(out), ""
    if ext == ".doc":
        return "", ("Old .doc format is not supported. Save it as .docx or PDF and import again.")
    return "", f"Unsupported file type '{ext}'. Use PDF, Word (.docx), Markdown or plain text."


def resume_text(script_dir: Path, resume_id: str = "") -> Tuple[str, str]:
    """(text, name) for a resume id, or the active one when id is blank. ('','') if none."""
    store = load_store(script_dir)
    rid = resume_id or store.get("active_resume") or ""
    if not rid:
        return "", ""
    for r in store.get("resumes", []):
        if r.get("id") == rid:
            p = _resume_dir(script_dir) / f"{rid}.md"
            try:
                return p.read_text(encoding="utf-8")[:MAX_RESUME_CHARS], r.get("name", "")
            except Exception:
                return "", r.get("name", "")
    return "", ""


def active_profile(script_dir: Path) -> dict:
    store = load_store(script_dir)
    pid = store.get("active_profile") or ""
    for p in store.get("profiles", []):
        if p.get("id") == pid:
            return p
    return {}


def store_public(script_dir: Path) -> dict:
    """What the UI needs: no resume bodies (they can be large), just the metadata + active ids."""
    store = load_store(script_dir)
    return {
        "resumes": [{k: r.get(k) for k in ("id", "name", "chars", "source", "added")}
                    for r in store.get("resumes", [])],
        "profiles": [{k: p.get(k) for k in ("id", "name", "position", "company", "resume_id")}
                     | {"jd_chars": len(p.get("jd") or ""),
                        "jd_preview": " ".join((p.get("jd") or "").split())[:70]}
                     for p in store.get("profiles", [])],
        "active_profile": store.get("active_profile", ""),
        "active_resume": store.get("active_resume", ""),
        "jd_source": store.get("jd_source", ""),
    }


# The resume is the candidate's OWN document, so it is a grounded source -- but a different KIND of
# source from the vault. The vault says what they know in depth; the resume says who they are, where
# they worked and when. Keeping them separate stops the model reciting resume bullets as if they
# were technical recall, and stops it treating an absent resume line as "no experience".
def _resume_block(text: str, name: str = "") -> str:
    if not text.strip():
        return ""
    return (
        "\n\nCANDIDATE PROFILE (the candidate's own CV: verified fact about who they are):\n"
        f"---\n{text.strip()}\n---\n"
        "Use this for identity, employers, roles, dates, education and certifications, and to pick "
        "which of their experiences to lead with. It does NOT license technical claims beyond the "
        "CONTEXT: if the CV names a tool the CONTEXT does not cover, you may say they have worked "
        "with it, but do not invent specifics about how."
    )


# Words that say HOW an interviewer asks about experience, not WHAT they ask about.
_CV_EVIDENCE_STOP = frozenset("""
a an the and or of in on at to for with by from as is are was were be been being have has had do does
did you your ever any some it its this that these those what which who how much many long year years
worked work working works used use using uses built build building deployed deploy deploying configured
configure configuring managed manage managing implemented implement administered administer supported
support migrated migrate designed design ran run running operated operate set setup up done doing
experience experienced exposure background hands hands-on handson production prod live real
environment environments professionally professional personally actually tell me about certified
responsible level large scale enterprise job role company companies team teams kind got get
""".split())


def _evidence_tokens(text: str) -> List[str]:
    words = re.findall(r"[a-z0-9][a-z0-9+#]*(?:[.\-][a-z0-9+#]+)*", (text or "").lower())
    # "dashboards" must meet "dashboard"; applied to both sides, so "tacacs" -> "tacac" still matches.
    return [w[:-1] if len(w) > 3 and w.endswith("s") and not w.endswith("ss") else w for w in words]


def _cv_evidence_block(question: str, resume: str, limit: int = 5) -> str:
    """The CV lines that name what an experience question asks about, each with its section.

    Found 14 Sep 2026: asked "Have you built Power BI dashboards?", every model answered from a
    dashboard PROJECT note and never mentioned the CV job whose bullet reads "Designed and built
    informative Power BI dashboards". The whole CV was in the prompt and the rule already
    said to lead with a job; the line was simply not noticed next to retrieved notes. Prompts lose to
    retrieval gravity in this codebase, so the evidence is put beside the question deterministically.

    Fails safe: when any word of the subject never appears in the CV ("Palo Alto firewalls" on a CV
    with Juniper firewalls), nothing is added, so a look-alike line cannot be offered as evidence."""
    if not (question or "").strip() or not (resume or "").strip():
        return ""
    subject: List[str] = []
    for w in _evidence_tokens(question):
        if w not in _CV_EVIDENCE_STOP and len(w) > 1 and w not in subject:
            subject.append(w)
    if not subject:
        return ""
    cv_words = set(_evidence_tokens(resume))
    if any(w not in cv_words for w in subject):
        return ""
    # One pass: every content line with its heading trail and level.
    entries: List[Tuple[Dict[int, str], str]] = []
    trail: Dict[int, str] = {}
    for raw in resume.splitlines():
        line = raw.strip()
        if not line:
            continue
        m = re.match(r"^(#{1,6})\s+(.*)$", line)
        if m:
            level = len(m.group(1))
            trail = {k: v for k, v in trail.items() if k < level}
            trail[level] = m.group(2).replace("**", "").strip().rstrip(":")
            continue
        entries.append((dict(trail), re.sub(r"^[*\-+]\s+", "", line).replace("**", "").strip()))

    def fmt(tr: Dict[int, str], text: str) -> str:
        if len(text) > 260:
            # Show the part of a long line (a summary paragraph, a skills list) where the subject
            # actually appears, not its first 260 characters.
            at = max(0, text.lower().find(subject[0][:4]) - 100)
            text = ("..." if at else "") + text[at:at + 260] + "..."
        where = " > ".join(v for k, v in sorted(tr.items()) if k > 1)
        return f"- [{where or 'CV'}] {text}"

    direct = [(tr, t) for tr, t in entries if set(subject) <= set(_evidence_tokens(t))][:limit]
    if not direct:
        return ""
    block = ("\n\nWHERE THE CV NAMES THIS (each line with the CV section it sits under). Weigh these "
             "with the levels above and lead with the strongest one:\n"
             + "\n".join(fmt(tr, t) for tr, t in direct))

    # Named ONLY in top-level sections (skills, certifications)? Then the duties that prove it are
    # probably worded differently. Measured the same day: QRadar appears only in the skills list
    # ("Security Operations (SOC/SIEM): IBM QRadar") and certifications, the job's "SOC/SIEM" duties
    # never say QRadar, and showing just the skills lines flipped Gemini from 10/10 yes to 0/2. So
    # add the duties under a deeper heading whose words ALL appear in that skills category label.
    # All, not any: "Cloud & DevOps" must not match "DevOps & Automation", or Terraform (skills only)
    # would borrow unrelated AWS project lines.
    if all(max(tr or {0: ""}) <= 2 for tr, _t in direct):
        labels = [set(_evidence_tokens(t.split(":", 1)[0])) - _CV_EVIDENCE_STOP
                  for _tr, t in direct if ":" in t]
        related: List[str] = []
        for tr, t in entries:
            deepest = max(tr) if tr else 0
            if deepest < 3 or (tr, t) in direct:
                continue
            head = set(_evidence_tokens(tr[deepest])) - _CV_EVIDENCE_STOP
            if head and any(head <= lab for lab in labels):
                related.append(fmt(tr, t))
                if len(related) >= 3:
                    break
        if related:
            block += ("\nDUTIES UNDER A CV HEADING THAT MATCHES ITS SKILLS CATEGORY (these lines do not "
                      "name it). When the skills list names it as the tool for that category and a job "
                      "has these duties, that is IN A JOB:\n" + "\n".join(related))
    return block


def _position_block(position: str) -> str:
    """Deliberately thin. The JD already does focus-steering, and this codebase has repeatedly
    found that stacking prompt axes loses to retrieval gravity, so the position is a label for
    picking the right JD+resume pair -- not a fifth lever fighting depth/class/level/role."""
    p = (position or "").strip()
    return f"\n\nThe candidate is interviewing for: {p}.\n" if p else ""


def load_jd(cfg: dict, script_dir: Path) -> str:
    p = jd_file_path(cfg, script_dir)
    if p.exists():
        try:
            return p.read_text(encoding="utf-8")
        except Exception:
            return ""
    return ""


def save_jd(cfg: dict, script_dir: Path, text: str) -> None:
    p = jd_file_path(cfg, script_dir)
    p.write_text(text or "", encoding="utf-8")


# ============================================================
# TIMING INSTRUMENTATION (permanent, off by default)
# ============================================================
#
# Enabled with --debug-timing or interview.debug_timing. This is deliberately NOT a throwaway
# measurement script: every phase of this work needs to be re-verified against real numbers, so
# the probes live in the code and stay switched off in normal use.

DEBUG_TIMING = False


class StageTimer:
    """Records elapsed times for the stages of one /ask. No-op unless DEBUG_TIMING."""

    __slots__ = ("_t0", "_last", "_marks", "on")

    def __init__(self, on: Optional[bool] = None):
        self.on = DEBUG_TIMING if on is None else on
        self._t0 = time.perf_counter()
        self._last = self._t0
        self._marks: List[Tuple[str, float]] = []

    def mark(self, name: str) -> None:
        if not self.on:
            return
        now = time.perf_counter()
        self._marks.append((name, now - self._last))
        self._last = now

    def report(self, prefix: str = "ask") -> None:
        if not self.on or not self._marks:
            return
        total = time.perf_counter() - self._t0
        parts = "  ".join(f"{n}={d * 1000:.0f}ms" for n, d in self._marks)
        print(f"[timing] {prefix}: {parts}  TOTAL={total * 1000:.0f}ms", flush=True)


# ============================================================
# HTTP SESSION (shared retry policy, mirrors v7/v6)
# ============================================================

def session_with_retries() -> requests.Session:
    session = requests.Session()
    retry = Retry(
        total=4,
        backoff_factor=1.2,
        status_forcelist=[408, 429, 500, 502, 503, 504],
        allowed_methods=["GET", "POST"],
        raise_on_status=False,
    )
    # Pool sized for our concurrency: an /ask can have condense + embed + answer-stream in flight
    # while the STT thread transcribes, all against the same host.
    adapter = HTTPAdapter(max_retries=retry, pool_connections=4, pool_maxsize=16)
    session.mount("https://", adapter)
    return session


# ---- One warm session for the whole process -------------------------------------------------
# Building a Session per request cost a fresh TCP+TLS handshake on EVERY call: ~1.2s per query
# measured, and ~26s on the first cold call. Since embeddings, the condense step, the answer
# stream and STT all hit the same host, one pooled session removes that cost from all of them.
# requests.Session is safe to share here -- we never mutate per-request state on it (no cookies,
# no shared headers), and the HTTPAdapter pools connections per thread-safe urllib3 pools.
_shared_session: Optional[requests.Session] = None
_shared_session_lock = threading.Lock()
_last_api_activity: float = 0.0


def shared_session() -> requests.Session:
    """The process-wide warm session. Also records activity so the keepalive knows when idle."""
    global _shared_session, _last_api_activity
    if _shared_session is None:
        with _shared_session_lock:
            if _shared_session is None:
                _shared_session = session_with_retries()
    _last_api_activity = time.monotonic()
    return _shared_session


def seconds_since_api_activity() -> float:
    return time.monotonic() - _last_api_activity if _last_api_activity else 1e9


def warm_connection(cfg: dict, script_dir: Path, quiet: bool = False) -> bool:
    """Establish the TLS connection to Gemini *before* it is needed.

    A cold first embed measured ~26s. Paying that at startup instead of in front of the first
    interview question turns a catastrophic stall into a non-event. Never raises."""
    try:
        interview = get_interview_settings(cfg, script_dir)
        t0 = time.perf_counter()
        embed_query("warm up", interview["embed_model"],
                    get_gemini_settings(cfg)["api_key"], interview["embed_dim"])
        if not quiet:
            print(f"  Gemini connection warm ({time.perf_counter() - t0:.2f}s)")
        return True
    except Exception as e:
        if not quiet:
            print(f"  Warm-up failed (will connect on first question): {e}")
        return False


class ConnectionKeepalive:
    """Keeps the Gemini connection from going cold between questions while listening is active.

    An interviewer talking for two minutes between questions is completely normal, and a dropped
    idle socket would make the *next* question pay the cold handshake -- a random mid-interview
    stall, worse than a predictable one at startup.

    Measured on this machine (warm baseline 0.39s): idle 30/60/90/120/180s all stayed warm, but
    at 240s the call took 2.19s -- the handshake had recurred. So the socket survives at least
    3 minutes and is gone by 4, and this keepalive is LOAD-BEARING for a long interviewer
    monologue, not just insurance.

    idle_seconds must stay comfortably below that death window. At 120s (checked every 5s) the
    real maximum idle is ~125s, well inside the verified-safe 180s. It fires only after genuine
    idle time, so an active Q&A costs nothing at all."""

    def __init__(self, cfg: dict, script_dir: Path, idle_seconds: float = 120.0):
        self.cfg = cfg
        self.script_dir = script_dir
        self.idle_seconds = idle_seconds
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None

    def start(self) -> None:
        if self._thread is not None and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        self._thread = None

    def _run(self) -> None:
        while not self._stop.wait(5.0):
            try:
                if seconds_since_api_activity() >= self.idle_seconds:
                    warm_connection(self.cfg, self.script_dir, quiet=True)
            except Exception:
                pass  # never let the keepalive kill the server


# ============================================================
# INGESTION + HEADING-AWARE CHUNKING
# ============================================================

SKIP_DIR_NAMES = {".obsidian", ".trash", ".git", "templates", "template", ".stfolder"}
HEADING_RE = re.compile(r"^(#{1,6})\s+(.*)$")


def pack_paragraphs(body: str, max_chars: int) -> List[str]:
    paras = [p.strip() for p in re.split(r"\n\s*\n", body) if p.strip()]
    chunks: List[str] = []
    cur = ""
    for p in paras:
        if len(p) > max_chars:
            if cur:
                chunks.append(cur)
                cur = ""
            for i in range(0, len(p), max_chars):
                chunks.append(p[i:i + max_chars])
            continue
        if cur and len(cur) + 2 + len(p) > max_chars:
            chunks.append(cur)
            cur = p
        else:
            cur = p if not cur else cur + "\n\n" + p
    if cur:
        chunks.append(cur)
    return chunks


def chunk_markdown(text: str, source: str, max_chars: int = 1500) -> List[Dict[str, str]]:
    """Split a note into heading-aware chunks, preserving the heading trail."""
    stack: List[Tuple[int, str]] = []
    buf: List[str] = []
    out: List[Dict[str, str]] = []
    in_fence = False

    def trail() -> str:
        return " > ".join(t for _, t in stack)

    def flush() -> None:
        body = "\n".join(buf).strip()
        buf.clear()
        if not body:
            return
        tr = trail()
        for piece in pack_paragraphs(body, max_chars):
            out.append({"source": source, "heading": tr, "text": piece})

    for line in text.split("\n"):
        stripped = line.strip()
        if stripped.startswith("```"):
            in_fence = not in_fence
            buf.append(line)
            continue
        m = HEADING_RE.match(stripped) if not in_fence else None
        if m:
            flush()
            level = len(m.group(1))
            title = m.group(2).strip()
            while stack and stack[-1][0] >= level:
                stack.pop()
            stack.append((level, title))
        else:
            buf.append(line)
    flush()
    return out


# ============================================================
# VAULT PROVENANCE TIERS (v3.0)
# ============================================================
# Each note is tagged with how the owner actually knows its content, so the answer can be honest
# about hands-on vs studied vs reference. Folder-first (169 files, per-file tagging is out); a
# frontmatter `tier:` on a note overrides its folder. Claim-strength order used by the ceiling gate:
#   production > project > study > reference
VALID_TIERS = ("production", "project", "study", "reference")
TIER_ORDER = {"production": 3, "project": 2, "study": 1, "reference": 0}
DEFAULT_TIER = "study"

_FRONTMATTER_TIER_RE = re.compile(
    r"\A﻿?---\s*\n(.*?)\n---\s*\n", re.S)          # a leading YAML frontmatter block
_TIER_LINE_RE = re.compile(r"^\s*tier\s*:\s*([A-Za-z]+)\s*$", re.M)


def frontmatter_tier(text: str) -> Optional[str]:
    """Return a valid tier declared in a note's leading frontmatter, else None."""
    m = _FRONTMATTER_TIER_RE.match(text or "")
    if not m:
        return None
    t = _TIER_LINE_RE.search(m.group(1))
    if not t:
        return None
    val = t.group(1).strip().lower()
    return val if val in VALID_TIERS else None


def resolve_folder_tier(rel_folder_parts: Tuple[str, ...], tier_map: dict) -> str:
    """Deepest matching folder path in tier_map wins; case-insensitive; `_default` else DEFAULT_TIER.
    rel_folder_parts is the file's parent folder, relative to the vault root, split into segments."""
    best = str(tier_map.get("_default", DEFAULT_TIER)).lower()
    if best not in VALID_TIERS:
        best = DEFAULT_TIER
    best_depth = 0
    lower_parts = [p.lower() for p in rel_folder_parts]
    for key, tier in tier_map.items():
        if key == "_default":
            continue
        tier = str(tier).lower()
        if tier not in VALID_TIERS:
            continue
        key_parts = [k.lower() for k in key.replace("\\", "/").split("/") if k]
        if not key_parts or len(key_parts) > len(lower_parts):
            continue
        if lower_parts[:len(key_parts)] == key_parts and len(key_parts) > best_depth:
            best_depth = len(key_parts)
            best = tier
    return best


def tier_for_file(path: Path, vault_dir: Optional[Path], tier_map: dict,
                  text: str, resume_path: str = "") -> str:
    """Tier for one file: frontmatter override > folder map. The resume is always `production`
    (it IS the candidate's lived experience). Files outside the vault default conservatively."""
    fm = frontmatter_tier(text)
    if fm:
        return fm
    if resume_path and str(path) == str(Path(resume_path)):
        return "production"
    if vault_dir is not None:
        try:
            rel = path.parent.relative_to(vault_dir)
            return resolve_folder_tier(rel.parts, tier_map)
        except Exception:
            pass
    return str(tier_map.get("_default", DEFAULT_TIER)).lower()


def _excluded(path: Path, exclude_lower: set) -> Optional[str]:
    """Return the exclusion token that drops this path (any path segment, case-insensitive), else
    None. Covers SKIP_DIR_NAMES (case-insensitively — the old check was case-sensitive, so a capital
    `Templates/` leaked in) plus the user's vault_exclude list."""
    parts_lower = [p.lower() for p in path.parts]
    for token in exclude_lower:
        if token in parts_lower:
            return token
    return None


def collect_source_files(interview: dict, script_dir: Path) -> List[Path]:
    files: List[Path] = []
    exclude_lower = {s.lower() for s in SKIP_DIR_NAMES} | {
        s.lower() for s in interview.get("vault_exclude", [])}

    vault = interview["vault_path"].strip()
    if vault:
        vault_dir = Path(vault)
        if not vault_dir.exists():
            raise FileNotFoundError(
                f"interview.vault_path does not exist: {vault_dir}\n"
                f"Edit config.json and set it to your Obsidian vault folder."
            )
        for p in sorted(vault_dir.rglob("*.md")):
            if _excluded(p, exclude_lower):   # case-insensitive skip + vault_exclude
                continue
            files.append(p)

    # The resume is DELIBERATELY not indexed any more (v3.13). It is injected verbatim into
    # every answer from the profile store instead. Indexing it meant a resume change did
    # nothing until the next --build-index, with nothing in the UI saying so -- which is
    # exactly how a real interview got an introduction built from a months-old CV.

    if not files:
        raise SetupError(
            "No notes found to index." + chr(10) +
            "  Set interview.vault_path in config.json to a folder containing .md files."
        )
    return files


def build_chunks(interview: dict, script_dir: Path) -> List[Dict[str, str]]:
    all_chunks: List[Dict[str, str]] = []
    vault = interview.get("vault_path", "").strip()
    vault_dir = Path(vault) if vault else None
    tier_map = interview.get("vault_tiers", {})
    resume_path = interview.get("resume_path", "")
    for f in collect_source_files(interview, script_dir):
        try:
            text = f.read_text(encoding="utf-8", errors="ignore")
        except Exception as e:
            print(f"  skip {f}: {e}")
            continue
        # Tier is derived per FILE (frontmatter override > folder map). Attached to every chunk so
        # it survives retrieval; NOT part of chunk_id, so it never triggers a re-embed.
        tier = tier_for_file(f, vault_dir, tier_map, text, resume_path)
        display = f.stem
        for ch in chunk_markdown(text, source=display):
            ch["path"] = str(f)
            ch["tier"] = tier
            all_chunks.append(ch)
    return all_chunks


def chunk_id(embed_model: str, ch: Dict[str, str]) -> str:
    h = hashlib.sha1()
    h.update(embed_model.encode("utf-8"))
    h.update(b"\x00")
    h.update(ch["source"].encode("utf-8"))
    h.update(b"\x00")
    h.update(ch["heading"].encode("utf-8"))
    h.update(b"\x00")
    h.update(ch["text"].encode("utf-8"))
    return h.hexdigest()


def embed_input(ch: Dict[str, str]) -> str:
    if ch.get("heading"):
        return f"{ch['source']} > {ch['heading']}\n{ch['text']}"
    return f"{ch['source']}\n{ch['text']}"


# ============================================================
# GEMINI EMBEDDINGS
# ============================================================

GEMINI_BASE = "https://generativelanguage.googleapis.com/v1beta"


def _embed_one(session: requests.Session, text: str, model: str, api_key: str,
               task_type: str, dim: int) -> List[float]:
    endpoint = f"{GEMINI_BASE}/models/{model}:embedContent?key={api_key}"
    body = {
        "model": f"models/{model}",
        "content": {"parts": [{"text": text}]},
        "taskType": task_type,
    }
    if dim:
        body["outputDimensionality"] = dim
    resp = session.post(endpoint, json=body, timeout=60)
    if resp.status_code >= 400:
        raise RuntimeError(_api_error("embed", resp.status_code, resp.text))
    return resp.json().get("embedding", {}).get("values", [])


# $ per 1M input tokens for gemini-embedding-001, and the chars-per-token ratio measured on this
# vault (12.2M chars ~= 3.06M tokens). Only used to print a running estimate, never to bill.
EMBED_USD_PER_MTOK = 0.15
EMBED_CHARS_PER_TOK = 4.0

# How often the partial build is written to disk. A full vault build is one HTTP request per chunk
# over roughly an hour; before this, a dropped connection or a Ctrl+C threw away every vector paid
# for, because the index was written once at the very end. 250 chunks is ~1 minute of work.
CHECKPOINT_EVERY = 250


def checkpoint_path(script_dir: Path) -> Path:
    return script_dir / (_INDEX_BASENAME[:-5] + ".partial.json")


def _save_checkpoint(script_dir: Path, model: str, rows: List[dict]) -> None:
    """Write embedded-so-far rows to a SEPARATE file, never over the live index.

    Deliberately not `save_index`: a partial index at the real path would be served by --serve as
    though it were complete, silently answering from a fraction of the vault. This file is only ever
    read back as an extra CACHE source by the next build, and deleted once the build succeeds."""
    p = checkpoint_path(script_dir)
    tmp = p.with_suffix(".json.tmp")
    try:
        tmp.write_text(json.dumps({"embed_model": model, "chunks": rows}), encoding="utf-8")
        os.replace(tmp, p)
    except Exception as e:
        print(f"  (could not write checkpoint: {e})")


def _load_checkpoint(script_dir: Path, model: str) -> Dict[str, dict]:
    p = checkpoint_path(script_dir)
    if not p.exists():
        return {}
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
        if data.get("embed_model") != model:
            return {}
        out = {r["id"]: r for r in data.get("chunks", []) if r.get("vector")}
        if out:
            print(f"  Resuming: {len(out)} vectors recovered from an interrupted build "
                  f"({p.name}).")
        return out
    except Exception as e:
        print(f"  (ignoring unreadable checkpoint {p.name}: {e})")
        return {}


def _fmt_eta(seconds: float) -> str:
    seconds = max(0, int(seconds))
    if seconds < 90:
        return f"{seconds}s"
    if seconds < 3600:
        return f"{seconds // 60}m {seconds % 60:02d}s"
    return f"{seconds // 3600}h {(seconds % 3600) // 60:02d}m"


def embed_documents(texts: List[str], model: str, api_key: str, dim: int = 768,
                    on_progress=None) -> List[List[float]]:
    """Embed document texts one at a time (gemini-embedding-001 exposes embedContent,
    not a synchronous batch method). Returns one vector per input, in order.

    `on_progress(count, vectors_so_far)` is called every CHECKPOINT_EVERY chunks so the caller can
    persist partial work. Progress lines carry a rate, an ETA and a running cost, because the only
    thing a user watching a silent hour-long build actually wants to know is whether it is stuck."""
    session = shared_session()
    vectors: List[List[float]] = []
    total = len(texts)
    t0 = time.perf_counter()
    chars = 0
    for i, t in enumerate(texts, 1):
        vectors.append(_embed_one(session, t, model, api_key, "RETRIEVAL_DOCUMENT", dim))
        chars += len(t)
        if i % 25 == 0 or i == total:
            elapsed = time.perf_counter() - t0
            rate = i / elapsed if elapsed > 0 else 0
            eta = (total - i) / rate if rate > 0 else 0
            usd = (chars / EMBED_CHARS_PER_TOK) / 1_000_000 * EMBED_USD_PER_MTOK
            print(f"  embedded {i}/{total} chunks  ({rate:.1f}/s, ~{_fmt_eta(eta)} left, "
                  f"~${usd:.3f} so far)", flush=True)
        if on_progress is not None and (i % CHECKPOINT_EVERY == 0 or i == total):
            on_progress(i, vectors)
    return vectors


def embed_query(text: str, model: str, api_key: str, dim: int = 768) -> List[float]:
    session = shared_session()
    return _embed_one(session, text, model, api_key, "RETRIEVAL_QUERY", dim)


# ============================================================
# INDEX BUILD / LOAD (with per-chunk cache reuse)
# ============================================================

def build_index(cfg: dict, script_dir: Path, force: bool = False,
                progress=None) -> Tuple[dict, dict]:
    """Build/refresh the semantic index. Returns (index, stats) where stats is
    {"chunks": total_written, "embedded": newly_embedded, "reused": cached_reused}.
    Reuses cached vectors for unchanged chunks unless force=True."""
    interview = get_interview_settings(cfg, script_dir)
    gem = get_gemini_settings(cfg)
    model = interview["embed_model"]

    chunks = build_chunks(interview, script_dir)
    print(f"Collected {len(chunks)} chunks from vault + resume.")

    # Reuse cached vectors for unchanged chunks unless --rebuild.
    cache: Dict[str, dict] = {}
    ipath = index_path(script_dir)
    if not force and ipath.exists():
        try:
            # with_vectors=True: the whole point of the cache is reusing the cached VECTORS, so
            # they must be materialised here even though serving never needs them.
            existing = load_index(script_dir, with_vectors=True)
            if existing.get("embed_model") == model:
                for row in existing.get("chunks", []):
                    cache[row["id"]] = row
        except Exception as e:
            print(f"  (ignoring unreadable existing index: {e})")

    # A checkpoint from an interrupted build is just another cache source. Merged AFTER the existing
    # index so a resumed run prefers the freshest vectors; --rebuild ignores both.
    if not force:
        cache.update(_load_checkpoint(script_dir, model))

    rows: List[dict] = []
    to_embed: List[Tuple[int, Dict[str, str]]] = []
    for ch in chunks:
        cid = chunk_id(model, ch)
        if cid in cache:
            # Reuse the cached VECTOR, but refresh the fields NOT covered by chunk_id from the
            # fresh walk. `path` (and `tier` derived from it) go stale when a file is MOVED to a new
            # folder under the same name: same id -> cache hit -> the old row's path/tier would
            # otherwise persist, silently keeping the file's previous tier. source/heading/text ARE
            # in the id, so a hit guarantees they match; only path + tier can drift.
            row = dict(cache[cid])
            row["path"] = ch.get("path", "")
            row["tier"] = ch.get("tier", DEFAULT_TIER)
            rows.append(row)
        else:
            placeholder = {
                "id": cid, "source": ch["source"], "heading": ch["heading"],
                "text": ch["text"], "path": ch.get("path", ""),
                "tier": ch.get("tier", DEFAULT_TIER), "vector": None,
            }
            rows.append(placeholder)
            to_embed.append((len(rows) - 1, ch))

    print(f"Reusing {len(chunks) - len(to_embed)} cached vectors; embedding {len(to_embed)} new chunks.")
    if to_embed:
        inputs = [embed_input(ch) for _, ch in to_embed]
        est_usd = sum(len(t) for t in inputs) / EMBED_CHARS_PER_TOK / 1_000_000 * EMBED_USD_PER_MTOK
        if len(to_embed) > 500:
            # Say the two things a first-time user on a large vault has no way to know, BEFORE the
            # hour starts rather than after it.
            print(f"  This is a large build: roughly {_fmt_eta(len(to_embed) / 3.5)} and about "
                  f"${est_usd:.2f} at current rates (one request per chunk).")
            print(f"  Progress is checkpointed every {CHECKPOINT_EVERY} chunks, so an interruption "
                  f"resumes rather than starting over.")

        def _checkpoint(done: int, vecs: List[List[float]]) -> None:
            paid = [dict(rows[idx], vector=v)
                    for (idx, _), v in zip(to_embed[:len(vecs)], vecs) if v]
            _save_checkpoint(script_dir, model, paid)
            if progress is not None:
                # Same cadence as the checkpoint. A first build is the one moment a user has no
                # idea whether the app is working, and the console is not where they are looking.
                try:
                    progress(done, len(to_embed))
                except Exception:
                    pass

        vectors = embed_documents(inputs, model, gem["api_key"], interview["embed_dim"],
                                  on_progress=_checkpoint)
        for (row_idx, _), vec in zip(to_embed, vectors):
            rows[row_idx]["vector"] = vec

    # Cached rows always carry a vector and survive the filter below; newly embedded rows
    # only survive if the embed returned a non-empty vector.
    reused_count = len(chunks) - len(to_embed)
    rows = [r for r in rows if r.get("vector")]
    dim = len(rows[0]["vector"]) if rows else 0
    index = {"embed_model": model, "dim": dim, "chunks": rows}
    written_i, written_v = save_index(script_dir, index)
    if written_v is not None:
        print(f"Index written: {written_i.name} + {written_v.name} | {len(rows)} chunks | dim={dim}")
    else:
        print(f"Index written: {written_i} | {len(rows)} chunks | dim={dim}")
    # The build succeeded, so the partial file has no further purpose. Leaving it behind would
    # make the NEXT build print a misleading "resuming" line.
    cp = checkpoint_path(script_dir)
    if cp.exists():
        try:
            cp.unlink()
        except Exception:
            pass
    stats = {
        "chunks": len(rows),
        "embedded": len(rows) - reused_count,
        "reused": reused_count,
    }
    return index, stats


def save_index(script_dir: Path, index: dict) -> Tuple[Path, Optional[Path]]:
    """Persist the index, keeping vectors in a BINARY sidecar when numpy is available.

    JSON stores every float as text, so 17k x 768 vectors cost ~190MB on disk and ~5.5s of parsing
    at startup -- for data that is only ~50MB as float32. The vectors move to a `.npy` sidecar and
    the JSON keeps just the metadata (id/source/heading/text/path/tier), which is the part worth
    reading by eye anyway.

    Without numpy we fall back to the legacy all-in-one JSON, because the pure-Python `_cosine`
    retrieval path (a documented convention) could not read a .npy at all.

    Both files are written to temp paths and renamed, so an interrupted save can't leave a metadata
    file pointing at a stale vector file.
    """
    ipath = index_path(script_dir)
    vpath = vectors_path(script_dir)
    rows = index.get("chunks", [])

    if _np is None or not rows:
        payload = dict(index)
        payload.pop("_matrix", None)
        tmp = ipath.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(payload), encoding="utf-8")
        os.replace(tmp, ipath)
        vpath.unlink(missing_ok=True)      # don't leave a stale sidecar behind
        return ipath, None

    mat = _np.asarray([r["vector"] for r in rows], dtype=_np.float32)
    meta_rows = [{k: v for k, v in r.items() if k != "vector"} for r in rows]
    payload = {
        "embed_model": index.get("embed_model", ""),
        "dim": int(mat.shape[1]) if mat.ndim == 2 else 0,
        # Consistency fingerprint: load refuses a sidecar whose shape disagrees with this, rather
        # than silently serving vectors that belong to a different build.
        "vector_file": vpath.name,
        "vector_count": int(mat.shape[0]),
        "chunks": meta_rows,
    }
    vtmp = vpath.with_suffix(".npy.tmp")
    with open(vtmp, "wb") as fh:
        _np.save(fh, mat)
    os.replace(vtmp, vpath)
    itmp = ipath.with_suffix(".json.tmp")
    itmp.write_text(json.dumps(payload), encoding="utf-8")
    os.replace(itmp, ipath)
    return ipath, vpath


def load_index(script_dir: Path, with_vectors: bool = False) -> dict:
    """Load the index in either format.

    `with_vectors=True` re-attaches per-row Python lists (what build_index's cache needs, and what
    the no-numpy fallback needs). Serving does NOT want them: VectorIndex only needs the matrix,
    and materialising 13M Python floats is exactly the cost this format change removes.
    """
    ipath = index_path(script_dir)
    if not ipath.exists():
        raise SetupError(
            f"No index at {ipath}." + chr(10) +
            "  Build one first:  python interview_assistant.py --build-index"
        )
    try:
        index = json.loads(ipath.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        raise RuntimeError(
            f"{ipath.name} is not valid JSON ({e}). A --build-index that was killed part-way\n"
            f"leaves the file truncated -- it is written once at the very end. Run:\n"
            f"  python interview_assistant.py --build-index"
        ) from None
    if not isinstance(index, dict):
        raise RuntimeError(f"{ipath.name} is not an index (expected a JSON object). "
                           f"Run:  python interview_assistant.py --build-index")
    vfile = index.get("vector_file")
    if not vfile:
        # Legacy all-in-one JSON: vectors are inline. Say so plainly if they are not -- otherwise
        # the first row without one surfaces as a bare KeyError('vector') several frames away.
        rows = index.get("chunks") or []
        if rows and not rows[0].get("vector"):
            raise RuntimeError(
                f"{ipath.name} has no vectors: it is neither a metadata+.npy index (no "
                f"'vector_file') nor a legacy index with inline vectors.\n"
                f"Run:  python interview_assistant.py --build-index"
            )
        return index

    vpath = script_dir / vfile
    if _np is None:
        raise RuntimeError(
            f"{ipath.name} keeps its vectors in {vfile}, which needs numpy to read.\n"
            f"Install numpy (pip install numpy), or rebuild with --rebuild to get an all-JSON index."
        )
    if not vpath.exists():
        raise FileNotFoundError(
            f"Index metadata {ipath.name} references {vfile}, which is missing. Both files belong\n"
            f"together -- restore it, or run:  python interview_assistant.py --build-index"
        )
    mat = _np.load(vpath)
    expected = index.get("vector_count")
    if expected is not None and int(mat.shape[0]) != int(expected):
        raise RuntimeError(
            f"Index mismatch: {ipath.name} describes {expected} chunks but {vfile} holds "
            f"{mat.shape[0]}.\nThey are from different builds -- run --build-index to rebuild."
        )
    if len(index.get("chunks", [])) != int(mat.shape[0]):
        raise RuntimeError(
            f"Index mismatch: {len(index.get('chunks', []))} metadata rows vs {mat.shape[0]} "
            f"vectors.\nRun:  python interview_assistant.py --build-index"
        )
    if with_vectors:
        for row, vec in zip(index["chunks"], mat):
            row["vector"] = vec.tolist()
    else:
        index["_matrix"] = mat
    return index


def preview_tiers(cfg: dict, script_dir: Path) -> None:
    """Dry run: show what WOULD be excluded, each folder's tier + file count, and which files change
    tier versus their location in the current index. Reads only; writes nothing, embeds nothing."""
    interview = get_interview_settings(cfg, script_dir)
    vault = interview.get("vault_path", "").strip()
    vault_dir = Path(vault) if vault else None
    tier_map = interview.get("vault_tiers", {})
    exclude_lower = {s.lower() for s in SKIP_DIR_NAMES} | {
        s.lower() for s in interview.get("vault_exclude", [])}
    model = interview["embed_model"]

    # old path per filename (source stem), from the current index -> lets us show tier changes from
    # a move. Keyed by SOURCE not chunk_id, so an edited-and-moved file is still detected (a content
    # edit changes chunk_id but not the filename).
    old_path_by_source: Dict[str, str] = {}
    ip = index_path(script_dir)
    if ip.exists():
        try:
            for row in json.loads(ip.read_text(encoding="utf-8")).get("chunks", []):
                old_path_by_source.setdefault(row.get("source", ""), row.get("path", ""))
        except Exception as e:
            print(f"  (could not read current index for change detection: {e})")

    excluded: List[Tuple[Path, str]] = []
    if vault_dir and vault_dir.exists():
        for p in sorted(vault_dir.rglob("*.md")):
            r = _excluded(p, exclude_lower)
            if r:
                excluded.append((p, r))

    chunks = build_chunks(interview, script_dir)   # applies exclusion + attaches tier
    folder_tier: Dict[str, str] = {}
    folder_count: Dict[str, int] = {}
    tier_totals: Dict[str, int] = {t: 0 for t in VALID_TIERS}
    changed: List[Tuple[str, str, str]] = []
    seen_files = set()

    for ch in chunks:
        path = ch["path"]
        if path in seen_files:
            continue
        seen_files.add(path)
        tier = ch.get("tier", DEFAULT_TIER)
        tier_totals[tier] = tier_totals.get(tier, 0) + 1
        try:
            rel = str(Path(path).parent.relative_to(vault_dir)) if vault_dir else "<resume>"
        except Exception:
            rel = "<outside vault>"
        folder_tier[rel] = tier
        folder_count[rel] = folder_count.get(rel, 0) + 1
        # tier change vs current index (a file of this name moved across a tier boundary)
        oldp = old_path_by_source.get(ch.get("source", ""))
        if oldp and vault_dir:
            try:
                old_folder = Path(oldp).parent
                if str(old_folder).lower() != str(Path(path).parent).lower():
                    old_tier = resolve_folder_tier(old_folder.relative_to(vault_dir).parts, tier_map)
                    if old_tier != tier:
                        changed.append((path, old_tier, tier))
            except Exception:
                pass

    print("\n=== TIER PREVIEW (dry run — NOTHING written or embedded) ===")
    print(f"Vault: {vault_dir}")
    print(f"\nEXCLUDED — {len(excluded)} file(s) NOT indexed:")
    for p, reason in excluded:
        try:
            rp = p.relative_to(vault_dir)
        except Exception:
            rp = p
        print(f"  [{reason}]  {rp}")
    print(f"\nINCLUDED BY FOLDER — tier · file count ({len(seen_files)} files):")
    for rel in sorted(folder_tier, key=str.lower):
        print(f"  {rel[:52]:<52} {folder_tier[rel]:<11} {folder_count[rel]}")
    print("\nTIER TOTALS: " + " · ".join(f"{t} {tier_totals.get(t,0)}" for t in VALID_TIERS)
          + f" · excluded {len(excluded)}")
    print(f"\nFILES THAT CHANGED TIER vs the current index — {len(changed)} "
          "(verifies the path-refresh fix; empty = nothing crossed a tier boundary):")
    for path, ot, nt in changed:
        try:
            rp = Path(path).relative_to(vault_dir)
        except Exception:
            rp = path
        print(f"  {ot:>10} -> {nt:<10}  {rp}")
    print("=== end preview — run --build-index to apply ===\n", flush=True)


class VectorIndex:
    """The loaded index plus a precomputed, L2-normalised float32 matrix of its vectors.

    Why: `retrieve()` used to rebuild that matrix from the per-row Python lists on EVERY query --
    ~0.60s on a 12.9k-chunk index, while the similarity math it wrapped is ~3ms. Building it once
    at load / reindex makes the query path a single `matrix @ qhat`.

    Both structures live in this one object on purpose: a /reindex hot-swap is then a single
    atomic pointer assignment, so no /ask can ever observe a matrix that disagrees with its rows.
    Construct the new VectorIndex OUTSIDE the lock, swap the pointer inside it.

    numpy stays OPTIONAL (CLAUDE.md convention): without it `matrix` is None, the per-row
    "vector" lists are preserved, and retrieval falls back to pure-Python `_cosine`."""

    __slots__ = ("index", "rows", "matrix", "embed_model")

    def __init__(self, index: dict):
        self.index = index
        self.rows: List[dict] = index.get("chunks", [])
        self.embed_model: str = index.get("embed_model", "")
        self.matrix = None
        if _np is not None and self.rows:
            # Prefer the matrix loaded straight from the .npy sidecar; only fall back to rebuilding
            # it from per-row lists for a legacy all-in-one JSON index.
            pre = index.get("_matrix")
            mat = pre if pre is not None else _np.asarray([r["vector"] for r in self.rows],
                                                          dtype=_np.float32)
            norms = _np.linalg.norm(mat, axis=1, keepdims=True)
            norms[norms == 0.0] = 1e-9
            self.matrix = mat / norms
            # The numpy path never reads the per-row lists again, and the index file has already
            # been written by build_index -- so drop them (~300MB at 12.9k chunks). Only safe
            # because `matrix` exists; without numpy the fallback still needs them.
            for r in self.rows:
                r.pop("vector", None)

    def __len__(self) -> int:
        return len(self.rows)


def load_vector_index(script_dir: Path) -> "VectorIndex":
    return VectorIndex(load_index(script_dir))


def migrate_index(script_dir: Path) -> None:
    """Convert a legacy all-in-one JSON index to metadata + .npy. Re-embeds NOTHING."""
    ipath = index_path(script_dir)
    if not ipath.exists():
        print(f"No index at {ipath}.")
        return
    if _np is None:
        print("numpy is required to write the binary index (pip install numpy).")
        return
    before = ipath.stat().st_size
    raw = json.loads(ipath.read_text(encoding="utf-8"))
    if raw.get("vector_file"):
        print(f"Already migrated: {ipath.name} + {raw['vector_file']}")
        return
    rows = raw.get("chunks", [])
    if not rows or not rows[0].get("vector"):
        print("Index has no inline vectors -- nothing to migrate.")
        return
    t0 = time.perf_counter()
    _ipath, vpath = save_index(script_dir, raw)
    after = ipath.stat().st_size + (vpath.stat().st_size if vpath else 0)
    print(f"Migrated {len(rows)} chunks in {time.perf_counter() - t0:.1f}s")
    print(f"  {before/1024/1024:.1f} MB  ->  {after/1024/1024:.1f} MB "
          f"({ipath.name} {ipath.stat().st_size/1024/1024:.1f} MB + "
          f"{vpath.name} {vpath.stat().st_size/1024/1024:.1f} MB)")


# ============================================================
# RETRIEVAL
# ============================================================

def _cosine(a: List[float], b: List[float]) -> float:
    dot = 0.0
    na = 0.0
    nb = 0.0
    for x, y in zip(a, b):
        dot += x * y
        na += x * x
        nb += y * y
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (math.sqrt(na) * math.sqrt(nb))


def rank_hits(qvec: List[float], vindex: "VectorIndex", top_k: int) -> List[Tuple[float, dict]]:
    """Score an already-embedded query against the index. Split out from retrieve() so the
    embedding round trip and the (now ~3ms) ranking can be timed and reused independently."""
    rows = vindex.rows
    if not rows:
        return []

    if vindex.matrix is not None:
        q = _np.asarray(qvec, dtype=_np.float32)
        qnorm = float(_np.linalg.norm(q)) or 1e-9
        # Rows are pre-normalised, so this dot product IS the cosine similarity.
        sims = vindex.matrix @ (q / qnorm)
        k = min(top_k, sims.shape[0])
        # argpartition is O(n) vs argsort's O(n log n) -- matters as the vault grows.
        part = _np.argpartition(-sims, k - 1)[:k] if k < sims.shape[0] else _np.arange(sims.shape[0])
        order = part[_np.argsort(-sims[part])]
        return [(float(sims[i]), rows[i]) for i in order]

    scored = [(_cosine(qvec, r["vector"]), r) for r in rows]
    scored.sort(key=lambda t: t[0], reverse=True)
    return scored[:top_k]


def retrieve(query: str, vindex: "VectorIndex", cfg: dict, script_dir: Path,
             top_k: int) -> List[Tuple[float, dict]]:
    interview = get_interview_settings(cfg, script_dir)
    gem = get_gemini_settings(cfg)
    qvec = embed_query(query, vindex.embed_model or interview["embed_model"],
                       gem["api_key"], interview["embed_dim"])
    return rank_hits(qvec, vindex, top_k)


# ============================================================
# GROUNDED ANSWER PROMPTS + MODE CLASSIFICATION
# ============================================================

SYSTEM_GROUNDED = """You are the candidate's own voice in a technical interview. You speak in the FIRST PERSON ("I", "my") as the candidate.

You are given CONTEXT excerpts pulled from the candidate's OWN notes and resume. These are the only things the candidate actually knows and has done.

ABSOLUTE RULES:
- Use ONLY the information in the CONTEXT. Never add tools, versions, commands, numbers, employers, or claims that are not present in the CONTEXT.
- Do not exaggerate scope or seniority beyond what the CONTEXT supports.
- If the CONTEXT does not fully address the question, answer at the level the CONTEXT DOES support instead of guessing -- and do NOT announce the shortfall (see the HONESTY RULE below, which governs).

WHEN THE CONTEXT ANSWERS THE QUESTION:
1. Answer in the first person exactly as the candidate would say it out loud. Lead with the substance -- no preamble, no restating the question.
2. Be SPECIFIC -- name the ACTUAL tools, service names, commands, versions, exact steps, and distinctions that appear in the CONTEXT, rather than generic statements. Specificity is what sounds senior; do not pad with vague filler.
3. Say each point ONCE. Never give a summary and then restate the same content again in another form -- that redundancy wastes the candidate's speaking time.
The DETAIL LEVEL instruction below sets the LENGTH and the FORMAT (flowing prose vs bullets vs headed sections). Follow it exactly -- it overrides any default urge to add bullet points or a separate summary. Stay natural and confident.

HONESTY RULE:
- NEVER claim experience the CONTEXT does not support. No "I deployed", "I ran", "in my environment" for anything absent from the CONTEXT. That rule is absolute.
- But do NOT VOLUNTEER what you have not done. The interviewer asked a question; answer it from what the CONTEXT supports, cleanly and in your own voice. Do NOT narrate the gap, and do NOT append disclaimers like "though I haven't done this hands-on", "I haven't worked on this directly", "this is more theoretical for me", or "I'd be keen to try it". Say the substance and stop.
- If asked about a specific product that is NOT in the CONTEXT, you MAY name the well-known market-standard alternatives in its category as general domain knowledge -- category and alternatives ONLY, never claimed experience, never invented specifics.
"""

# Gated disclosure. Appended ONLY when asks_about_experience() fires -- i.e. the interviewer asked
# the experience question outright, at which point evasion would be dishonest and would also read
# far worse than a straight answer.
# The CV counts as evidence (14 Sep 2026). This used to judge ONLY from the retrieved notes, so a
# literal model denied experience the CV documents: asked about QRadar in production, Haiku said no
# 3 of 3 and Gemini 2 of 3, although the CV has SOC/SIEM duties under the current job and names
# QRadar as the SIEM. The three evidence levels stop the CV from over-proving in the other
# direction: a project, a skills-list entry or a certification is NOT production.
DISCLOSURE_BLOCK = """

THE INTERVIEWER HAS DIRECTLY ASKED ABOUT YOUR HANDS-ON EXPERIENCE. Answer that question honestly and FIRST, before anything else. Judge it from BOTH the CONTEXT and the CANDIDATE PROFILE (the CV), and this judgement outranks any instruction above that tells you not to mention experience. Each CONTEXT excerpt is tagged with how it is known, such as (production) or (project).
- IN A JOB: a job in the CV whose duties cover it, or CONTEXT tagged (production). A tool named in the CV's skills counts when a job's duties describe that kind of work (for example a SIEM named in the skills, and SOC or SIEM duties under a role). A tool or protocol named inside a job's duties counts in full even when it is one item in a list, such as "configured OSPF, EIGRP and BGP across sites". When the CV shows it in a job, lead with that job, even if the CONTEXT also describes a project or reads like textbook material. Say yes plainly and name the role or system. Use only details the CV or CONTEXT states, and never invent numbers, versions or scale.
- HANDS-ON, BUT NOT IN A JOB: CONTEXT tagged (project), a project or proof of concept in the CV, or a skills-list entry with no job duties behind it. If the question asks about production, say what you built and that it was not in production, for example "I've built X in a project, but not in production." If it only asks whether you have worked with it, say yes and name the project. A certification alone shows knowledge, not operation. So does anything the CV lists as being studied, learned or planned: that is the NOTHING level below, so never describe labs, clusters or projects with it that the CV does not describe.
- NOTHING shows it: say so directly and without apology, in one short clause, for example "I haven't run that in production myself". Then, if you have genuinely relevant knowledge or an adjacent thing you HAVE done, give it briefly. A similar tool in the CV is not the tool that was asked about. Never pad the admission, never over-apologise, never claim it anyway.
- These levels apply to EVERY sentence about your own work, not only the first. A project stays a project, a tool that is only in the skills list or a certification is not something you ran in production, and work belongs to a particular job only when the CV lists it under that job. This matters most in the sentence that bridges to what you HAVE done. Wrong, when the CV has X and Y only under projects or skills: "My experience is with X and Y at scale in my roles." Right: "I've built projects on X and Y, but not in production."
- Disclose the ABSENCE of hands-on experience, never the SOURCE of your knowledge. Do NOT say "I've studied", "from my studies", "from my coursework", "my notes", "I've read about", "I've been learning", or name any course, certification, book or training. After the one honest clause, simply explain what you know in a normal confident voice, as knowledge you hold rather than material you revised.
- Answer the question that was ACTUALLY asked. If it was a yes/no about your experience, the honest clause plus at most a sentence or two of what you do know is the whole answer -- do NOT pivot into a troubleshooting walkthrough, a step-by-step, or a general explainer the interviewer did not ask for.
- Do not overstate scope or seniority to soften the answer."""

# The candidate's VOICE, on every answer type (13 Sep 2026). The no-source rule used to live only in
# some answer types, as a closed list of banned phrases, so Claude paraphrased straight past it
# ("My study covers Linux kernel architecture ... but doesn't include hands-on OpenShift") while
# Gemini answered the same question in one plain sentence. Appended LAST in build_answer_messages so
# it sits after, and outranks, the framing text above it.
# Second pass, same day: the examples use X and Y so no product name reaches every user's prompt,
# and course-speak is named outright, because Haiku kept calling study-tier labs "guided exercises
# in a learning environment" after the first pass while Gemini said "project work".
VOICE_RULE = """

SPEAK ONLY AS THE CANDIDATE. This answer is said out loud in an interview, and the interviewer must never learn it was prepared from anything:
- Never mention notes, study, studies, courses, coursework, reading, documentation, "context", excerpts, or any material you were given, and never describe what that material covers, includes or lacks.
- Never describe practice as a course, a guided project, guided exercises, lab exercises or a "learning environment". If you really did hands-on work outside production, say plainly what you did and that it was not in production, the way a person would in an interview.
- Wrong: "My study covers X, but doesn't include Y." Wrong: "The context I have references Y." Wrong: "I worked through guided exercises on Y in a learning environment." Right, when you really did hands-on work: "I've set Y up myself, but never in production." Right, otherwise: "I haven't worked on Y in production myself."
- What you know is simply what you know, said in your own voice with no source attached.
- "I" always means the candidate, never a system. Say what a system, device or protocol does in the third person ("X compares Y", not "I compare Y"), and use "I" only for what you did, decided or would do."""

# Punctuation that reads as AI-written (13 Sep 2026, the owner's rule). Matters most in text typed
# into an interview platform's answer box, where the interviewer READS it. Only the punctuation
# half of the owner's style guidance is used: the other half ("narrative where it helps, not the
# terse voice") would contradict the "To the point" detail level, which is one sentence by design.
STYLE_RULE = """
- Punctuation: do not use em dashes, en dashes, double hyphens used as a dash, or semicolons in your sentences. Use a comma, a full stop, or a word such as "and" or "to" instead (write "2019 to 2022", not a dashed range). Code, commands and queries keep their own punctuation."""

SYSTEM_ADJACENT = """You are the candidate's own voice in a technical interview, speaking in the FIRST PERSON ("I", "my").

The retrieved CONTEXT is only loosely related to the question -- it does NOT show direct, deep hands-on experience with exactly what was asked, but it may contain the closest genuinely-related thing the candidate has actually done. THIS PARAGRAPH IS BACKGROUND FOR YOU ONLY. It describes the retrieval situation; it is NOT something to tell the interviewer, and none of it may surface in the answer.

Give a BRIEF answer (1-3 sentences, NO bullet points) that bridges from the closest genuinely-related item that clearly appears in the CONTEXT, naming it naturally, and answers the question as well as that material allows.

ABSOLUTE RULES:
- Use ONLY what is in the CONTEXT for any concrete claim. Never invent tools, versions, numbers, projects, or employers. Never claim to have operated something the CONTEXT does not show.
- Do NOT overstate the connection or your depth.
- Do NOT volunteer what you haven't done. No "though my hands-on depth here is limited", no "I haven't worked with this directly", no trailing disclaimer. Answer from the adjacent material in a normal confident voice; if the interviewer wants to know whether you've operated it, they will ask, and you answer that honestly when they do.
- If the CONTEXT truly contains nothing related, give the short general answer without inventing anything -- do not force a bridge, and do not editorialise about the gap.
"""

# GENERAL-KNOWLEDGE framing (grounding mode 'assist' when retrieval came back ungrounded, or 'open'
# for every question). This is the ONE framing that is allowed to answer from the model's own
# knowledge rather than the vault -- an explicit owner decision, surfaced on the badge so it is never
# mistaken for vault-backed recall.
#
# The grounding contract is NARROWED here, not abandoned: inventing a personal history is still
# forbidden. The model may explain what it knows about the subject; it may NOT say the candidate
# built, ran, configured or operated any of it. That is the line that keeps an answer defensible
# when the interviewer probes -- and the reason asks_about_experience() still forces an honest
# disclosure on a direct probe even in this mode.
SYSTEM_OPEN = """You are helping a candidate answer a technical interview question. Answer from general professional knowledge of the subject.

If CONTEXT from the candidate's own notes is supplied below, PREFER it and lead with it -- it is what the candidate actually knows. Beyond that you may draw on general domain knowledge to give a correct, useful answer.

ABSOLUTE RULES (these do not relax):
- NEVER claim personal hands-on experience. Do NOT say "I built", "I deployed", "I configured", "I ran", "I managed", "in my environment", "at my company", "in my role", or name any employer, project, client, team or date that is not in the CONTEXT. Inventing a personal history is forbidden -- it is the one thing that would be indefensible when the interviewer follows up.
- Explain the subject as knowledge, and where the question asks how you would handle something you MAY reason in the first person about the APPROACH you would take ("I'd start by...") -- that is judgement, not an experience claim.
- Do NOT state or hint at where your knowledge came from. No "I've studied", "from my notes", "in theory", "from what I've read", "I haven't done this hands-on". Just answer.
- Be accurate. If something is genuinely contested or version-dependent, say so plainly rather than inventing certainty.
"""

# Rewritten to VARY every time -- never reuse a stock sentence like
# "I don't have direct experience with X" (that verbatim repeat tips off interviewers).
SYSTEM_UNGROUNDED = """You are the candidate's own voice in a technical interview, speaking in the FIRST PERSON ("I", "my").

Nothing sufficiently relevant was found in the candidate's own notes or resume for this question, so the candidate does not have documented hands-on experience with it.

Write a SHORT (1-2 sentence) reply that honestly conveys you haven't worked hands-on with the specific topic asked. Hard requirements:
- VARY the wording every single time. Do NOT reuse any stock template or the same opening phrase across answers -- rephrase naturally, as a real person would in conversation, so it never sounds canned.
- Stay graceful and confident; you may briefly express genuine curiosity or willingness to pick it up.
- Do NOT invent any experience, tools, projects, frameworks, or specifics. No bullet points.

MARKET-ALTERNATIVES CARVE-OUT (general domain knowledge, NOT a claim of experience): if asked about a specific product you have no CONTEXT for, you MAY name the well-known market-standard alternatives in that product's category -- e.g. "I haven't operated it myself, though I know it sits alongside X and Y in that space" -- while stating plainly you haven't used them. Name the category and its alternatives ONLY. Never claim you have used them, never invent versions, numbers, configurations, or results, and keep it to a phrase, not a survey.
"""


# STUDY framing: the top-scoring retrieved notes are STUDY tier (courses/reading, no hands-on).
# A first-person KNOWLEDGE claim, never an operation claim. Distinct from adjacent (which bridges
# from real experience) and ungrounded (no notes at all).
SYSTEM_STUDY = """You are answering a technical interview question. The retrieved CONTEXT comes from the candidate's STUDY notes (courses, certifications, reading) -- knowledge, NOT hands-on production or project work.

Explain the concept accurately and directly, using ONLY what the CONTEXT supports. About 2-4 sentences, clean and competent -- the kind of explanation any strong professional gives.

DO NOT:
- Preface with PROVENANCE. No "from my studies", "based on my studies", "my notes indicate", "my understanding is", "as I've learned". The answer must carry NO verbal signal of where the knowledge came from -- that is shown elsewhere.
- Claim hands-on or production experience. No "I deployed", "I configured", "I've used", "I've run", "in my environment", "in my role". Invent no experience, numbers, employers, or projects.
- Add a self-label or hedge such as "I haven't done this in production" or "I'm confident I could pick it up". No self-labelling at all -- just explain.

Whether the candidate has operated this is signalled outside the answer and disclosed honestly ONLY if the interviewer asks directly. Your job is the clean, correct explanation.
"""

# REFERENCE framing: the top notes are REFERENCE tier (domain/framework knowledge only). A neutral
# explanation with NO first-person claim -- not experience, not even study. Deliberately detached.
SYSTEM_REFERENCE = """You are answering a technical interview question. The retrieved CONTEXT is REFERENCE material -- general domain or framework knowledge, not a record of anything the candidate personally did or studied as a course.

Give a concise, accurate explanation of the concept from the CONTEXT (about 2-4 sentences). HARD RULES:
- Claim NO hands-on experience, and use NO provenance preface. Do NOT say "I've done", "I've used", "I've configured", "I studied", "from my studies", "my notes indicate", or "in my experience". You MAY reason in the first person about how you would APPROACH something (that is judgement, not an experience claim) when the question asks how you'd handle a situation; for a plain "what is X" question, default to a neutral explanation.
- Use ONLY what the CONTEXT supports; invent no specifics, numbers, tools, or results.
- A clean explanation a competent professional could give -- not a fabricated personal anecdote.
"""


# SCREEN framing: the question is on the candidate's screen (a case study, a code/query review),
# not in their notes. This is the one framing whose CONTEXT is external, so it says so plainly rather
# than letting a screen answer wear the grounded badge. Vault CONTEXT is still supplied when
# retrieval found anything -- the candidate's own diagnostic vocabulary should still come through.
SYSTEM_SCREEN = """You are helping a candidate answer a question about material shown on their screen during a technical interview -- a case study, a code or query snippet, a log extract.

The SCREEN CONTENT below is the primary source. Read it carefully and answer about THAT, not about something similar you have seen before.

HOW TO ANSWER:
- Be specific to what is actually on the screen. Quote the exact line, operator, field or symptom you are referring to, so the candidate can point at it.
- For a code or query review: say what it does, then name the SPECIFIC defect and where it is, then the fix. One precise defect beats three vague suspicions.
- For a case study or incident: the likely cause, then how you would CONFIRM it, then what you would change. Distinguish what the material states from what you are inferring.
- If the screen content is truncated or an important part is clearly missing, say so in a short clause rather than inventing the missing piece.

ABSOLUTE RULES:
- Never claim personal hands-on experience with the system on screen. This is analysis, not recall. Do not say "I built", "I ran", "in my environment", and never name an employer, project or date.
- If NOTES CONTEXT from the candidate's own material is supplied, use it to inform the approach and vocabulary, but the screen content decides the facts.
- Do not invent values, fields, table names or line numbers that are not visible in the screen content.
"""


# Optional tone addendum (style only -- NEVER weakens grounding). Applied to grounded and
# adjacent answers when the user enables "humanize"; ungrounded already varies its wording.
HUMANIZE_ADDENDUM = (
    "\n\nTONE: Deliver this in a warm, natural, human, conversational first-person voice while "
    "staying professional and concise. Vary sentence rhythm so it doesn't sound scripted. This is "
    "style only -- do NOT add, soften, or invent any facts beyond the CONTEXT; all grounding rules "
    "still bind."
)


SYSTEM_PROFILE = """You are answering as the candidate, about the candidate's own background.

The CANDIDATE PROFILE below is their CV. It is fact about them, so answer from it directly and in the first person.

HOW TO ANSWER:
- Lead with what is relevant to this interview, not a chronological recital of the whole CV.
- Concrete: roles, employers, scope, and the kind of work -- as the CV states them.
- If NOTES CONTEXT is supplied, you may use it to add depth on something the CV only names.
- Never invent an employer, title, date, certification or achievement that is not in the CV.
- If the CV genuinely does not cover what was asked, say so plainly rather than filling the gap.
"""

# Added to the profile framing only for a question about something specific the candidate did, which
# only CV-only mode routes there (see build_answer_messages and cv_only_framing).
PAST_WORK_RULE = """

THIS QUESTION ASKS ABOUT SOMETHING SPECIFIC YOU DID. This overrides the DETAIL LEVEL above:
- Say what you did, in the role it belongs to, using only the facts in the CANDIDATE PROFILE: the work and any result it states. Add no incident, conversation, disagreement, number, tool, step or outcome beyond those facts. Two to four sentences.
- Where those facts end, stop, or go on with how you approach this kind of work in general ("My approach is..."). If no work there matches the question, answer only with your approach, in one to three sentences, without inventing an example.
- Speak as the candidate in an interview: never refer to a CV, a profile or a record, and never comment on what is or is not detailed.
- Wrong, when no such occasion is described: "The one that stands out was an outage where I..." Right: "As incident commander at X, I lead the response and drive the postmortem actions. My approach is..." Wrong: "I don't have an example of that on my CV." Right: "My approach to that is..." """

# "Tell me about yourself" is the one question guaranteed to be asked, and it must never be
# answered from vault retrieval alone -- that is what produced an intro built out of technical
# notes. Local regex, same cheap-signal approach as wants_detail()/asks_about_experience().
_BACKGROUND_RE = re.compile(
    r"(tell|talk)\s+(me|us)\s+(a\s+bit\s+)?about\s+(yourself|your\s+background|your\s+career)"
    r"|introduce\s+yourself"
    r"|walk\s+(me|us)\s+through\s+your\s+(cv|resume|résumé|background|career)\b"
    r"|(your|the)\s+(cv|resume|résumé)\b"
    r"|about\s+your\s+(background|career|profile)\b"
    r"|who\s+are\s+you\b"
    r"|why\s+should\s+we\s+hire\s+you"
    r"|where\s+(have|did)\s+you\s+work"
    r"|summar(y|ise|ize)\s+of\s+your\s+(background|career|experience)\b",
    re.I)


def asks_about_background(question: str) -> bool:
    """True for identity/CV questions -- the ones the resume, not the vault, should answer."""
    return bool(_BACKGROUND_RE.search(question or ""))


def classify_mode(top_score: float, min_score: float, adjacent_margin: float) -> str:
    if top_score >= min_score:
        return "grounded"
    if top_score >= (min_score - adjacent_margin):
        return "adjacent"
    return "ungrounded"


def temperature_for_mode(mode: str) -> float:
    return {"grounded": 0.2, "adjacent": 0.5, "ungrounded": 0.75,
            "study": 0.5, "reference": 0.4, "open": 0.5, "screen": 0.2,
            "profile": 0.4}.get(mode, 0.2)


def apply_grounding(framing: str, grounding: str) -> str:
    """Let the GROUNDING setting override the retrieval-derived framing. Deliberately the LAST step,
    so retrieval and the tier ceiling still decide everything they decided before -- this only
    redirects the outcome.
      strict -> unchanged (the original contract).
      assist -> only rescues 'ungrounded'; a study/reference/adjacent hit is real vault material and
                keeps its honest framing rather than being replaced by generated text.
      open   -> every answer is general-knowledge framed, with any retrieved CONTEXT preferred.
    """
    if grounding == "open":
        return "open"
    if grounding == "assist" and framing == "ungrounded":
        return "open"
    return framing


# CV-ONLY (30 Sep 2026): no notes indexed yet, but a CV is active, so the CV is the ONLY evidence of
# what the candidate has done. Measured on the fictional demo CV with no notes before this existed:
# "How did you handle TLS certificate renewals on NGINX?" was DENIED under strict although the CV
# lists certificate lifecycle work, and under assist both CV achievements came back as hypotheticals
# ("I'd start by..."), because the ungrounded and open framings are written for "your notes have
# nothing on this". A question about the candidate's own past is really a CV question here.
_PAST_WORK_RE = re.compile(r"\bdid you\b|\bhave you (?:ever )?(?:had to|handled|dealt with|led)\b", re.I)


def cv_only_framing(question: str, grounding: str) -> str:
    """Framing for an answer with NO notes indexed and an active CV.
      background question            -> profile (as always)
      direct experience probe        -> the grounding outcome, which carries DISCLOSURE_BLOCK and
                                        judges the probe from the CV (measured correct as it was)
      the candidate's own past work  -> profile ("How did you...", "Why did you...", behavioural)
      anything else                  -> the grounding outcome: strict gives the honest no, assist
                                        and open give a general answer under the orange badge.
    The Source setting keeps its meaning: nothing here turns strict into a generated answer."""
    q = question or ""
    if asks_about_background(q):
        return "profile"
    if asks_about_experience(q):
        return apply_grounding("ungrounded", grounding)
    if classify_question(q) == "behavioural" or _PAST_WORK_RE.search(q):
        return "profile"
    return apply_grounding("ungrounded", grounding)


# Words a question uses for the DOING rather than the subject: in "how did you decrease false positives
# in QRadar", decrease is the doing, and QRadar and false positives are the subject. Kept apart from
# _CV_EVIDENCE_STOP so the CV evidence block is unchanged. Folded forms, as _evidence_tokens returns.
_TOPIC_STOP = _CV_EVIDENCE_STOP | frozenset("""
decrease decreased reduce reduced improve tune tuned tuning onboard onboarded handle handled harden
hardened monitor monitored explain difference between work guarantee schedule detect create created
make made write written setup configure deploy approach walk through step
""".split())


def _topic_words(text: str) -> set:
    return {t for t in _evidence_tokens(text) if t not in _TOPIC_STOP and len(t) > 1}


def _note_is_about(row: dict, subject: set) -> bool:
    """Does this chunk's note title or heading trail name any of the question's subject words?"""
    return bool(subject & set(_evidence_tokens(f"{row.get('source') or ''} {row.get('heading') or ''}")))


def experience_ceiling(hits: List[Tuple[float, dict]], margin: float,
                       question: Optional[str] = None) -> Optional[str]:
    """The tier that caps the answer's experiential claim: the tier of the HIGHEST-SCORING chunk,
    optionally raised by a higher tier scoring within `margin` of the top. At margin 0.0 (default)
    only the top hit counts, so a weak higher-tier hit can't unlock strong framing. Returns None if
    no hit carries a tier (pre-tier index) -> caller falls back to score-only behaviour.

    A higher tier may raise the ceiling only if its note is ABOUT what was asked: its title or heading
    trail must share a subject word with `question`, the query retrieval ran on (24 Sep 2026). Found
    live: "How did you decrease false positives in QRadar?" was answered as a hypothetical because a
    QRadar course chunk (study) beat the owner's own QRadar note (production) by 0.022, so the answer
    left out a real 60% reduction. A plain margin fixed that but was topic-blind: it would also have
    let an unrelated project note lift "Have you managed an Oracle database?". The gate only ever
    RAISES, so it cannot lower a badge or touch a behavioural answer. No question, or a question with
    no subject words, allows no promotion: an old caller fails safe to the strict behaviour."""
    if not hits or not hits[0][1].get("tier"):
        return None
    top_score = hits[0][0]
    best = hits[0][1].get("tier", DEFAULT_TIER)
    if margin > 0:
        subject = _topic_words(question or "")
        if not subject:
            return best
        for score, row in hits:                 # hits are sorted score-descending
            if score < top_score - margin:
                break
            t = row.get("tier")
            if t and TIER_ORDER.get(t, 0) > TIER_ORDER.get(best, 0) and _note_is_about(row, subject):
                best = t
    return best


# Word endings folded before a question's subject is compared with note or CV text, on both sides, so
# "clustering" meets "cluster" and "configured" meets "configure". Deliberately light: it only has to
# stop an incidental word form from failing a match, not to be a linguistic stemmer.
_CLAIM_SUFFIXES = ("ation", "ing", "ed", "es", "er", "ion", "s")


def _claim_stem(word: str) -> str:
    for suf in _CLAIM_SUFFIXES:
        if word.endswith(suf) and len(word) - len(suf) >= 4:
            return word[:-len(suf)]
    return word


def _claim_words(text: str) -> set:
    return {_claim_stem(t) for t in _evidence_tokens(text)}


def claim_tier(hits: List[Tuple[float, dict]], question: str, ceiling: Optional[str],
               resume: str = "") -> Optional[str]:
    """For a direct experience question, the tier the evidence supports for what was ASKED, never
    above `ceiling`; "none" when no retrieved note of any tier and no part of the CV names it.

    Found 24 Sep 2026: "Have you worked with Palo Alto firewalls?" was badged Production experience,
    because the owner's SRX firewall notes top retrieval for it, while the answer correctly said no.
    At the strict setting 10 of 26 tools the owner has never used got a Production or Project badge
    that way. The answer was right and the badge contradicted it.

    Evidence is the same fail-safe test `_cv_evidence_block` uses: EVERY subject word must appear.
    Two things made it safe on the owner's real work, both measured:
    - the words are pooled across all retrieved notes of a tier, not required in one chunk. Per chunk
      it stripped the badge from 4 of 24 real probes ("TACACS for network devices", "NAT on Juniper
      SRX firewalls"...), because generic words like "devices" rarely sit beside the product name;
    - the CV counts as evidence, because `DISCLOSURE_BLOCK` lets a CV job justify a yes. If the CV
      names every subject word the badge keeps its tier, so it cannot contradict a supported claim.
    Only production and project badges are judged: a study or reference badge claims nothing."""
    if ceiling not in ("production", "project") or not hits:
        return ceiling
    subject = {_claim_stem(t) for t in _topic_words(question or "")}
    if not subject:
        return ceiling
    if resume and subject <= _claim_words(resume):
        return ceiling
    rows = [(row.get("tier"),
             _claim_words(f"{row.get('source') or ''} {row.get('heading') or ''} {row.get('text') or ''}"))
            for _, row in hits]
    for tier in sorted(TIER_ORDER, key=lambda t: -TIER_ORDER[t]):
        if TIER_ORDER[tier] > TIER_ORDER[ceiling]:
            continue
        pool: set = set()
        for t, found in rows:
            if TIER_ORDER.get(t, 0) >= TIER_ORDER[tier]:
                pool |= found
        if subject <= pool:
            return tier
    return "none"


def badge_for(framing: str, ceiling: Optional[str], probe: bool, hits: List[Tuple[float, dict]],
              query: str, resume: str = "", notes_used: bool = True) -> Tuple[str, Optional[str]]:
    """(mode, ceiling_tier) for the BADGE. Identical to the answer's framing, except on a direct
    experience question whose Production or Project badge the evidence does not support, where it
    drops to what the evidence does support: Conceptual, Reference, or "No direct experience".
    The PROMPT is never changed: those answers were already right (the experience test passes every
    "no" case), and the production framing is what lets one bridge honestly ("not Palo Alto, but I
    ran Juniper SRX..."). Only the label that contradicted the answer moves.

    The reverse case (30 Sep 2026): when NO notes informed the answer, an experience probe is judged
    from the CV alone (DISCLOSURE_BLOCK), so "Have you run PostgreSQL replication?" can be a correct
    yes under a "No direct experience" badge. If the CV names every subject word, the badge says the
    CV is the evidence ("profile" renders as "From your CV"), with the same fail-safe as claim_tier."""
    if framing == "profile":
        return "profile", None
    if probe and resume and not notes_used and framing in ("ungrounded", "open"):
        subject = {_claim_stem(t) for t in _topic_words(query or "")}
        if subject and subject <= _claim_words(resume):
            return "profile", None
    if not probe or framing != "grounded":
        return framing, ceiling
    claim = claim_tier(hits, query, ceiling, resume)
    if claim in ("production", "project"):
        return "grounded", claim
    if claim in ("study", "reference"):
        return claim, claim
    if claim == "none":
        return "ungrounded", None
    return framing, ceiling


def resolve_framing(score_mode: str, ceiling_tier: Optional[str]) -> str:
    """Combine the score-based retrieval mode with the tier ceiling into the final answer framing.
    Retrieval strength decides IF there's an answer; tier decides HOW to speak about it.
    - ungrounded (nothing relevant) stays ungrounded regardless of tier.
    - production/project ceiling -> keep the experience framing (grounded/adjacent).
    - study ceiling -> 'study' (conceptual, first-person knowledge, no operation claim).
    - reference ceiling -> 'reference' (neutral explanation, no personal claim).
    ceiling_tier None (pre-tier index / gating off) -> unchanged score_mode."""
    if score_mode == "ungrounded" or ceiling_tier is None:
        return score_mode
    if ceiling_tier in ("production", "project"):
        return score_mode
    return ceiling_tier  # 'study' or 'reference'


def _jd_focus_block(jd: str) -> str:
    if not jd or not jd.strip():
        return ""
    return (
        "\n\nACTIVE JOB DESCRIPTION (FOCUS STEERING ONLY):\n"
        + jd.strip()
        + "\n\nUse the job description ONLY to decide which of my real, CONTEXT-supported "
        "experiences to emphasize and how to frame relevance. It NEVER licenses inventing "
        "facts, tools, or experience that are not in the CONTEXT -- all grounding rules still "
        "bind. If the question is clearly outside the job description's scope, you may briefly "
        "note that to the interviewer, but STILL give a short answer whenever the CONTEXT "
        "supports one."
    )


def _history_block(history: Optional[list]) -> str:
    """Compact 'conversation so far' block so a follow-up question keeps continuity. Prior answers
    are truncated to bound tokens. Grounding is NOT weakened -- new specifics still come from CONTEXT."""
    if not history:
        return ""
    lines: List[str] = []
    for turn in history[-4:]:
        if not isinstance(turn, dict):
            continue
        q = str(turn.get("q") or "").strip()
        a = str(turn.get("a") or "").strip()
        if q:
            lines.append(f"- Interviewer asked: {q}")
        if a:
            lines.append(f"  I answered: {a[:400]}")
    if not lines:
        return ""
    return (
        "CONVERSATION SO FAR (the latest question may be a FOLLOW-UP to this, so keep continuity "
        "with what I already said):\n" + "\n".join(lines) +
        "\n(Answer any follow-up in the context of the above, but ground every NEW specific claim "
        "in the CONTEXT below, and do not invent.)\n\n"
    )


# System prompt for the lightweight "resolve" step: it BOTH decides whether the latest question
# continues the previous topic AND (only if it does) rewrites it into a standalone search query.
# One Flash call does both, so auto-detection costs nothing extra over the old condense-only step.
CONDENSE_SYSTEM = (
    "You analyse an interviewer's latest question against the recent conversation.\n"
    "Decide if it is a FOLLOW-UP (it continues the same topic, or it cannot be understood on its "
    "own because it refers back with words like 'it', 'that', 'those', 'the same', or asks to go "
    "deeper into what was just discussed) or a NEW TOPIC (it introduces a different subject and "
    "stands on its own, even if it shares broad domain vocabulary with earlier questions).\n"
    "Reply with ONLY a JSON object, no markdown fences, no commentary:\n"
    '{\"followup\": true|false, \"query\": \"<one-line standalone search query>\"}\n'
    "For a follow-up, resolve every reference so the query makes sense alone. For a new topic, set "
    "followup to false and return the question unchanged as the query."
)

# Conservative heuristic used only if the LLM resolve step fails: continuation openers and
# referential pronouns are the signals that a question cannot stand on its own.
_FOLLOWUP_HINT_RE = re.compile(
    r"^\s*(?:and|so|ok(?:ay)?|but|then|also)\b"
    r"|\bwhat about\b|\bhow about\b|\bwhat if\b"
    r"\b|\btell me more\b|\bgo on\b|\bgo deeper\b|\belaborate\b|\bwalk me through\b"
    r"|\bthat (?:one|approach|setup|design|issue|project)\b|\bthe same\b|\bin that case\b"
    r"|\b(?:it|that|those|these|them|this)\b",
    re.I,
)


def _heuristic_followup(question: str) -> bool:
    """Fallback follow-up guess when the LLM resolve step is unavailable. Conservative: only a
    referential/continuation signal counts, so an unrelated new question defaults to NEW TOPIC."""
    return bool(_FOLLOWUP_HINT_RE.search(question or ""))


def _parse_resolve_json(raw: str) -> Optional[Tuple[bool, str]]:
    """Pull {"followup":bool,"query":str} out of the model reply; None if unparseable."""
    if not raw:
        return None
    txt = raw.strip()
    if txt.startswith("```"):  # strip accidental markdown fences
        txt = re.sub(r"^```[a-zA-Z]*\s*|\s*```$", "", txt).strip()
    m = re.search(r"\{.*\}", txt, re.S)
    if not m:
        return None
    try:
        obj = json.loads(m.group(0))
    except Exception:
        return None
    if not isinstance(obj, dict) or "followup" not in obj:
        return None
    return bool(obj.get("followup")), str(obj.get("query") or "").strip()


def condense_query(question: str, history: Optional[list], cfg: dict,
                   script_dir: Path) -> Tuple[str, bool]:
    """Classify the latest question as follow-up vs new topic and, for a follow-up, rewrite it into
    a standalone retrieval query. Returns (search_query, is_followup). Always uses a fast model
    (Flash) regardless of the answer model. Degrades to (question, heuristic) on any failure --
    retrieval must never break because of this step."""
    if not history:
        return question, False
    convo: List[str] = []
    for turn in history[-4:]:
        if not isinstance(turn, dict):
            continue
        q = str(turn.get("q") or "").strip()
        a = str(turn.get("a") or "").strip()
        if q:
            convo.append(f"Interviewer: {q}")
        if a:
            convo.append(f"Me: {a[:300]}")
    if not convo:
        return question, False
    user = ("Recent conversation:\n" + "\n".join(convo) +
            f"\n\nLatest question:\n{question}\n\nJSON:")
    try:
        out = gemini_chat(
            [{"role": "system", "content": CONDENSE_SYSTEM}, {"role": "user", "content": user}],
            CURATED_ANSWER_MODELS[0], get_gemini_settings(cfg)["api_key"],
            max_tokens=200, temperature=0.0,
        )
        parsed = _parse_resolve_json(out)
        if parsed is None:
            return question, _heuristic_followup(question)
        is_followup, query = parsed
        if not is_followup:
            # New topic: retrieve on exactly what was asked, ignoring the rewrite entirely.
            return question, False
        return (query or question), True
    except Exception:
        return question, _heuristic_followup(question)


# Clarifying-question generation (the "Ask follow-up" button). NOT vault-grounded -- these are
# standard domain scoping questions, the bounded carve-out already ruled (same class as the
# market-alternatives exemption): they ask the interviewer, assert nothing about the candidate.
CLARIFY_SYSTEM = (
    "You help a candidate SCOPE a technical interview question BEFORE answering it. Produce 2-3 short, "
    "high-value CLARIFYING QUESTIONS the candidate should ask the interviewer so they understand the "
    "real requirements instead of assuming -- the kind a senior engineer asks. Examples of the KIND: "
    "'Is this a stateless web tier or a stateful database?'  'What are your RTO and RPO?'  'How much "
    "downtime is acceptable?'  'Do you have immutable backups to recover a known-good state?'.\n"
    "RULES:\n"
    "- They are questions the candidate ASKS THE INTERVIEWER -- never statements about the candidate, "
    "never a claim of experience.\n"
    "- Standard domain/scoping questions only; invent no specifics about the environment.\n"
    "- Tailor them to THIS question. One line each. Output ONLY the questions, one per line, no "
    "numbering and no preamble."
)


_scoping_bank_cache: Dict[str, str] = {}


def load_scoping_bank(cfg: dict, script_dir: Path) -> str:
    """The owner's curated scoping-question bank (reference-notes/…), if present, minus its leading
    frontmatter/banner. Cached by path. Returns '' when absent ⇒ generic clarify."""
    rel = get_interview_settings(cfg, script_dir).get("scoping_bank_path", "")
    if not rel:
        return ""
    p = Path(rel)
    if not p.is_absolute():
        p = script_dir / p
    key = str(p)
    if key in _scoping_bank_cache:
        return _scoping_bank_cache[key]
    text = ""
    if p.exists():
        try:
            raw = p.read_text(encoding="utf-8", errors="ignore")
            raw = _FRONTMATTER_TIER_RE.sub("", raw, count=1)   # drop a leading --- … --- block
            text = raw.strip()
        except Exception:
            text = ""
    _scoping_bank_cache[key] = text
    return text


def generate_clarify(question: str, cfg: dict, script_dir: Path) -> List[str]:
    """2-3 clarifying questions for a question. Fast model, on demand (the user clicked). If a curated
    scoping bank is configured, it steers the output toward the owner's own bank. Never raises."""
    system = CLARIFY_SYSTEM
    bank = load_scoping_bank(cfg, script_dir)
    if bank:
        system += ("\n\nUse this curated SCOPING-QUESTION BANK as your primary source of ideas -- pick "
                   "and ADAPT the 2-3 most relevant to THIS question (tailor them; don't copy verbatim "
                   "if a sharper version fits). Follow its 'not for lookup questions' rule.\n\n" + bank)
    try:
        out = gemini_chat(
            [{"role": "system", "content": system}, {"role": "user", "content": question}],
            CURATED_ANSWER_MODELS[0], get_gemini_settings(cfg)["api_key"],
            max_tokens=200, temperature=0.4,
        )
        lines = [re.sub(r"^\s*(?:[-*•]|\d+[.)])\s*", "", ln).strip()
                 for ln in (out or "").splitlines() if ln.strip()]
        return [ln for ln in lines if ln][:3]
    except Exception:
        return []


def build_answer_messages(question: str, hits: List[Tuple[float, dict]],
                          mode: str, jd: str = "", humanize: bool = False,
                          depth: str = "balanced", history: Optional[list] = None,
                          detail_requested: bool = False,
                          qclass: str = "direct_factual", altitude: str = "lead",
                          role: str = "general", experience_probe: bool = False,
                          screen_text: str = "", resume: str = "",
                          position: str = "", resolved_question: str = "") -> List[dict]:
    # The CV rides on every framing. It is the candidate's own document, so it is a grounded
    # source; keeping it verbatim rather than indexed is what makes it impossible for an
    # answer to come from a stale copy (the bug that produced an intro from an old resume).
    jd_block = _jd_focus_block(jd) + _resume_block(resume) + _position_block(position)
    # Tone/depth/continuity apply to the EXPERIENCE framings only; study/reference/ungrounded stay
    # short and honest.
    # 'open' is a full-length content framing, so it takes tone/depth/history like grounded does.
    _full = ("grounded", "adjacent", "open", "screen", "profile")
    tone_block = HUMANIZE_ADDENDUM if (humanize and mode in _full) else ""
    depth_block = (depth_profile(depth, detail_requested)["guidance"]
                   if mode in _full else "")
    hist_block = _history_block(history) if mode in _full else ""
    # TERSE is a hard ceiling, so it must reach study/reference too -- those framings normally carry
    # their own "2-4 sentences" length and would otherwise ignore the strip.
    terse = (depth == "terse" and not detail_requested)
    if terse and mode in ("study", "reference"):
        depth_block = depth_profile(depth, detail_requested)["guidance"]
    # Phase-4 doctrine (class SHAPE/VOICE + mode ALTITUDE), appended to every content framing
    # (not ungrounded). direct_factual/behavioural yield '' so they answer immediately.
    doc = doctrine_block(qclass, altitude, detail_requested)
    # Optional role lens, appended to the same content framings as the doctrine. 'general' -> ''.
    rolet = role_block(role)
    if rolet:
        doc = (doc + "\n" + rolet) if doc else rolet
    # ...but at TERSE nothing may fight the one-sentence ceiling. The class SHAPE (checkpoints,
    # assumptions-then-approach), the lead ALTITUDE suppression and the role LENS all push the answer
    # LONGER or re-order it, which is exactly what "to the point" rejects -- so they are dropped and
    # replaced by the single rule that matters. Grounding is untouched; only shape/length is.
    if terse:
        doc = ("\n\nThe DETAIL LEVEL above wins over everything: no approach narration, no "
               "checkpoint list, no scoping preamble, no role framing. One sentence, then stop. "
               "You MAY name the exact technology, feature, or command that answers the question "
               "even at lead altitude -- naming the right thing IS the concise answer.")
    # Provenance is disclosed only when the interviewer actually asks for it (see
    # asks_about_experience). Appended LAST so it outranks the framing's own length rule.
    # On an experience question the CV lines naming the subject ride directly under the rule (see
    # _cv_evidence_block). Matched on the RESOLVED question, so "have you done that in production?"
    # finds the lines for what "that" refers to.
    disc = (DISCLOSURE_BLOCK + _cv_evidence_block(str(resolved_question or "").strip() or question,
                                                  resume)) if experience_probe else ""
    # The disclosure judges from the CV too, so every answer type that carries it must also
    # carry the CV. study and reference normally leave it out (they stay short and honest), so
    # it is added only on an experience question and every other prompt is unchanged.
    cv_probe = _resume_block(resume) if experience_probe else ""
    # Voice and punctuation ride on EVERY answer type, appended last (see VOICE_RULE).
    voice = VOICE_RULE + STYLE_RULE

    # A follow-up like "how would you handle THAT on an Azure VM?" cannot be answered on its own.
    # condense_query already resolves it into a standalone question, but only for RETRIEVAL: the
    # experience framings carry the conversation into the prompt (hist_block), while study,
    # reference and ungrounded received the bare original -- so the model had no referent for
    # "that". Measured before this change: on a study-tier follow-up, history was absent from the
    # prompt on every model tested. The RESOLVED question closes the gap WITHOUT importing prior
    # answers, which on a study/reference framing would pull the reply toward the experience voice
    # the tier ceiling exists to prevent. The interviewer's own words stay first.
    resolved = str(resolved_question or "").strip()
    q_line = f"Interview question:\n{question}\n\n"
    if resolved and question.strip() and resolved.lower() != question.strip().lower():
        q_line = (f"Interview question:\n{question}\n"
                  f"(In the context of the conversation so far, this means: {resolved})\n\n")

    def context_text() -> str:
        # Label each chunk with its provenance tier so the model can see production vs study vs
        # reference. The deterministic gate already set the framing; this is corroborating signal.
        blocks = []
        for i, (score, r) in enumerate(hits, 1):
            head = f"{r['source']}" + (f" > {r['heading']}" if r.get("heading") else "")
            tier = r.get("tier")
            tag = f"({tier}) " if tier else ""
            blocks.append(f"[{i}] {tag}Source: {head}\n{r['text']}")
        return "\n\n".join(blocks)

    if mode == "study":
        user = (
            f"{q_line}"
            f"CONTEXT (from my STUDY notes -- learned, not operated hands-on):\n{context_text()}\n\n"
            f"Answer following the rules and the doctrine below."
        )
        return [
            {"role": "system", "content": SYSTEM_STUDY + (tone_block if humanize else "")
                                          + depth_block + doc + cv_probe + disc + voice},
            {"role": "user", "content": user},
        ]

    if mode == "reference":
        user = (
            f"{q_line}"
            f"CONTEXT (reference/domain material):\n{context_text()}\n\n"
            f"Answer following the rules and the doctrine below."
        )
        return [
            {"role": "system", "content": SYSTEM_REFERENCE + depth_block + doc + cv_probe + disc + voice},
            {"role": "user", "content": user},
        ]

    if mode == "screen":
        notes = (f"NOTES CONTEXT (the candidate's own material -- for approach and vocabulary, "
                 f"NOT for the facts on screen):\n{context_text()}\n\n") if hits else ""
        user = (
            f"{hist_block}"
            f"SCREEN CONTENT (what the interviewer is showing):\n---\n{screen_text}\n---\n\n"
            f"{notes}"
            f"Interviewer question (may be spoken; if empty, answer what the screen asks):\n"
            f"{question}\n\n"
            f"Answer following the rules."
        )
        return [
            {"role": "system", "content": SYSTEM_SCREEN + jd_block + tone_block + depth_block + doc + voice},
            {"role": "user", "content": user},
        ]

    if mode == "open":
        # General-knowledge answer. CONTEXT is included when retrieval found anything at all (even
        # below the grounding threshold) so real notes still lead where they exist.
        ctx = (f"CONTEXT from my own notes (PREFER this, it is what I actually know):\n"
               f"{context_text()}\n\n") if hits else ""
        user = (
            f"{hist_block}"
            f"Interview question (may be a follow-up to the conversation above):\n{question}\n\n"
            f"{ctx}"
            f"Answer following the rules."
        )
        return [
            {"role": "system", "content": SYSTEM_OPEN + jd_block + tone_block + depth_block + doc + disc + voice},
            {"role": "user", "content": user},
        ]

    if mode == "grounded":
        user = (
            f"{hist_block}"
            f"Interview question (may be a follow-up to the conversation above):\n{question}\n\n"
            f"CONTEXT (from my own notes/resume):\n{context_text()}\n\n"
            f"Answer in the first person following the rules."
        )
        return [
            {"role": "system", "content": SYSTEM_GROUNDED + jd_block + tone_block + depth_block + doc + disc + voice},
            {"role": "user", "content": user},
        ]

    if mode == "adjacent":
        user = (
            f"{hist_block}"
            f"Interview question (may be a follow-up to the conversation above):\n{question}\n\n"
            f"CONTEXT (loosely related, from my own notes/resume):\n{context_text()}\n\n"
            f"Give the brief bridging answer in the first person following the rules."
        )
        return [
            {"role": "system", "content": SYSTEM_ADJACENT + jd_block + tone_block + depth_block + doc + disc + voice},
            {"role": "user", "content": user},
        ]

    if mode == "profile":
        # An identity question. The CV answers it; retrieved notes only add depth.
        ctx = (f"NOTES CONTEXT (optional depth, from my own notes):\n{context_text()}\n\n"
               if hits else "")
        # CV-only mode also sends "How did you..." and behavioural questions here (cv_only_framing).
        # Those ask for a specific thing the candidate did, which a CV rarely records in full:
        # measured on the demo CV, "Tell me about a time you had a conflict with a manager" came back
        # as an invented story built out of the CV's alerting work, on both grounding settings. An
        # identity question never reaches this line, so the normal profile prompt is unchanged.
        story = PAST_WORK_RULE if not asks_about_background(question) else ""
        user = (
            f"{hist_block}"
            f"Interview question:\n{question}\n\n"
            f"{ctx}"
            f"Answer in the first person from my CV, following the rules."
        )
        return [
            {"role": "system", "content": SYSTEM_PROFILE + jd_block + tone_block + depth_block + voice + story},
            {"role": "user", "content": user},
        ]

    # ungrounded -- nothing relevant was retrieved. The CV still rides along, because a
    # question about the candidate's own background is not a topic they lack experience with;
    # without this, "which companies have you worked for" draws an honest-but-absurd refusal.
    _bg_note = ("\n\nIf the question is about the candidate's own background, employers, "
                "education, certifications or career history, answer it from the CANDIDATE "
                "PROFILE -- that is documented fact about them, not a claim of hands-on "
                "expertise.") if resume.strip() else ""
    # An experience question with nothing retrieved can still be answered yes from the CV
    # (a job the notes never covered), so the disclosure rides here too when a CV is loaded.
    _disc_cv = disc if resume.strip() else ""
    return [
        {"role": "system", "content": SYSTEM_UNGROUNDED + _resume_block(resume) + _bg_note + _disc_cv + voice},
        {"role": "user", "content": q_line.rstrip()},
    ]


def sources_of(hits: List[Tuple[float, dict]]) -> List[dict]:
    seen = set()
    out = []
    for score, r in hits:
        head = r["source"] + (f" > {r['heading']}" if r.get("heading") else "")
        if head in seen:
            continue
        seen.add(head)
        out.append({"label": head, "score": round(float(score), 3), "tier": r.get("tier")})
    return out


# ============================================================
# OPENROUTER CHAT (non-stream + stream)
# ============================================================

# ============================================================
# ANTHROPIC (Claude) -- via the official SDK, optional dependency
# ============================================================
#
# This is the ONE provider here that does not go over the shared `requests` session, and that is
# deliberate: Anthropic ships a first-party Python SDK, and hand-rolling its wire format would mean
# owning the streaming event grammar, the thinking/effort surface and the error taxonomy by hand.
# `pip install anthropic`; absent, the error names the package like every other optional path.
#
# Latency note that matters for an interview: on Claude Opus 5 thinking is ON by default, which
# costs seconds before the first token. Rather than disable it (which has documented failure modes
# -- the model can write a tool call into visible text, and can leak thinking tags), we lower the
# EFFORT, which is the supported lever: terse/concise ask for low effort, deep asks for high.
_ANTHROPIC_EFFORT = {"terse": "low", "concise": "low", "balanced": "medium", "deep": "high"}

# `output_config.effort` arrived with the 4.6 generation. OLDER models reject it outright:
#     400 invalid_request_error "This model does not support the effort parameter."
# Haiku 4.5 is in the shipped catalogue and hits exactly that, so it is listed here to save a
# doomed round trip. The list is a SHORTCUT, not the guard -- _is_effort_error below retries
# without effort whichever model complains, because a hardcoded capability list is precisely what
# has broken this app before (the whole gemini-2.5 family retired underneath a pinned catalogue).
_ANTHROPIC_NO_EFFORT = {"claude-haiku-4-5", "claude-sonnet-4-5", "claude-opus-4-1", "claude-3-5-haiku"}


def _model_takes_effort(model: str) -> bool:
    m = (model or "").strip()
    return m not in _ANTHROPIC_NO_EFFORT


def _is_effort_error(e: Exception) -> bool:
    """A 400 caused by our effort setting rather than by the prompt. Same reasoning as
    _is_thinking_config_error on the Gemini path: a wrong capability guess must degrade the
    request, not kill the answer mid-interview."""
    if "BadRequest" not in type(e).__name__:
        return False
    return "effort" in str(e).lower()


def _anthropic_client(settings: dict):
    try:
        import anthropic
    except ImportError:
        raise RuntimeError(
            "Answering with Claude needs the Anthropic SDK. Install it with:"
            + chr(10) + "      pip install anthropic"
        ) from None
    # base_url is passed EXPLICITLY. The SDK otherwise honours ANTHROPIC_BASE_URL from the
    # environment, and that variable is commonly set by other Anthropic tooling on a developer
    # machine (it is set on the machine this was written on) -- which would silently send this
    # app's interview answers to someone else's proxy. Same class of bug as inheriting another
    # project's API key, and the same rule applies: this app names what it uses.
    return anthropic.Anthropic(api_key=settings["api_key"],
                               base_url=settings.get("base_url") or "https://api.anthropic.com")


def _anthropic_args(messages: List[dict], model: str, max_tokens: int,
                    depth: Optional[str]) -> dict:
    """Split our {system,user} message list into Anthropic's system + messages shape."""
    system = ""
    turns: List[dict] = []
    for m in messages:
        if m.get("role") == "system":
            system = (system + chr(10) + chr(10) + m["content"]) if system else m["content"]
        else:
            turns.append({"role": m.get("role") or "user", "content": m["content"]})
    if not turns:
        turns = [{"role": "user", "content": " "}]
    args = {"model": model, "max_tokens": max_tokens, "messages": turns}
    if _model_takes_effort(model):
        args["output_config"] = {"effort": _ANTHROPIC_EFFORT.get(depth or "", "low")}
    if system:
        args["system"] = system
    return args


def _without_effort(args: dict) -> dict:
    out = dict(args)
    oc = dict(out.get("output_config") or {})
    oc.pop("effort", None)
    if oc:
        out["output_config"] = oc
    else:
        out.pop("output_config", None)
    return out


def _anthropic_error(e: Exception) -> RuntimeError:
    """Same intent as _api_error: a sentence the user can act on, not a raw provider dump."""
    name = type(e).__name__
    env = PROVIDERS["anthropic"]["env"]
    if "Authentication" in name or "PermissionDenied" in name:
        return RuntimeError(f"Anthropic rejected the key. Check {env}, or the key you entered in "
                            f"Settings, and that the account has credit.")
    if "NotFound" in name:
        return RuntimeError(f"Anthropic does not recognise that model id. {e}")
    # The account's own spending limit arrives as a 400, not a rate limit. Name it plainly and keep
    # the "regain access on ..." date the API gives (30 Sep 2026, owner's monthly limit ran out).
    if "specified API usage limits" in str(e):
        _when = re.search(r"regain access on (.+?)\.?['\"}]", str(e))
        return RuntimeError("Your Anthropic usage limit is used up"
                            + (f" until {_when.group(1)}" if _when else "")
                            + ". Switch to a Gemini model meanwhile, or raise the limit in the "
                              "Anthropic console.")
    if "RateLimit" in name:
        return RuntimeError("Anthropic rate limited the request. Wait a moment and ask again.")
    if "Connection" in name or "Timeout" in name:
        return RuntimeError(f"Could not reach the Anthropic API ({name}).")
    return RuntimeError(f"Anthropic error ({name}): {str(e)[:300]}")


def chat_anthropic(messages: List[dict], settings: dict, model: str,
                   max_tokens: int = 1500, temperature: float = 0.2,
                   depth: Optional[str] = None) -> str:
    # temperature is accepted for signature symmetry and deliberately NOT sent: the current Claude
    # models reject sampling parameters (HTTP 400). Effort is the equivalent lever and is set above.
    client = _anthropic_client(settings)
    args = _anthropic_args(messages, model, max_tokens, depth)
    try:
        resp = client.messages.create(**args)
    except Exception as e:
        if not _is_effort_error(e):
            raise _anthropic_error(e) from None
        try:
            resp = client.messages.create(**_without_effort(args))
        except Exception as e2:
            raise _anthropic_error(e2) from None
    return "".join(b.text for b in resp.content if getattr(b, "type", "") == "text").strip()


def stream_anthropic(messages: List[dict], settings: dict, model: str,
                     max_tokens: int = 1500, temperature: float = 0.2,
                     depth: Optional[str] = None):
    client = _anthropic_client(settings)
    args = _anthropic_args(messages, model, max_tokens, depth)
    # The retry has to happen BEFORE anything is yielded, or a caller would see a half-written
    # answer restart from the beginning. The 400 lands on stream open, so this is safe.
    try:
        stream_cm = client.messages.stream(**args)
        stream = stream_cm.__enter__()
    except Exception as e:
        if not _is_effort_error(e):
            raise _anthropic_error(e) from None
        try:
            stream_cm = client.messages.stream(**_without_effort(args))
            stream = stream_cm.__enter__()
        except Exception as e2:
            raise _anthropic_error(e2) from None
    # `__enter__` RETURNS the MessageStream -- the manager itself is not the stream. Discarding the
    # return value is what produced "'MessageStreamManager' object has no attribute 'text_stream'".
    # And `text_stream` does not exist in anthropic 1.x at all (it was a 0.x convenience): the
    # stream is ITERATED, and it fires a synthesized `text` event carrying each delta.
    yielded = False
    try:
        for event in stream:
            if getattr(event, "type", "") == "text":
                piece = getattr(event, "text", "")
                if piece:
                    yielded = True
                    yield piece
        if not yielded:
            # Belt and braces against exactly the drift that caused this bug: if a future SDK stops
            # firing `text` events, fall back to the accumulated message rather than streaming
            # nothing at all. The stream is already consumed, so this costs no extra request.
            try:
                final = stream.get_final_message()
                text = "".join(b.text for b in final.content
                               if getattr(b, "type", "") == "text").strip()
            except Exception:
                text = ""
            if text:
                yield text
    except Exception as e:
        raise _anthropic_error(e) from None
    finally:
        try:
            stream_cm.__exit__(None, None, None)
        except Exception:
            pass


# ============================================================
# OPENAI-COMPATIBLE (OpenAI, OpenRouter, and anything speaking the same wire format)
# ============================================================
#
# One implementation for both. OpenRouter deliberately speaks OpenAI's /chat/completions shape, so
# the only differences are the base URL and two optional attribution headers -- not enough to
# justify two copies of the SSE parser.

def _oai_headers(settings: dict) -> dict:
    headers = {
        "Authorization": f"Bearer {settings['api_key']}",
        "Content-Type": "application/json",
    }
    if settings.get("http_referer"):
        headers["HTTP-Referer"] = settings["http_referer"]
    if settings.get("x_title"):
        headers["X-Title"] = settings["x_title"]
    return headers


def _oai_error(label: str, status: int, text: str) -> RuntimeError:
    try:
        msg = json.loads(text).get("error", {}).get("message", text)
    except Exception:
        msg = text
    if status in (401, 403):
        return RuntimeError(f"{label} rejected the key (HTTP {status}). Check the key in Settings "
                            f"or its environment variable, and that the account has credit."
                            + chr(10) + f"  Details: {str(msg)[:200]}")
    if status == 404:
        return RuntimeError(f"{label} does not recognise that model id (HTTP 404). "
                            f"Check the exact id." + chr(10) + f"  Details: {str(msg)[:200]}")
    if status == 429:
        return RuntimeError(f"{label} rate limited the request (HTTP 429). Wait and ask again.")
    return RuntimeError(f"{label} error {status}: {str(msg)[:300]}")


def chat_openai_compat(messages: List[dict], settings: dict, model: str,
                       max_tokens: int = 500, temperature: float = 0.2) -> str:
    label = settings.get("label") or "The provider"
    endpoint = f"{settings['base_url']}/chat/completions"
    body = {"model": model, "messages": messages,
            "temperature": temperature, "max_tokens": max_tokens, "stream": False}
    resp = shared_session().post(endpoint, headers=_oai_headers(settings), json=body, timeout=120)
    if resp.status_code >= 400:
        raise _oai_error(label, resp.status_code, resp.text)
    choices = resp.json().get("choices", [])
    if not choices:
        raise RuntimeError(f"{label} returned no choices")
    content = choices[0].get("message", {}).get("content", "")
    if isinstance(content, list):
        content = chr(10).join(p.get("text", "") for p in content if isinstance(p, dict))
    return str(content).strip()


def stream_openai_compat(messages: List[dict], settings: dict, model: str,
                         max_tokens: int = 500, temperature: float = 0.2):
    label = settings.get("label") or "The provider"
    endpoint = f"{settings['base_url']}/chat/completions"
    body = {"model": model, "messages": messages,
            "temperature": temperature, "max_tokens": max_tokens, "stream": True}
    with shared_session().post(endpoint, headers=_oai_headers(settings), json=body,
                               timeout=120, stream=True) as resp:
        if resp.status_code >= 400:
            raise _oai_error(label, resp.status_code, resp.text)
        resp.encoding = "utf-8"   # latin-1 default mangles non-ASCII in the stream
        for raw in resp.iter_lines(decode_unicode=True):
            if not raw or not raw.startswith("data:"):
                continue
            payload = raw[len("data:"):].strip()
            if payload == "[DONE]":
                break
            try:
                delta = json.loads(payload)["choices"][0].get("delta", {})
            except Exception:
                continue
            piece = delta.get("content")
            if piece:
                yield piece


def verify_provider_key(provider: str, settings: dict) -> None:
    """Prove the key works, or raise with the provider's own reason.

    This exists because the app once stored 101 characters of an ERROR MESSAGE as an API key -- the
    user pasted what was on their screen, the app accepted it without a word, and the only symptom
    was a 401 on the next answer. A key that cannot possibly work must fail at the moment it is
    entered, not in the middle of an interview.

    Every provider here publishes a model-listing endpoint, so verification bills nothing and needs
    no prompt. A network failure is reported as such rather than as a bad key."""
    kind = (PROVIDERS.get(provider) or {}).get("kind")
    label = settings.get("label") or provider
    if kind == "anthropic":
        try:
            _anthropic_client(settings).models.list(limit=1)
        except Exception as e:
            raise _anthropic_error(e) from None
        return
    if kind == "openai_compat":
        list_provider_models(provider, settings)   # raises _oai_error on a bad key
        return
    if kind == "gemini":
        resp = shared_session().get(
            "https://generativelanguage.googleapis.com/v1beta/models",
            params={"key": settings["api_key"], "pageSize": 1}, timeout=30)
        if resp.status_code >= 400:
            raise RuntimeError(_api_error("models", resp.status_code, resp.text))
        return
    raise RuntimeError(f"Cannot verify a key for {label}.")


def list_provider_models(provider: str, settings: dict) -> List[str]:
    """Ask an OpenAI-compatible provider what it actually serves right now.

    This exists because hardcoding a model catalogue has already cost this project a broken app
    once: the whole gemini-2.5 family was retired out from under a pinned config. For providers
    that publish /models, asking beats guessing."""
    resp = shared_session().get(f"{settings['base_url']}/models",
                                headers=_oai_headers(settings), timeout=30)
    if resp.status_code >= 400:
        raise _oai_error(settings.get("label") or provider, resp.status_code, resp.text)
    data = resp.json().get("data") or []
    ids = sorted({str(m.get("id")) for m in data if isinstance(m, dict) and m.get("id")})
    return ids


# ============================================================
# GEMINI CHAT (answer generation -- cheapest, reuses embeddings key)
# ============================================================

def _gemini_parts(messages: List[dict]) -> Tuple[str, str]:
    system = ""
    user = ""
    for m in messages:
        if m["role"] == "system":
            system = m["content"]
        else:
            user = m["content"] if not user else user + "\n\n" + m["content"]
    return system, user


# gemini-2.5-pro thinking is MANDATORY (budget 0 -> HTTP 400 "only works in thinking mode") and it
# dominates pro's latency: measured ~8-10s time-to-first-token at budget 2048, but only ~2-3s at 128.
# In this grounded-RAG app the retrieved context does most of the work, so a small budget keeps pro's
# precision while cutting the stall. Budget is depth-tied; the "fast pro" toggle forces the floor.
# Overridable via interview.pro_thinking_budgets (per-depth).
PRO_THINKING_BUDGETS = {"concise": 256, "balanced": 512, "deep": 1536}
PRO_DEFAULT_BUDGET = 512


def pro_thinking_budget(depth: Optional[str], interview: Optional[dict] = None) -> int:
    """Resolve pro's thinking budget from depth (+ optional config override).

    The "fast pro" toggle used to force a 128 floor here. It was removed: measured on
    gemini-pro-latest it made NO difference (6068ms at budget 512 vs 6109ms at 128), so it was a
    control that looked meaningful and did nothing."""
    budgets = dict(PRO_THINKING_BUDGETS)
    override = (interview or {}).get("pro_thinking_budgets")
    if isinstance(override, dict):
        for k, v in override.items():
            try:
                budgets[str(k).lower()] = int(v)
            except (TypeError, ValueError):
                pass
    return max(1, int(budgets.get((depth or "").lower(), PRO_DEFAULT_BUDGET)))


def _is_thinking_model(model: str) -> bool:
    """True when the model's thinking cannot be switched off (pro tiers). Name-based, because the
    API exposes no capability flag -- but the request path also RETRIES without thinkingConfig on a
    400, so a wrong guess degrades instead of failing."""
    return "pro" in (model or "").lower()


def _thinking_and_output(model: str, max_tokens: int,
                         thinking_budget: Optional[int] = None) -> Tuple[Optional[dict], int]:
    """Model-aware thinking config + output budget. Returns (thinkingConfig | None, out_tokens);
    None means OMIT thinkingConfig entirely and let the model choose.

    Three cases, because Gemini models genuinely differ and getting it wrong is a hard error:
      * THINKING_OFF_MODELS accept thinkingBudget:0 -> thinking OFF, so the whole output budget
        reaches the visible answer. Thinking tokens otherwise count against maxOutputTokens, which
        is what used to truncate answers mid-sentence.
      * pro tiers REJECT budget 0 ("Budget 0 is invalid. This model only works in thinking mode",
        HTTP 400), so they get a bounded budget plus extra output room so thinking cannot starve
        the answer.
      * anything else (unknown / future model) -> omit thinkingConfig. Verified safest default:
        every model probed accepted a request with no thinkingConfig, while several rejected
        budget 0. Still add output room, since thinking will consume part of the budget.
    """
    m = (model or "").strip().lower()
    if m in THINKING_OFF_MODELS:
        return {"thinkingBudget": 0}, max_tokens
    if _is_thinking_model(m):
        budget = thinking_budget if isinstance(thinking_budget, int) and thinking_budget > 0 else 2048
        return {"thinkingBudget": budget}, max(max_tokens, budget + 2000)
    return None, max(max_tokens, max_tokens + 2000)


def _gemini_body(system: str, user: str, max_tokens: int, temperature: float,
                 model: str = "", thinking_budget: Optional[int] = None,
                 images: Optional[List[bytes]] = None) -> dict:
    thinking, out_tokens = _thinking_and_output(model, max_tokens, thinking_budget)
    gen: dict = {"temperature": temperature, "maxOutputTokens": out_tokens}
    # OMIT the key entirely when None -- sending "thinkingConfig": null is itself a 400.
    if thinking is not None:
        gen["thinkingConfig"] = thinking
    parts: List[dict] = [{"text": user}]
    # Images AFTER the text: the instruction should be read first, and the screenshots are the
    # material it refers to.
    for blob in (images or []):
        parts.append({"inline_data": {"mime_type": "image/jpeg",
                                      "data": base64.b64encode(blob).decode("ascii")}})
    return {
        "system_instruction": {"parts": [{"text": system}]},
        "contents": [{"role": "user", "parts": parts}],
        "generationConfig": gen,
    }


def _is_thinking_config_error(status: int, text: str) -> bool:
    """A 400 caused by our thinkingConfig rather than by the prompt. Model thinking rules change
    without notice (the entire 2.5 family became unavailable to new projects overnight), so the
    request path retries once WITHOUT thinkingConfig instead of surfacing a hard failure."""
    if status != 400:
        return False
    t = (text or "").lower()
    return "thinking" in t or "budget" in t


def _body_without_thinking(body: dict) -> dict:
    stripped = json.loads(json.dumps(body))
    stripped.get("generationConfig", {}).pop("thinkingConfig", None)
    return stripped


def gemini_chat(messages: List[dict], model: str, api_key: str,
                max_tokens: int = 1500, temperature: float = 0.2,
                thinking_budget: Optional[int] = None) -> str:
    system, user = _gemini_parts(messages)
    endpoint = f"{GEMINI_BASE}/models/{model}:generateContent?key={api_key}"
    session = shared_session()
    body = _gemini_body(system, user, max_tokens, temperature, model, thinking_budget)
    resp = session.post(endpoint, json=body, timeout=120)
    if _is_thinking_config_error(resp.status_code, resp.text):
        # Our thinking guess was wrong for this model -- retry once letting it decide.
        resp = session.post(endpoint, json=_body_without_thinking(body), timeout=120)
    if resp.status_code >= 400:
        raise RuntimeError(f"Gemini generate error {resp.status_code}: {resp.text[:500]}")
    cands = resp.json().get("candidates", [])
    if not cands:
        raise RuntimeError("Gemini returned no candidates")
    parts = cands[0].get("content", {}).get("parts", [])
    return "".join(p.get("text", "") for p in parts).strip()


def gemini_chat_stream(messages: List[dict], model: str, api_key: str,
                       max_tokens: int = 1500, temperature: float = 0.2,
                       thinking_budget: Optional[int] = None,
                       images: Optional[List[bytes]] = None):
    system, user = _gemini_parts(messages)
    endpoint = f"{GEMINI_BASE}/models/{model}:streamGenerateContent?alt=sse&key={api_key}"
    session = shared_session()
    body = _gemini_body(system, user, max_tokens, temperature, model, thinking_budget, images)
    resp = session.post(endpoint, json=body, timeout=120, stream=True)
    if _is_thinking_config_error(resp.status_code, resp.text):
        # Same retry as gemini_chat: a wrong thinking guess must degrade, not kill the answer.
        resp.close()
        resp = session.post(endpoint, json=_body_without_thinking(body), timeout=120, stream=True)
    with resp:
        if resp.status_code >= 400:
            raise RuntimeError(_api_error("stream", resp.status_code, resp.text, cfg))
        # Gemini's SSE omits a charset, so requests would default to latin-1 and mangle any
        # non-ASCII (em-dashes, smart quotes, accents) that models like 2.5-pro emit. Force UTF-8.
        resp.encoding = "utf-8"
        for raw in resp.iter_lines(decode_unicode=True):
            if not raw or not raw.startswith("data:"):
                continue
            payload = raw[len("data:"):].strip()
            if payload == "[DONE]":
                break
            try:
                cands = json.loads(payload).get("candidates", [])
                for p in cands[0].get("content", {}).get("parts", []):
                    t = p.get("text")
                    if t:
                        yield t
            except Exception:
                continue


# ============================================================
# ANSWER PROVIDER DISPATCH
# ============================================================

def provider_settings(provider: str, cfg: dict, script_dir: Path) -> dict:
    """Everything a chat backend needs for one provider, with the key resolved (env > UI > file)."""
    spec = PROVIDERS.get(provider)
    if not spec:
        raise RuntimeError(f"Unknown provider '{provider}'. Known: {', '.join(PROVIDERS)}.")
    # Package BEFORE key, deliberately. They are independent, but a missing package is the more
    # fundamental blocker -- report it first, or the user pastes a key, sees it accepted, and only
    # then discovers they also needed a pip install. Same principle as the numpy/soundcard ordering.
    missing = provider_missing_package(provider)
    if missing:
        raise RuntimeError(f"Answering with {spec['label']} needs the {missing} package. Install it "
                           f"with:" + chr(10) + f"      pip install {missing}")
    key, _src = resolve_provider_key(provider, cfg, script_dir)
    if not key:
        env = provider_env_name(provider, cfg)
        raise RuntimeError(
            f"No API key for {spec['label']}. Add one in Settings -> API keys, or set the "
            f"{env} environment variable" + (f' (setx {env} "your-key-here", then a NEW terminal)'
                                             if env else "") + ".")
    block = cfg.get(provider) or {}
    return {
        "api_key": key,
        "label": spec.get("short") or spec["label"],
        "base_url": str(block.get("base_url") or spec.get("base_url") or "").rstrip("/"),
        "http_referer": block.get("http_referer", "http://localhost"),
        "x_title": block.get("x_openrouter_title", "Live Interview Assistant"),
    }


def resolve_answer(cfg: dict, script_dir: Path) -> Tuple[str, str]:
    """(provider, model) for the next answer.

    A qualified `provider:model` decides its own provider; a bare id falls back to
    interview.answer_provider, which is what every pre-v3.15 config carries."""
    interview = get_interview_settings(cfg, script_dir)
    provider, model = split_model_id(effective_answer_model(cfg, script_dir))
    return (provider or interview["answer_provider"] or DEFAULT_PROVIDER), model


def _pro_budget(model: str, cfg: dict, script_dir: Path,
                depth: Optional[str]) -> Optional[int]:
    """Thinking budget to pass down, only for gemini-2.5-pro (None otherwise -> flash keeps budget 0)."""
    if not _is_thinking_model(model):
        return None
    return pro_thinking_budget(depth, get_interview_settings(cfg, script_dir))


# AI-style dashes, removed from the ANSWER as it streams (14 Sep 2026). STYLE_RULE asks every model
# not to use them, and Gemini and Sonnet comply, but Haiku still used one in 4 of 25 answers after
# two prompt passes. A prompt rule plateaus; a text rule does not. Only the answer path is filtered.
_DASHES = "\u2014\u2013"                       # em dash, en dash
_DASH_HOLD = " \t\r\n`" + _DASHES


class ProseDashFilter:
    """Swap em and en dashes in answer PROSE for plain punctuation, one streamed piece at a time.

    "the fix \u2014 a restart \u2014 worked" -> "the fix, a restart, worked", "2019\u20132022" -> "2019 to
    2022", "client\u2013server" -> "client-server". Code spans and fenced code are left alone, and so
    are hyphens, double hyphens (a CLI flag is not a dash) and semicolons.

    Streaming costs no visible latency: a piece is passed on at once except for its trailing
    whitespace, dashes or backticks, which wait for the next piece because what they become depends
    on what follows. The words themselves are never held back. Text without a dash comes out
    byte-identical."""

    def __init__(self):
        self.pending = ""
        self.last = ""                                # last character already passed on
        self.in_fence = False
        self.in_inline = False

    def feed(self, piece: str) -> str:
        text = self.pending + (piece or "")
        cut = len(text)
        while cut and text[cut - 1] in _DASH_HOLD:
            cut -= 1
        self.pending = text[cut:]
        return self._convert(text[:cut], final=False)

    def flush(self) -> str:
        text, self.pending = self.pending, ""
        return self._convert(text, final=True)

    def _convert(self, s: str, final: bool) -> str:
        buf: List[str] = []
        i, n = 0, len(s)
        while i < n:
            ch = s[i]
            if ch == "`":
                j = i
                while j < n and s[j] == "`":
                    j += 1
                if j - i >= 3:
                    self.in_fence, self.in_inline = not self.in_fence, False
                elif not self.in_fence:
                    self.in_inline = not self.in_inline
                buf.extend(s[i:j])
                i = j
                continue
            if ch == "\n":
                self.in_inline = False              # an unclosed backtick must not disable the rest
            if ch in _DASHES and not (self.in_fence or self.in_inline):
                i = self._dash(s, i, buf)
                continue
            buf.append(ch)
            i += 1
        out = "".join(buf)
        if out:
            self.last = out[-1]
        return out

    def _dash(self, s: str, i: int, buf: List[str]) -> int:
        ch = s[i]
        stripped = ""
        while buf and buf[-1] in " \t":
            stripped = buf.pop() + stripped
        prev = buf[-1] if buf else self.last
        j = i + 1
        while j < len(s) and s[j] in " \t":
            j += 1
        nxt = s[j] if j < len(s) else ""            # "" only at the very end of the answer
        tight = not stripped and j == i + 1
        if prev.isdigit() and ((ch == "\u2013" and nxt.isalnum()) or (tight and nxt.isdigit())):
            buf.extend(" to ")                      # 2019-2022, 40-50, May 2022 - Present
        elif tight and ch == "\u2013" and prev.isalnum() and nxt.isalnum():
            buf.append("-")                         # client-server
        elif prev in ("", "\n", "\r"):
            buf.extend(stripped + "- ")             # a dash used as a list marker
        elif prev == "|" or nxt == "|":
            buf.extend(" - " if stripped else "-")  # an empty table cell
        elif nxt in ("", "\n", "\r") or nxt in ",.;:!?)":
            pass                                    # nothing to join: drop it
        elif prev in ",;:.!?":
            buf.append(" ")
        elif prev == "(":
            pass
        else:
            buf.extend(", ")
        return j


def clean_answer_punctuation(text: str) -> str:
    """The whole-text form of ProseDashFilter, for answers that are not streamed."""
    f = ProseDashFilter()
    return f.feed(text) + f.flush()


def generate_answer(messages: List[dict], cfg: dict, script_dir: Path,
                    temperature: float = 0.2, max_tokens: int = 1500,
                    depth: Optional[str] = None) -> str:
    return clean_answer_punctuation(_answer_raw(messages, cfg, script_dir, temperature=temperature,
                                               max_tokens=max_tokens, depth=depth))


def generate_answer_stream(messages: List[dict], cfg: dict, script_dir: Path,
                           temperature: float = 0.2, max_tokens: int = 1500,
                           depth: Optional[str] = None,
                           images: Optional[List[bytes]] = None):
    dashes = ProseDashFilter()
    for piece in _answer_stream_raw(messages, cfg, script_dir, temperature=temperature,
                                    max_tokens=max_tokens, depth=depth, images=images):
        out = dashes.feed(piece)
        if out:
            yield out
    tail = dashes.flush()
    if tail:
        yield tail


def _answer_raw(messages: List[dict], cfg: dict, script_dir: Path,
                temperature: float = 0.2, max_tokens: int = 1500,
                depth: Optional[str] = None) -> str:
    provider, model = resolve_answer(cfg, script_dir)
    kind = (PROVIDERS.get(provider) or {}).get("kind")
    if kind == "gemini":
        return gemini_chat(messages, model, get_gemini_settings(cfg)["api_key"],
                           max_tokens=max_tokens, temperature=temperature,
                           thinking_budget=_pro_budget(model, cfg, script_dir, depth))
    if kind == "anthropic":
        return chat_anthropic(messages, provider_settings(provider, cfg, script_dir), model,
                              max_tokens=max_tokens, temperature=temperature, depth=depth)
    if kind == "openai_compat":
        return chat_openai_compat(messages, provider_settings(provider, cfg, script_dir), model,
                                  max_tokens=max_tokens, temperature=temperature)
    raise RuntimeError(
        f"answer_provider '{provider}' is not configured. Known: {', '.join(PROVIDERS)}."
    )


def _answer_stream_raw(messages: List[dict], cfg: dict, script_dir: Path,
                       temperature: float = 0.2, max_tokens: int = 1500,
                       depth: Optional[str] = None,
                       images: Optional[List[bytes]] = None):
    provider, model = resolve_answer(cfg, script_dir)
    # A SCREENSHOT always goes to Gemini, whichever provider is selected. The vision path is
    # measured and tuned here (SCREENSHOT_MODEL caught a KQL bug that the cheaper tier misread), and
    # routing images to a provider whose vision behaviour is unmeasured would silently change the
    # one feature where a confidently wrong reading is worst. Cost is ~$0.0017 a screen question.
    if images:
        provider, model = DEFAULT_PROVIDER, SCREENSHOT_MODEL
    kind = (PROVIDERS.get(provider) or {}).get("kind")
    if kind == "gemini":
        yield from gemini_chat_stream(messages, model, get_gemini_settings(cfg)["api_key"],
                                      max_tokens=max_tokens, temperature=temperature,
                                      thinking_budget=_pro_budget(model, cfg, script_dir, depth),
                                      images=images)
    elif kind == "anthropic":
        yield from stream_anthropic(messages, provider_settings(provider, cfg, script_dir), model,
                                    max_tokens=max_tokens, temperature=temperature, depth=depth)
    elif kind == "openai_compat":
        yield from stream_openai_compat(messages, provider_settings(provider, cfg, script_dir),
                                        model, max_tokens=max_tokens, temperature=temperature)
    else:
        raise RuntimeError(
            f"answer_provider '{provider}' is not configured. Known: {', '.join(PROVIDERS)}."
        )


# ============================================================
# ANSWER ORCHESTRATION
# ============================================================

def answer_once(question: str, cfg: dict, script_dir: Path, jd: Optional[str] = None,
                humanize: Optional[bool] = None, depth: Optional[str] = None,
                mode_altitude: Optional[str] = None,
                role: Optional[str] = None, grounding: Optional[str] = None) -> dict:
    interview = get_interview_settings(cfg, script_dir)
    _prof = active_profile(script_dir)
    _resume_txt, _ = resume_text(script_dir)
    # CV-only (see cv_only_framing): no index, but a CV to answer from. Without a CV the missing
    # index is still the error the user needs to see.
    try:
        index = load_vector_index(script_dir)
    except SetupError:
        if not _resume_txt.strip():
            raise
        index = None
    cv_only = index is None or not index.rows
    if jd is None:
        jd = load_jd(cfg, script_dir)
    if humanize is None:
        humanize = effective_humanize(cfg, script_dir)
    if depth not in VALID_DEPTHS:
        depth = effective_depth(cfg, script_dir)
    altitude = mode_altitude if mode_altitude in VALID_MODES else effective_mode(cfg, script_dir)
    if role not in VALID_ROLES:
        role = effective_role(cfg, script_dir)
    if grounding not in VALID_GROUNDING:
        grounding = effective_grounding(cfg, script_dir)
    detail_requested = wants_detail(question)
    qclass = classify_question(question)
    prof = depth_profile(depth, detail_requested)

    hits = [] if cv_only else retrieve(question, index, cfg, script_dir, prof["top_k"])
    top_score = hits[0][0] if hits else 0.0
    mode = classify_mode(top_score, interview["min_score"], interview["adjacent_margin"])
    # Provenance gate: cap the answer's framing at the top hit's tier (study/reference can't claim
    # hands-on). None when the index carries no tiers -> unchanged score behaviour.
    ceiling = (experience_ceiling(hits, interview["tier_ceiling_margin"], question)
               if interview.get("vault_tiers") and not cv_only else None)
    base_framing = resolve_framing(mode, ceiling)
    framing = apply_grounding(base_framing, grounding)
    if cv_only and _resume_txt.strip():
        framing = cv_only_framing(question, grounding)
    grounded = framing == "grounded"
    # When the vault had NOTHING (base was ungrounded), the retrieved chunks are by definition
    # below threshold -- feeding them to the 'open' framing as "PREFER this" makes the model anchor
    # on irrelevant notes and answer with a resume dump instead of the question. Drop them.
    ctx_hits = [] if base_framing == "ungrounded" else hits
    # 'open' shows sources only when retrieval actually contributed something.
    show_sources = framing != "ungrounded" and not (framing == "open" and not ctx_hits)

    if _resume_txt.strip() and asks_about_background(question):
        framing = "profile"
    messages = build_answer_messages(question, ctx_hits, framing, jd, humanize=humanize, depth=depth,
                                     detail_requested=detail_requested, qclass=qclass,
                                     altitude=altitude, role=role,
                                     experience_probe=asks_about_experience(question),
                                     resume=_resume_txt,
                                     position=str(_prof.get("position") or ""))
    _ = grounding  # already folded into `framing` above
    text = generate_answer(messages, cfg, script_dir, temperature=temperature_for_mode(framing),
                           max_tokens=prof["max_tokens"], depth=depth)
    badge_mode, badge_tier = badge_for(framing, ceiling, asks_about_experience(question), hits,
                                       question, _resume_txt, notes_used=bool(ctx_hits))
    return {
        "answer": text,
        "grounded": badge_mode == "grounded",
        "mode": badge_mode,
        "ceiling_tier": badge_tier,
        "framing": framing,
        "cv_only": cv_only,
        "top_score": round(float(top_score), 3),
        "sources": sources_of(hits) if show_sources else [],
    }


# ============================================================
# LOOPBACK CAPTURE + GEMINI "CLOUD STT"  (interviewer audio)
# ============================================================
#
# Fully decoupled from /ask. Requires the optional `soundcard` package and `numpy`.
# Captures the default speaker's WASAPI loopback at 16 kHz mono, segments utterances by
# energy (RMS) with a trailing-silence hangover, converts each utterance to 16-bit PCM WAV,
# and transcribes it by POSTing inline audio to the SAME Gemini generateContent endpoint/key.
#
#   pip install soundcard numpy      (webrtcvad is optional and NOT required)

def gemini_transcribe_wav(wav_bytes: bytes, cfg: dict, script_dir: Path,
                          timeout: int = 120) -> str:
    """Transcribe WAV audio bytes via Gemini inline audio (same key as embeddings/answers)."""
    interview = get_interview_settings(cfg, script_dir)
    api_key = get_gemini_settings(cfg)["api_key"]
    model = interview["stt_model"]
    endpoint = f"{GEMINI_BASE}/models/{model}:generateContent?key={api_key}"
    b64 = base64.b64encode(wav_bytes).decode("ascii")
    thinking, out_tokens = _thinking_and_output(model, 1500)
    body = {
        "contents": [{
            "role": "user",
            "parts": [
                {"inline_data": {"mime_type": "audio/wav", "data": b64}},
                {"text": "Transcribe this audio verbatim; return only the spoken words."},
            ],
        }],
        "generationConfig": {
            "temperature": 0,
            "maxOutputTokens": out_tokens,
            "thinkingConfig": thinking,
        },
    }
    session = shared_session()
    resp = session.post(endpoint, json=body, timeout=timeout)
    if resp.status_code >= 400:
        raise RuntimeError(f"Gemini STT error {resp.status_code}: {resp.text[:500]}")
    cands = resp.json().get("candidates", [])
    if not cands:
        return ""
    parts = cands[0].get("content", {}).get("parts", [])
    return "".join(p.get("text", "") for p in parts).strip()


def _pcm16_wav_bytes(mono_float, sample_rate: int) -> bytes:
    """Convert a float32 mono numpy array in [-1, 1] to 16-bit PCM WAV bytes (stdlib wave)."""
    clipped = _np.clip(mono_float, -1.0, 1.0)
    pcm16 = (clipped * 32767.0).astype("<i2")
    buf = io.BytesIO()
    with wave.open(buf, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(sample_rate)
        w.writeframes(pcm16.tobytes())
    return buf.getvalue()


# Gemini bills audio input at a flat 32 tokens per second of audio, priced as flash audio input.
# Overridable via config in case the published rate changes -- the point is a live, visible estimate,
# not billing-grade accounting.
AUDIO_TOKENS_PER_SECOND = 32
STT_AUDIO_USD_PER_1M = 1.00


class SttMeter:
    """Running tally of how much audio the transcriber has SENT this listening session.

    Exists because transcription is the only cost in this app that accrues without anyone asking a
    question: loopback captures whatever plays through the speakers, so a lecture, a call or a video
    left playing with listening ON bills continuously and invisibly. This turns that into a number
    on screen. Thread-safe -- finals and partials are dispatched from separate daemon threads.
    """

    def __init__(self, usd_per_1m: float = STT_AUDIO_USD_PER_1M,
                 tokens_per_second: int = AUDIO_TOKENS_PER_SECOND):
        self._lock = threading.Lock()
        self.usd_per_1m = usd_per_1m
        self.tokens_per_second = tokens_per_second
        self.reset()

    def reset(self) -> None:
        with self._lock:
            self.started = time.time()
            self.audio_seconds = 0.0      # audio actually uploaded (deltas + finals)
            self.calls = 0
            self.partials = 0
            self.finals = 0

    def add(self, seconds: float, final: bool) -> None:
        with self._lock:
            self.audio_seconds += max(0.0, float(seconds))
            self.calls += 1
            if final:
                self.finals += 1
            else:
                self.partials += 1

    def snapshot(self) -> dict:
        with self._lock:
            tokens = self.audio_seconds * self.tokens_per_second
            return {
                "audio_seconds": round(self.audio_seconds, 1),
                "audio_tokens": int(tokens),
                "calls": self.calls,
                "partials": self.partials,
                "finals": self.finals,
                "elapsed_seconds": round(time.time() - self.started, 1),
                "est_usd": round(tokens * self.usd_per_1m / 1_000_000, 4),
            }

    def summary(self) -> str:
        s = self.snapshot()
        return (f"{s['audio_seconds']:.0f}s audio sent in {s['calls']} calls "
                f"({s['partials']} partial / {s['finals']} final) "
                f"~= {s['audio_tokens']:,} audio tokens ~= ${s['est_usd']:.4f} "
                f"| listening {s['elapsed_seconds'] / 60:.1f} min")


class LoopbackTranscriber:
    """Daemon thread: capture speaker loopback, segment by energy, Gemini-transcribe utterances.

    Transcribed segments are pushed onto a thread-safe queue as {"text": str, "ts": epoch}.
    NEVER raises out of the thread -- transcription errors are swallowed per-utterance so the
    capture loop keeps running. start() returns (ok, info) and never crashes the server.
    """

    def __init__(self, cfg: dict, script_dir: Path, bus: Optional["SessionBus"] = None,
                 decorate=None, on_stopped=None):
        self.cfg = cfg
        self.script_dir = script_dir
        interview = get_interview_settings(cfg, script_dir)
        self.sample_rate = interview["stt_sample_rate"]
        self.silence_threshold = interview["silence_threshold"]
        self.hangover_ms = interview["silence_hangover_ms"]
        self.partial_interval_ms = interview["partial_stt_interval_ms"]
        self.tail_flush_ms = interview["partial_tail_flush_ms"]
        # Segments are published to the SessionBus so every connected device gets EVERY segment.
        # (This was a single queue.Queue whose get() removed the item -- with a phone mirror
        # connected, transcript lines were split at random between the two screens.)
        self.bus = bus
        # Optional hook that stamps each segment before it goes out (used to mark segments captured
        # while scoping as replies, and to track "the question currently being asked").
        self.decorate = decorate
        # Called if capture stops on its own (device error), so the UI can't keep claiming it is
        # listening when it is not -- previously the thread just died silently mid-interview.
        self.on_stopped = on_stopped
        # Accumulated PARTIAL text per utterance. Partials now transcribe only the NEW audio since
        # the previous partial (a "delta"); the running text is rebuilt here. Re-sending the whole
        # utterance every 2.5s meant a 60s question uploaded ~38MB of base64 and starved the 100ms
        # capture loop -- which is what produced "data discontinuity in recording".
        self._utt_text: Dict[int, str] = {}
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None
        self.device_name: Optional[str] = None
        self._lock = threading.Lock()
        self._utt = 0                 # utterance id, increments when a new utterance opens
        self._partial_busy = False    # one partial transcription in flight at a time
        # --- cost visibility + auto-stop guards -------------------------------------------------
        # Two DIFFERENT failure modes, and they need two different limits:
        #  * idle  -- listening left on in a quiet room. Costs nothing today (the VAD gates on
        #    energy), but it leaves the UI lying about state and one noise burst starts billing.
        #  * max session -- listening left on while ANY audio plays (a lecture, a call, a video).
        #    The idle timer NEVER fires here, because from the VAD's point of view someone is
        #    talking the whole time. This is the one that actually costs money, so the wall-clock
        #    cap is the load-bearing guard, not the idle one.
        self.meter = SttMeter(usd_per_1m=interview["stt_audio_usd_per_1m"])
        self.idle_stop_s = max(0.0, interview["stt_idle_stop_minutes"] * 60.0)
        self.max_session_s = max(0.0, interview["stt_max_session_minutes"] * 60.0)
        self.on_meter = None          # optional callback(snapshot) for periodic UI/console updates

    def is_running(self) -> bool:
        return self._thread is not None and self._thread.is_alive()

    def start(self) -> Tuple[bool, str]:
        with self._lock:
            if self.is_running():
                return True, self.device_name or "already listening"
            # numpy is checked FIRST because `soundcard` imports it: without numpy, soundcard is
            # unimportable too, and reporting "install soundcard" sends a user who already has it
            # chasing the wrong package. Root cause before symptom.
            if _np is None:
                return False, ("numpy is required for loopback capture (pip install numpy). "
                               "The 'soundcard' package needs it too.")
            if _soundcard is None:
                return False, "The 'soundcard' package is not installed (pip install soundcard)."
            try:
                mic = self._find_loopback_mic()
            except Exception as e:
                return False, f"Could not open a loopback device: {e}"
            if mic is None:
                return False, "No WASAPI loopback device found for the default speaker."
            self.device_name = getattr(mic, "name", "loopback")
            # Re-read the interviewer-pause duration so a Settings change applies on next Start.
            self.hangover_ms = effective_hangover_ms(self.cfg, self.script_dir)
            # Each Start begins a fresh billing session, so the on-screen number always means
            # "this listening session" rather than "since the process booted".
            self.meter.reset()
            # soundcard warns per occurrence; once we know the device is glitching, repeating it
            # every frame just buries real output. Show it once per run.
            warnings.filterwarnings("once", message=".*data discontinuity.*")
            self._stop.clear()
            # (No stale-segment drain needed: the bus publishes to per-subscriber queues, and a
            # client that connects later simply never sees segments produced before it subscribed.)
            self._thread = threading.Thread(target=self._run, args=(mic,), daemon=True)
            self._thread.start()
            return True, self.device_name

    def stop(self) -> None:
        self._stop.set()
        t = self._thread
        if t is not None:
            t.join(timeout=3.0)
        self._thread = None

    def _find_loopback_mic(self):
        # Prefer a loopback mic matching the default speaker; fall back to any loopback mic.
        try:
            spk = _soundcard.default_speaker()
            mic = _soundcard.get_microphone(id=str(spk.name), include_loopback=True)
            if mic is not None:
                return mic
        except Exception:
            pass
        for m in _soundcard.all_microphones(include_loopback=True):
            if getattr(m, "isloopback", False):
                return m
        return None

    def _run(self, mic) -> None:
        sr = self.sample_rate
        frame = max(1, int(sr * 0.1))  # ~100 ms frames
        hangover_s = self.hangover_ms / 1000.0
        partial_interval_s = max(1.0, self.partial_interval_ms / 1000.0)
        threshold = self.silence_threshold
        voiced: List = []
        trailing_silence = 0.0
        speech_time = 0.0
        utt = 0            # current open utterance id (0 = none open)
        seq = 0            # per-utterance partial sequence
        last_partial = 0.0 # monotonic time of the last partial dispatch
        partial_cursor = 0 # frames of `voiced` already sent as partial DELTAS
        tail_flush_s = self.tail_flush_ms / 1000.0   # 0 disables the end-of-speech flush
        tail_flushed = False  # one flush per silence run, reset the moment speech resumes
        read_errors = 0    # consecutive rec.record() failures
        stop_reason = ""
        session_start = time.monotonic()
        last_voice = session_start   # monotonic time of the last frame above the speech threshold
        last_meter_log = session_start
        meter_log_interval_s = 300.0
        try:
            with mic.recorder(samplerate=sr, channels=1, blocksize=frame) as rec:
                while not self._stop.is_set():
                    try:
                        data = rec.record(numframes=frame)
                        read_errors = 0
                    except Exception as e:
                        # A single WASAPI hiccup used to `break` here -- the capture thread died
                        # silently and the UI went on claiming it was listening for the rest of the
                        # interview. Ride out transient errors; only give up (loudly) if it persists.
                        read_errors += 1
                        if read_errors >= 10:
                            stop_reason = f"audio device stopped responding ({e})"
                            break
                        time.sleep(0.05)
                        continue
                    if data is None or len(data) == 0:
                        continue
                    mono = data[:, 0] if getattr(data, "ndim", 1) > 1 else data
                    rms = float(_np.sqrt(_np.mean(_np.square(mono)))) if mono.size else 0.0
                    frame_s = len(mono) / sr
                    if rms >= threshold:
                        if not voiced:
                            # new utterance opens
                            self._utt += 1
                            utt = self._utt
                            seq = 0
                            partial_cursor = 0
                            last_partial = time.monotonic()
                        # Speech resumed -- this was a pause mid-question, not the end of it, so
                        # arm the flush again for the next time they stop.
                        tail_flushed = False
                        voiced.append(_np.asarray(mono, dtype=_np.float32).copy())
                        speech_time += frame_s
                        trailing_silence = 0.0
                    elif voiced:
                        # keep trailing silence as part of the utterance tail
                        voiced.append(_np.asarray(mono, dtype=_np.float32).copy())
                        trailing_silence += frame_s
                        # ---- TAIL FLUSH -------------------------------------------------------
                        # The moment the speaker stops, transcribe whatever has not been sent yet
                        # instead of waiting for the next 2.5s partial tick or for the hangover.
                        #
                        # This is what removes the "dead wait at the end". The old end-of-question
                        # path stacked TWO delays: up to partial_interval_s for the tail words, and
                        # then hangover_s before the final's FULL re-transcription even started.
                        # The tail delta is at most one partial interval of audio, so it comes back
                        # in ~2s and the complete question is on screen while the hangover is still
                        # running. That decouples "the text is complete" from "the utterance is
                        # closed" -- so the hangover can now be tuned purely for SEGMENTATION
                        # (long enough not to split a question) without costing responsiveness.
                        if (tail_flush_s and not tail_flushed and speech_time >= 1.0
                                and trailing_silence >= tail_flush_s
                                and not self._partial_busy and len(voiced) > partial_cursor):
                            delta = voiced[partial_cursor:]
                            partial_cursor = len(voiced)
                            self._partial_busy = True
                            last_partial = time.monotonic()
                            tail_flushed = True
                            seq += 1
                            self._dispatch(delta, sr, utt, seq, final=False)
                        if trailing_silence >= hangover_s:
                            if speech_time >= 0.4:
                                seq += 1
                                self._dispatch(list(voiced), sr, utt, seq, final=True)
                            voiced = []
                            trailing_silence = 0.0
                            speech_time = 0.0
                            utt = 0
                            partial_cursor = 0
                            tail_flushed = False
                    # Live partial: transcribe only the audio added SINCE the last partial. Sending
                    # the whole utterance each time grew quadratically (a 60s question uploaded
                    # ~38MB of base64 across 30 partials), which starved this 100ms read loop and
                    # produced "data discontinuity in recording". The final still re-transcribes the
                    # complete utterance, so accuracy is unchanged.
                    if (voiced and speech_time >= 1.0 and not self._partial_busy
                            and time.monotonic() - last_partial >= partial_interval_s
                            and len(voiced) > partial_cursor):
                        delta = voiced[partial_cursor:]
                        partial_cursor = len(voiced)
                        self._partial_busy = True
                        last_partial = time.monotonic()
                        seq += 1
                        self._dispatch(delta, sr, utt, seq, final=False)

                    # ---- cost guards -------------------------------------------------------
                    now = time.monotonic()
                    if rms >= threshold:
                        last_voice = now
                    # Wall-clock cap. This is the guard that catches the expensive case (audio
                    # playing while nobody is interviewing), because that case never looks idle.
                    if self.max_session_s and (now - session_start) >= self.max_session_s:
                        stop_reason = (f"listening auto-stopped after "
                                       f"{self.max_session_s / 60:.0f} min (session limit) "
                                       f"- {self.meter.summary()}")
                        break
                    # Idle cap. Cheap tidy-up: nobody has spoken for a long time.
                    if self.idle_stop_s and (now - last_voice) >= self.idle_stop_s:
                        stop_reason = (f"listening auto-stopped after "
                                       f"{self.idle_stop_s / 60:.0f} min with no speech "
                                       f"- {self.meter.summary()}")
                        break
                    # Periodic visibility while it IS running, so a leak is noticed in minutes
                    # rather than on next month's bill.
                    if now - last_meter_log >= meter_log_interval_s:
                        last_meter_log = now
                        if self.on_meter is not None:
                            try:
                                self.on_meter(self.meter.snapshot())
                            except Exception:
                                pass
                # flush a final in-progress utterance on stop
                if voiced and speech_time >= 0.4:
                    self._dispatch(list(voiced), sr, utt, seq + 1, final=True)
        except Exception as e:
            # never let the capture thread crash the process
            stop_reason = stop_reason or f"capture failed ({e})"
        finally:
            # If we stopped for any reason OTHER than an explicit stop(), say so: a silent death
            # left the overlay showing "Stop listening" for the rest of the interview.
            if not self._stop.is_set() and self.on_stopped is not None:
                try:
                    self.on_stopped(stop_reason or "audio capture ended unexpectedly")
                except Exception:
                    pass

    def _dispatch(self, voiced: List, sr: int, utt: int, seq: int, final: bool) -> None:
        """Transcribe a snapshot of the utterance off the capture thread (never blocks it)."""
        t = threading.Thread(target=self._transcribe_async,
                             args=(voiced, sr, utt, seq, final), daemon=True)
        t.start()

    def _transcribe_async(self, voiced: List, sr: int, utt: int, seq: int, final: bool) -> None:
        try:
            audio = _np.concatenate(voiced)
            # Count what we are about to UPLOAD, before the call -- a request that fails or times
            # out has still been billed, so metering the success path would under-report.
            self.meter.add(len(audio) / float(sr), final)
            wav_bytes = _pcm16_wav_bytes(audio, sr)
            # Partials get a short timeout — a stale partial is worthless; finals keep the
            # generous timeout so a slow network never loses a whole question.
            text = gemini_transcribe_wav(wav_bytes, self.cfg, self.script_dir,
                                         timeout=120 if final else 20)
            if final:
                # The final transcribes the WHOLE utterance, so it supersedes the accumulation.
                self._utt_text.pop(utt, None)
            elif text:
                # A partial only carried the delta audio; rebuild the running text for this
                # utterance so subscribers still receive the full question-so-far.
                running = (self._utt_text.get(utt, "") + " " + text).strip()
                self._utt_text[utt] = running
                text = running
            if text and self.bus is not None:
                seg = {"text": text, "ts": time.time(),
                       "utt": utt, "seq": seq, "partial": not final}
                if self.decorate is not None:
                    try:
                        seg = self.decorate(seg) or seg
                    except Exception:
                        pass
                self.bus.publish("segment", seg)
        except Exception:
            # swallow per-utterance errors; keep listening
            pass
        finally:
            if not final:
                self._partial_busy = False


# ============================================================
# SCREEN CONTEXT via CDP  (Path A: read the page, do not photograph it)
# ============================================================
# Some interviews put the question on the SCREEN, not in the audio: review this KQL, diagnose this
# case study. Loopback capture cannot see any of it.
#
# Why DOM text rather than a screenshot: a screenshot is viewport-limited, and these pages routinely
# nest a scrollable box inside the page. Measured on a mock of exactly that shape -- 9,796px of
# content in a 105px box -- a screenshot saw ZERO complete lines while document.innerText returned
# all 60, including the line scrolled ~9,700px out of view. DOM extraction is also exact (no OCR),
# ~50ms, needs no vision model, and requires no scrolling, so nothing moves on a shared screen.
#
# Requires the browser started with --remote-debugging-port. Chrome/Edge speak CDP; Firefox dropped
# CDP for WebDriver BiDi and is driven through that instead (see _BidiSession) -- same capability,
# different protocol. The screenshot path (B) is only for what is not a browser at all.
CDP_DEFAULT_URL = "http://127.0.0.1:9222"

# Never read from these -- they are never the interview question, and one of them (an extension
# background page) is what a naive "first target wins" rule would have grabbed on this machine.
_CDP_SKIP_PREFIXES = ("devtools://", "chrome-extension://", "chrome://", "edge://", "about:")


def _cdp_targets(base: str, timeout: float = 3.0) -> List[dict]:
    with urlopen_compat(base.rstrip("/") + "/json/list", timeout) as r:
        return json.loads(r.read().decode("utf-8", "replace"))


def urlopen_compat(url: str, timeout: float):
    import urllib.request
    return urllib.request.urlopen(url, timeout=timeout)


def _cdp_eval(ws_url: str, expression: str, timeout: float = 8.0):
    """One Runtime.evaluate over the target's websocket. Returns the value, or raises."""
    import websocket  # optional dep; caller handles ImportError
    # Chrome >= 111 rejects the CDP socket unless the client suppresses its Origin header.
    ws = websocket.create_connection(ws_url, timeout=timeout, suppress_origin=True)
    try:
        ws.send(json.dumps({"id": 1, "method": "Runtime.evaluate",
                            "params": {"expression": expression, "returnByValue": True,
                                       "awaitPromise": True}}))
        deadline = time.time() + timeout
        while time.time() < deadline:
            msg = json.loads(ws.recv())
            if msg.get("id") == 1:
                res = msg.get("result", {})
                if "exceptionDetails" in res:
                    raise RuntimeError(str(res["exceptionDetails"])[:200])
                return res.get("result", {}).get("value")
        raise TimeoutError("CDP evaluate timed out")
    finally:
        try:
            ws.close()
        except Exception:
            pass


_CDP_STATE_JS = "JSON.stringify({v:document.visibilityState,f:document.hasFocus()})"


def cdp_pick_page(base: str, url_hint: str = "", timeout: float = 3.0) -> Tuple[Optional[dict], List[dict]]:
    """Choose WHICH tab to read. Returns (chosen, all_candidates).

    You will have other tabs open -- course material, docs, whatever -- so this must not simply take
    the first one. Precedence:
      1. a configured url_hint (e.g. "interview-platform.example") that is also visible,
      2. the tab that is BOTH focused and visible -- during an interview that is the interview tab,
      3. any visible tab (covers a second window that lost OS focus to the overlay),
      4. nothing, and say so with the candidate list rather than guessing.
    Background tabs report visibilityState 'hidden', which is what makes this reliable.
    """
    cands = [t for t in _cdp_targets(base, timeout)
             if t.get("type") == "page"
             and not str(t.get("url", "")).startswith(_CDP_SKIP_PREFIXES)
             and t.get("webSocketDebuggerUrl")]
    scored = []
    for t in cands:
        try:
            st = json.loads(_cdp_eval(t["webSocketDebuggerUrl"], _CDP_STATE_JS, timeout) or "{}")
        except Exception:
            st = {}
        t = dict(t, _visible=(st.get("v") == "visible"), _focused=bool(st.get("f")))
        scored.append(t)
    # Hints are a LIST, and they never outrank the tab you are actually looking at. A single
    # hardcoded domain is a footgun: with one platform's domain pinned, a stale tab from it left open
    # in the background would beat the interview you are really sitting in with another company. So the
    # hint only breaks ties AMONG plausible tabs -- the focused, visible one always wins first.
    hints = [h.strip().lower() for h in (url_hint if isinstance(url_hint, list) else [url_hint or ""])
             if str(h).strip()]

    def _hinted(t) -> bool:
        u = str(t.get("url", "")).lower()
        return any(h in u for h in hints)

    for t in scored:
        if _hinted(t) and t["_focused"] and t["_visible"]:
            return t, scored
    for t in scored:
        if t["_focused"] and t["_visible"]:
            return t, scored
    for t in scored:
        if _hinted(t) and t["_visible"]:
            return t, scored
    for t in scored:
        if t["_visible"]:
            return t, scored
    # Nothing visible (see the occlusion note below) -- now a hint is the best signal available.
    for t in scored:
        if _hinted(t):
            return t, scored
    # Nothing reports visible. Chrome marks a FULLY OCCLUDED window hidden, so this happens when the
    # browser is buried behind other windows -- which is normal while you are reading the overlay.
    # With exactly one candidate there is no ambiguity and nothing to get wrong, so read it.
    if len(scored) == 1:
        return scored[0], scored
    return None, scored


# Prefer the main content region so page chrome (nav, cookie banners) does not crowd out the
# question, but fall back to body -- interview apps rarely use semantic landmarks.
_CDP_TEXT_JS = """(() => {
  const pick = document.querySelector('main, [role="main"], article') || document.body;
  const t = (pick.innerText || '').trim();
  return JSON.stringify({title: document.title, url: location.href, text: t});
})()"""


def screen_read_text(cfg: dict, script_dir: Path) -> dict:
    """Read the active browser tab's text, over CDP or BiDi. Never raises; {'ok': False, 'error'}.

    Reads the top document AND every nested frame. That is not a nicety: a real interview platform
    renders the whole case study inside a sandboxed iframe, and innerText does not cross
    that boundary -- so reading only the top document returned the logo and the timer while the
    candidate was looking at four answer boxes.
    """
    iv = get_interview_settings(cfg, script_dir)
    base = iv["screen_cdp_url"]
    try:
        import websocket  # noqa: F401
    except Exception:
        return {"ok": False, "error": "The 'websocket-client' package is not installed "
                                      "(pip install websocket-client)."}
    kind = detect_browser_kind(base)
    if kind == "none":
        return _no_browser_error(base)
    try:
        if kind == "cdp":
            page, cands = cdp_pick_page(base, iv["screen_url_hint"])
            if page is None:
                titles = [f"{(t.get('title') or '?')[:40]}" for t in cands[:5]]
                return {"ok": False, "error": "No visible browser tab found."
                                              + (f" Saw: {', '.join(titles)}" if titles else
                                                 " No ordinary page tabs are open on that port.")}
            with _cdp_frames(base, page) as (frames, _main):
                parts, head = _read_frames_text(frames)
                nframes = len(frames)
            title = page.get("title") or head.get("title") or ""
            url = head.get("url") or ""
        else:
            with _BidiSession(base) as sess:
                ctx0, cands = bidi_pick_context(sess, iv["screen_url_hint"])
                if ctx0 is None:
                    titles = [f"{(t.get('title') or '?')[:40]}" for t in cands[:5]]
                    return {"ok": False, "error": "No visible browser tab found."
                                                  + (f" Saw: {', '.join(titles)}" if titles else
                                                     " No ordinary tabs are open on that port.")}
                frames = _bidi_frames(sess, ctx0["context"])
                parts, head = _read_frames_text(frames)
                nframes = len(frames)
            title = ctx0.get("title") or head.get("title") or ""
            url = head.get("url") or ""
    except Exception as e:
        return {"ok": False, "error": f"Could not read the tab: {str(e)[:160]}"}
    # Collapse runs of blank lines here rather than in the injected JS: escaping a newline
    # through a Python literal into a JS regex is a needless hazard, and it broke twice.
    text = re.sub(r"\n{3,}", "\n\n", "\n\n".join(parts)).strip()
    cap = iv["screen_max_chars"]
    truncated = len(text) > cap
    if truncated:
        text = text[:cap]
    if not text:
        return {"ok": False, "error": "That tab has no readable text (canvas or image-only?)."}
    # A page shell with no content reads as a SUCCESS otherwise, which is worse than a failure:
    # it silently pre-empts the screenshot fallback and the model answers from nothing. Measured
    # live -- a platform's page shell returned 18 characters and the answer came out of conversation
    # history instead. Below the floor, fail loudly so Path B takes over.
    floor = iv["screen_min_chars"]
    if floor and len(text) < floor:
        return {"ok": False, "thin": True, "chars": len(text), "title": title,
                "error": (f"Only {len(text)} characters were readable on \"{title[:40]}\" "
                          f"({nframes} frame(s) checked) - that looks like a page shell, "
                          f"not the question.")}
    return {"ok": True, "via": kind, "text": text, "title": title,
            "url": url, "chars": len(text), "truncated": truncated,
            "tabs_seen": len(cands), "frames": nframes}


def screen_list_boxes(cfg: dict, script_dir: Path) -> dict:
    """Enumerate the answer boxes on the interview tab, across every frame. Never raises."""
    iv = get_interview_settings(cfg, script_dir)
    base = iv["screen_cdp_url"]
    try:
        import websocket  # noqa: F401
    except Exception:
        return {"ok": False, "error": "The 'websocket-client' package is not installed "
                                      "(pip install websocket-client)."}
    kind = detect_browser_kind(base)
    try:
        if kind == "cdp":
            page, _ = cdp_pick_page(base, iv["screen_url_hint"])
            if page is None:
                return {"ok": False, "error": "No visible browser tab found."}
            with _cdp_frames(base, page) as (frames, main):
                boxes, _routes = _collect_boxes(frames)
                nframes = len(frames)
                url = main.eval("location.href") or ""
            title = page.get("title") or ""
        elif kind == "bidi":
            with _BidiSession(base) as sess:
                ctx0, _ = bidi_pick_context(sess, iv["screen_url_hint"])
                if ctx0 is None:
                    return {"ok": False, "error": "No visible browser tab found."}
                frames = _bidi_frames(sess, ctx0["context"])
                boxes, _routes = _collect_boxes(frames)
                nframes = len(frames)
            title = ctx0.get("title") or ""
            url = ctx0.get("url") or ""
        else:
            return _no_browser_error(base)
    except Exception as e:
        return {"ok": False, "error": "Could not read the tab: " + str(e)[:160]}
    return {"ok": True, "via": kind, "title": title, "url": url,
            "boxes": boxes, "count": len(boxes), "frames": nframes}


def screen_fill_box(cfg: dict, script_dir: Path, idx: int, text: str,
                    typing: bool = False, cps: float = 22.0) -> dict:
    """Put `text` into answer box `idx`, then READ IT BACK and say whether it actually landed.

    The read-back is the point. A page can accept a programmatic fill visually and discard it (see
    _boxes_set_js), and mid-interview a silent failure is worse than no feature -- so this reports
    verified=False and the UI falls back to copy-and-paste rather than pretending.
    """
    iv = get_interview_settings(cfg, script_dir)
    base = iv["screen_cdp_url"]
    text = str(text or "")
    if not text.strip():
        return {"ok": False, "error": "Nothing to fill."}
    try:
        import websocket  # noqa: F401
    except Exception:
        return {"ok": False, "error": "The 'websocket-client' package is not installed."}
    kind = detect_browser_kind(base)
    gone = "Box %d is no longer on the page." % (idx + 1)
    try:
        if kind == "cdp":
            page, _ = cdp_pick_page(base, iv["screen_url_hint"])
            if page is None:
                return {"ok": False, "error": "No visible browser tab found."}
            with _cdp_frames(base, page) as (frames, _main):
                _boxes, routes = _collect_boxes(frames)
                if idx >= len(routes):
                    return {"ok": False, "error": gone}
                fr, local = routes[idx]
                if fr.eval(_boxes_focus_js(local)) != "ok":
                    return {"ok": False, "error": gone}
                # Input.insertText goes through the browser's real input pipeline, so editors that
                # ignore synthetic value assignment (Monaco, CodeMirror) still receive it. It must
                # be sent on the session that OWNS the frame -- for a cross-origin iframe that is
                # its own target, not the page's.
                if typing:
                    for ch, delay in _paced(text, cps):
                        fr.session.call("Input.insertText", {"text": ch})
                        time.sleep(delay)
                else:
                    fr.session.call("Input.insertText", {"text": text})
                got = fr.eval(_boxes_read_js(local)) or ""
                if got.strip() != text.strip():      # editor refused it -- try the DOM route
                    fr.eval(_boxes_set_js(local, text))
                    got = fr.eval(_boxes_read_js(local)) or ""
        elif kind == "bidi":
            with _BidiSession(base) as sess:
                ctx0, _ = bidi_pick_context(sess, iv["screen_url_hint"])
                if ctx0 is None:
                    return {"ok": False, "error": "No visible browser tab found."}
                frames = _bidi_frames(sess, ctx0["context"])
                _boxes, routes = _collect_boxes(frames)
                if idx >= len(routes):
                    return {"ok": False, "error": gone}
                fr, local = routes[idx]
                if fr.eval(_boxes_focus_js(local)) != "ok":
                    return {"ok": False, "error": gone}
                if typing:
                    # BiDi has no insertText, so grow the value: each step is a real input event,
                    # which is what React (and any editor listening for input) reacts to.
                    sofar = ""
                    for ch, delay in _paced(text, cps):
                        sofar += ch
                        fr.eval(_boxes_set_js(local, sofar))
                        time.sleep(delay)
                else:
                    fr.eval(_boxes_set_js(local, text))
                got = fr.eval(_boxes_read_js(local)) or ""
        else:
            return _no_browser_error(base)
    except Exception as e:
        return {"ok": False, "error": "Could not fill the box: " + str(e)[:160]}
    verified = got.strip() == text.strip()
    return {"ok": True, "via": kind, "idx": idx, "verified": verified,
            "chars": len(got), "expected": len(text)}


# ---- Firefox: the same Path A, over WebDriver BiDi instead of CDP ---------------------------
# Mozilla removed CDP, which is why this file used to say "Firefox cannot do this". It can -- just
# not over that protocol. WebDriver BiDi is native to Firefox and exposes script.evaluate, which is
# the ONLY primitive Path A needs. Verified live on Firefox 153: /json/list 404s (CDP really is
# gone), while BiDi returned document.innerText including all 60 lines of an 80px scroll box.
#
# This matters beyond tidiness: Chrome ran a real interview with broken audio and poor
# transcription where Firefox was smooth, so being able to read the screen from Firefox means not
# having to choose between good audio and Path A.
_BIDI_SKIP_PREFIXES = ("about:", "moz-extension://", "chrome://", "resource://")

# Interview platforms render the exercise inside an iframe, so every screen operation walks
# frames. Bounded because an ad-heavy page can carry dozens and each one costs a round trip.
MAX_SCREEN_FRAMES = 12

def _ws_base(http_base: str) -> str:
    return http_base.rstrip("/").replace("https://", "wss://").replace("http://", "ws://")


class _BidiSession:
    """One WebDriver BiDi session. Short-lived: opened per operation, closed after.

    BiDi is stateful (session.new before anything else works), so unlike the CDP helper this has to
    be a connection you hold rather than a one-shot call.
    """

    def __init__(self, http_base: str, timeout: float = 8.0):
        self.url = _ws_base(http_base) + "/session"
        self.timeout = timeout
        self._ws = None
        self._ids = itertools.count(1)

    def __enter__(self):
        import websocket  # optional dep; caller handles ImportError
        self._ws = websocket.create_connection(self.url, timeout=self.timeout, suppress_origin=True)
        r = self.call("session.new", {"capabilities": {}})
        if "result" not in r:
            raise RuntimeError("BiDi session.new refused: " + json.dumps(r)[:160])
        return self

    def __exit__(self, *exc):
        # session.end is NOT optional. Firefox allows exactly ONE active BiDi session and does not
        # release it just because the socket closed -- measured: the very next session.new failed
        # with "Maximum number of active sessions", so a single probe would have locked the feature
        # out for the rest of the interview.
        try:
            self.call("session.end", {})
        except Exception:
            pass
        try:
            self._ws.close()
        except Exception:
            pass
        return False

    def call(self, method: str, params: dict) -> dict:
        mid = next(self._ids)
        self._ws.send(json.dumps({"id": mid, "method": method, "params": params}))
        deadline = time.time() + self.timeout
        while time.time() < deadline:
            msg = json.loads(self._ws.recv())
            if msg.get("id") == mid:
                return msg
        raise TimeoutError("BiDi " + method + " timed out")

    def contexts(self) -> List[dict]:
        """Top-level browsing contexts == tabs. Children are iframes; see frames()."""
        r = self.call("browsingContext.getTree", {})
        return [c for c in r.get("result", {}).get("contexts", [])
                if not str(c.get("url", "")).startswith(_BIDI_SKIP_PREFIXES)]

    def frames(self, ctx_id: str) -> List[str]:
        """This tab's context id followed by every nested frame, depth-first.

        Load-bearing: interview platforms render the exercise INSIDE an iframe (one real platform
        uses a sandboxed one), and innerText does not cross that boundary. Only
        reading the top document is what made a real case study look like an empty page.
        """
        r = self.call("browsingContext.getTree", {"root": ctx_id})
        out: List[str] = []

        def walk(node):
            if len(out) >= MAX_SCREEN_FRAMES:
                return
            out.append(node["context"])
            for ch in node.get("children") or []:
                walk(ch)

        for c in r.get("result", {}).get("contexts", []):
            walk(c)
        return out or [ctx_id]

    def eval(self, ctx: str, expression: str):
        r = self.call("script.evaluate", {"expression": expression, "target": {"context": ctx},
                                          "awaitPromise": True, "resultOwnership": "none"})
        res = r.get("result", {})
        if res.get("type") == "exception":
            raise RuntimeError(json.dumps(res.get("exceptionDetails", res))[:200])
        return res.get("result", {}).get("value")


def detect_browser_kind(base: str, timeout: float = 3.0) -> str:
    """'cdp' (Chrome/Edge), 'bidi' (Firefox), or 'none'.

    Deliberately NOT cached. The tempting optimisation -- remember the protocol per port, since a
    running browser cannot change what it speaks -- is wrong in the one case that matters: closing
    Chrome and opening Firefox on the same port mid-session (which is exactly what happens when the
    first interview runs in one browser and the second in the other) would leave a stale 'cdp'
    pinned and every screen read failing until a restart. Measured cost of probing every time:
    41ms for CDP, 37ms for BiDi, against a ~40ms read and a multi-second answer. Not worth a bug.
    """
    kind = "none"
    try:
        _cdp_targets(base, timeout)
        kind = "cdp"
    except Exception:
        # Probe with session.status, which needs no session -- creating one just to ask what
        # protocol this is would burn Firefox's single session slot.
        try:
            import websocket
            ws = websocket.create_connection(_ws_base(base) + "/session", timeout=timeout,
                                             suppress_origin=True)
            try:
                ws.send(json.dumps({"id": 0, "method": "session.status", "params": {}}))
                deadline = time.time() + timeout
                while time.time() < deadline:
                    if json.loads(ws.recv()).get("id") == 0:
                        kind = "bidi"
                        break
            finally:
                ws.close()
        except Exception:
            kind = "none"
    return kind


def _pick_by_precedence(scored: List[dict], hints: List[str]) -> Optional[dict]:
    """Shared tab-choosing rule for both protocols (see cdp_pick_page for why this order)."""
    def _hinted(t) -> bool:
        u = str(t.get("url", "")).lower()
        return any(h in u for h in hints)

    for t in scored:
        if _hinted(t) and t["_focused"] and t["_visible"]:
            return t
    for t in scored:
        if t["_focused"] and t["_visible"]:
            return t
    for t in scored:
        if _hinted(t) and t["_visible"]:
            return t
    for t in scored:
        if t["_visible"]:
            return t
    for t in scored:
        if _hinted(t):
            return t
    return scored[0] if len(scored) == 1 else None


def _norm_hints(url_hint) -> List[str]:
    raw = url_hint if isinstance(url_hint, list) else [url_hint or ""]
    return [str(h).strip().lower() for h in raw if str(h).strip()]


def bidi_pick_context(sess: "_BidiSession", url_hint="") -> Tuple[Optional[dict], List[dict]]:
    """Firefox equivalent of cdp_pick_page, using the same precedence rule."""
    scored = []
    for c in sess.contexts():
        try:
            st = json.loads(sess.eval(c["context"], _CDP_STATE_JS) or "{}")
        except Exception:
            st = {}
        try:
            title = sess.eval(c["context"], "document.title") or ""
        except Exception:
            title = ""
        scored.append(dict(c, title=title, _visible=(st.get("v") == "visible"),
                           _focused=bool(st.get("f"))))
    return _pick_by_precedence(scored, _norm_hints(url_hint)), scored


# ---- Answer boxes: reading them, and putting an answer in the right one ----------------------
# The hands-on stage of an AI interview presents ANSWER BOXES to type into. Reading the answer off
# a phone and retyping it is the bottleneck this removes.
#
# One selector, defined once and reused by BOTH enumerate and fill, so index N means the same
# element in both calls. Filters out search boxes and chrome by size, and skips anything the page
# has disabled -- those are never the answer box.
_BOXES_FN_JS = """
  const __iaBoxes = () => {
    const sel = 'textarea, input[type=text], input:not([type]), [contenteditable=""], [contenteditable="true"]';
    // Shadow roots are the SIBLING of the iframe bug: querySelectorAll does not pierce them, so a
    // platform built from web components would hand us an answer box we cannot see. Measured on a
    // 3-box probe before this: 2 found. Walking hosts keeps document order, so the flat index is
    // still identical between enumerate and fill.
    const found = [];
    const visit = (root) => {
      Array.from(root.querySelectorAll('*')).forEach(el => {
        if (el.matches && el.matches(sel)) found.push(el);
        if (el.shadowRoot) visit(el.shadowRoot);
      });
    };
    visit(document);
    return found.filter(el => {
      const r = el.getBoundingClientRect();
      if (r.width < 40 || r.height < 12) return false;
      if (el.disabled || el.readOnly) return false;
      const st = getComputedStyle(el);
      return st.visibility !== 'hidden' && st.display !== 'none';
    });
  };
"""

# The label is the question. Prefer real labelling, then walk backwards for the nearest text --
# interview apps rarely wire up <label for>, but the question is always just above the box.
_BOXES_LIST_JS = """(() => {
""" + _BOXES_FN_JS + """
  const out = [];
  __iaBoxes().forEach((el, i) => {
    let label = '';
    if (el.labels && el.labels.length) label = el.labels[0].innerText || '';
    if (!label) label = el.getAttribute('aria-label') || '';
    if (!label && el.getAttribute('aria-labelledby')) {
      const l = document.getElementById(el.getAttribute('aria-labelledby'));
      if (l) label = l.innerText || '';
    }
    if (!label) {
      let n = el.previousElementSibling, hops = 0;
      while (n && hops++ < 4) { const t = (n.innerText || '').trim(); if (t) { label = t; break; } n = n.previousElementSibling; }
    }
    if (!label && el.parentElement) label = (el.parentElement.innerText || '').trim();
    if (!label) label = el.getAttribute('placeholder') || '';
    const cur = el.isContentEditable ? (el.innerText || '') : (el.value || '');
    const r = el.getBoundingClientRect();
    out.push({ idx: i, tag: el.tagName.toLowerCase(),
               kind: el.isContentEditable ? 'contenteditable' : 'value',
               id: el.id || '', name: el.getAttribute('name') || '',
               label: label.replace(/\\s+/g, ' ').trim().slice(0, 220),
               filled: cur.trim().length,
               top: Math.round(r.top + window.scrollY) });
  });
  return JSON.stringify({ title: document.title, url: location.href, boxes: out });
})()"""


def _boxes_focus_js(idx: int) -> str:
    """Focus box N and select whatever is already in it, so an insert REPLACES rather than appends."""
    return ("(() => {" + _BOXES_FN_JS + """
  const el = __iaBoxes()[%d];
  if (!el) return 'missing';
  el.scrollIntoView({block: 'center'});
  el.focus();
  if (el.isContentEditable) {
    const r = document.createRange(); r.selectNodeContents(el);
    const s = getSelection(); s.removeAllRanges(); s.addRange(r);
  } else if (el.select) { el.select(); }
  return 'ok';
})()""" % idx)


def _boxes_set_js(idx: int, text: str) -> str:
    """Fill without CDP Input -- the path Firefox uses.

    Assigning el.value is NOT enough and fails silently: measured against real React 18, the DOM
    node showed the text while React's state stayed empty, so the form would submit blank. Going
    through the prototype's native value setter and then dispatching a bubbling input event is what
    React's synthetic event system actually listens for. Verified: state updated on both a
    controlled textarea and a controlled input.
    """
    return ("(() => {" + _BOXES_FN_JS + """
  const el = __iaBoxes()[%s];
  if (!el) return 'missing';
  const txt = %s;
  el.scrollIntoView({block: 'center'});
  el.focus();
  if (el.isContentEditable) {
    el.innerText = txt;
    el.dispatchEvent(new InputEvent('input', {bubbles: true}));
  } else {
    const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const d = Object.getOwnPropertyDescriptor(proto, 'value');
    if (d && d.set) { d.set.call(el, txt); } else { el.value = txt; }
    el.dispatchEvent(new Event('input', {bubbles: true}));
    el.dispatchEvent(new Event('change', {bubbles: true}));
  }
  return 'ok';
})()""" % (idx, json.dumps(text)))


def _boxes_read_js(idx: int) -> str:
    return ("(() => {" + _BOXES_FN_JS + """
  const el = __iaBoxes()[%d];
  if (!el) return '';
  return el.isContentEditable ? (el.innerText || '') : (el.value || '');
})()""" % idx)


class _CdpSession:
    """A held-open CDP connection. _cdp_eval is one-shot; filling needs focus and insertText to
    land on the same connection, and Input.insertText has no expression form."""

    def __init__(self, ws_url: str, timeout: float = 8.0):
        self.ws_url, self.timeout = ws_url, timeout
        self._ws = None
        self._ids = itertools.count(1)

    def __enter__(self):
        import websocket
        self._ws = websocket.create_connection(self.ws_url, timeout=self.timeout,
                                               suppress_origin=True)
        return self

    def __exit__(self, *exc):
        try:
            self._ws.close()
        except Exception:
            pass
        return False

    def call(self, method: str, params: dict) -> dict:
        mid = next(self._ids)
        self._ws.send(json.dumps({"id": mid, "method": method, "params": params}))
        deadline = time.time() + self.timeout
        while time.time() < deadline:
            msg = json.loads(self._ws.recv())
            if msg.get("id") == mid:
                if "error" in msg:
                    raise RuntimeError(str(msg["error"])[:200])
                return msg.get("result", {})
        raise TimeoutError("CDP " + method + " timed out")

    def eval(self, expression: str, context_id: Optional[int] = None):
        params = {"expression": expression, "returnByValue": True, "awaitPromise": True}
        if context_id is not None:
            params["contextId"] = context_id
        r = self.call("Runtime.evaluate", params)
        if "exceptionDetails" in r:
            raise RuntimeError(str(r["exceptionDetails"])[:200])
        return r.get("result", {}).get("value")

    def frames(self) -> List[Optional[int]]:
        """Execution contexts for the main frame and every nested iframe.

        Same reason as the BiDi version: the exercise lives in an iframe. An isolated world per
        frame is the deterministic way to address them -- the DOM is shared, which is all we touch,
        and Input.insertText is world-agnostic so filling is unaffected.
        """
        out: List[Optional[int]] = [None]        # None == the default (main) context
        try:
            self.call("Page.enable", {})
            tree = self.call("Page.getFrameTree", {})
        except Exception:
            return out
        ids: List[str] = []

        def walk(node):
            ids.append(node["frame"]["id"])
            for ch in node.get("childFrames") or []:
                walk(ch)

        walk(tree.get("frameTree", {}))
        for fid in ids[1:MAX_SCREEN_FRAMES]:     # [0] is the main frame, already covered by None
            try:
                r = self.call("Page.createIsolatedWorld",
                              {"frameId": fid, "worldName": "ia_screen"})
                out.append(r["executionContextId"])
            except Exception:
                pass
        return out


def _no_browser_error(base: str) -> dict:
    port = base.rsplit(":", 1)[-1].strip("/") or "9223"
    return {"ok": False, "error": ("No browser is listening on " + base + ". Start Chrome/Edge with "
                                   "--remote-debugging-port=" + port + ", or Firefox with the same "
                                   "flag (Firefox is driven over WebDriver BiDi).")}


def _cdp_oopif_targets(base: str, page_id: str, timeout: float = 3.0) -> List[dict]:
    """Cross-origin iframes Chrome has site-isolated into their OWN processes.

    Measured: a page embedding a cross-origin iframe reports frames=1 through Page.getFrameTree --
    the child is simply not addressable from the parent target. It IS listed by /json/list as
    type=iframe with parentId pointing at the page, so it has to be attached to separately.
    Firefox/BiDi needs none of this: browsingContext.getTree returns cross-origin children directly.
    """
    try:
        targets = _cdp_targets(base, timeout)
    except Exception:
        return []
    by_parent: Dict[str, List[dict]] = {}
    for t in targets:
        if t.get("type") == "iframe" and t.get("webSocketDebuggerUrl"):
            by_parent.setdefault(str(t.get("parentId") or ""), []).append(t)
    out: List[dict] = []
    frontier = [str(page_id or "")]
    while frontier and len(out) < MAX_SCREEN_FRAMES:
        nxt = []
        for pid in frontier:
            for t in by_parent.get(pid, []):
                out.append(t)
                nxt.append(str(t.get("id") or ""))
        frontier = nxt
    return out


class _Frame:
    """One addressable document: how to run JS in it, and which session owns it.

    Both protocols and both process models reduce to this, so _collect_boxes and the three screen
    entry points do not need to know whether a frame is same-process, an isolated world, or a
    separately-attached out-of-process target.
    """

    __slots__ = ("eval", "session")

    def __init__(self, eval_fn, session=None):
        self.eval = eval_fn
        self.session = session


@contextlib.contextmanager
def _cdp_frames(base: str, page: dict):
    """Every document reachable from `page`: main frame, same-process iframes, and OOPIFs."""
    with contextlib.ExitStack() as stack:
        frames: List[_Frame] = []
        main = stack.enter_context(_CdpSession(page["webSocketDebuggerUrl"]))
        for ctx in main.frames():
            frames.append(_Frame(lambda js, _s=main, _c=ctx: _s.eval(js, _c), main))
        for t in _cdp_oopif_targets(base, page.get("id")):
            try:
                sub = stack.enter_context(_CdpSession(t["webSocketDebuggerUrl"]))
            except Exception:
                continue
            for ctx in sub.frames():
                frames.append(_Frame(lambda js, _s=sub, _c=ctx: _s.eval(js, _c), sub))
        yield frames[:MAX_SCREEN_FRAMES], main


def _bidi_frames(sess: "_BidiSession", ctx0: str) -> List[_Frame]:
    return [_Frame(lambda js, _f=fid: sess.eval(_f, js), sess)
            for fid in sess.frames(ctx0)]


def _collect_boxes(frames: List["_Frame"]) -> Tuple[List[dict], List[Tuple["_Frame", int]]]:
    """Run the box selector in every frame and flatten to ONE list.

    Returns (boxes, routes) where routes[i] == (frame, local_index) for boxes[i]. Enumerate and
    fill both build this the same way from the same selector, so a global index always means the
    same element in both calls -- which is what lets `idx` be a plain number in the endpoint.
    """
    boxes: List[dict] = []
    routes: List[Tuple[_Frame, int]] = []
    for fi, fr in enumerate(frames):
        try:
            data = json.loads(fr.eval(_BOXES_LIST_JS) or "{}")
        except Exception:
            continue
        for b in data.get("boxes") or []:
            routes.append((fr, int(b["idx"])))
            boxes.append(dict(b, idx=len(boxes), frame=fi))
    return boxes, routes


def _read_frames_text(frames: List["_Frame"]) -> Tuple[List[str], dict]:
    parts, head = [], {}
    for i, fr in enumerate(frames):
        try:
            d = json.loads(fr.eval(_CDP_TEXT_JS) or "{}")
        except Exception:
            continue
        if d.get("text"):
            parts.append(d["text"])
        if i == 0:
            head = d
    return parts, head


# ---- Path B: screenshot fallback -------------------------------------------------------------
# For when Path A cannot apply: Firefox (no CDP), a native app, a PDF viewer, shared video. Strictly
# a fallback -- it is viewport-limited, which is the whole reason Path A exists.
#
# Measured on a rendered KQL screenshot with known ground truth: gemini-3.1-flash-lite, 3.5-flash and
# pro-latest all transcribed it 100% CHARACTER-EXACT, and a 1568px JPEG scored identically to the
# full PNG while costing the same 1,142 image tokens -- so downscaling is free and the full-res
# upload buys nothing. What differed was DIAGNOSIS: flash-lite misread the bug, 3.5-flash and pro
# caught it. Hence SCREENSHOT_MODEL below.
SCREENSHOT_LONGEST_EDGE = 1568      # the vision tile sweet spot; larger costs bytes, not accuracy
SCREENSHOT_JPEG_QUALITY = 85
SCREENSHOT_MODEL = "gemini-3.5-flash"
MAX_SCREEN_SHOTS = 4                # a panicked key-mash must not upload twenty frames


def capture_screen_jpeg() -> Tuple[Optional[bytes], str]:
    """Grab the primary screen, downscaled and JPEG-encoded. Returns (bytes, error)."""
    try:
        from PIL import ImageGrab, Image
    except Exception:
        return None, "Pillow is not installed (pip install pillow)."
    try:
        img = ImageGrab.grab()
    except Exception as e:
        return None, f"Screen capture failed: {e}"
    try:
        longest = max(img.size)
        if longest > SCREENSHOT_LONGEST_EDGE:
            k = SCREENSHOT_LONGEST_EDGE / float(longest)
            img = img.resize((max(1, round(img.width * k)), max(1, round(img.height * k))),
                             Image.LANCZOS)
        buf = io.BytesIO()
        img.convert("RGB").save(buf, format="JPEG", quality=SCREENSHOT_JPEG_QUALITY)
        return buf.getvalue(), ""
    except Exception as e:
        return None, f"Could not encode the screenshot: {e}"


# ============================================================
# WEB OVERLAY SERVER (stdlib http.server + SSE, HTTP/1.1)
# ============================================================

def load_or_create_token(script_dir: Path, rotate: bool = False) -> str:
    """Access token that SURVIVES a server restart.

    It used to be regenerated every run, which silently unpaired the phone: its `ia_k` cookie
    still held the old token, so every reconnect -- including the watchdog's -- got a 403 and the
    only way back was rescanning the QR. Persisting it means a restart (or a crash) leaves paired
    devices working. `--rotate-token` forces a new one when you actually want to revoke access.
    """
    p = script_dir / "ia_token"
    if not rotate:
        try:
            existing = p.read_text(encoding="utf-8").strip()
            if existing:
                return existing
        except OSError:
            pass
    token = secrets.token_urlsafe(6)
    try:
        p.write_text(token, encoding="utf-8")
    except OSError:
        pass   # non-fatal: the token just won't survive this restart
    return token


def is_loopback_host(host: str) -> bool:
    return (host or "").lower() in ("127.0.0.1", "localhost", "::1", "")


def lan_ipv4s() -> List[str]:
    """This machine's LAN IPv4s, DEFAULT-ROUTE ADDRESS FIRST.

    Order matters: the QR code and the certificate hint use [0], and a box with Hyper-V/WSL/VPN
    adapters has several private IPs the phone cannot reach. The address the OS would actually
    use to leave the machine is the one the phone can reach, so it must lead.
    """
    ordered: List[str] = []

    def add(ip: str) -> None:
        if ip and not ip.startswith("127.") and ip not in ordered:
            ordered.append(ip)

    try:  # no packets are sent; this just asks the OS which interface would be used
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        add(s.getsockname()[0])
        s.close()
    except Exception:
        pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            add(info[4][0])
    except Exception:
        pass
    return ordered


def ensure_tls_cert(script_dir: Path, hosts: List[str]) -> Optional[Tuple[Path, Path, Path]]:
    """Create (once) a local CA + a server cert covering `hosts`; return (cert, key, ca_cert).

    HTTPS is what unlocks a *secure context* on the phone -- without it Android blocks PWA
    install and the Wake Lock that stops the screen sleeping mid-interview. The server cert
    carries the LAN IPs as SANs (modern browsers ignore CN), and the CA is offered at /ca.crt so
    the phone can trust it ONCE and never see a warning again.

    Returns None if the optional `cryptography` package is missing.
    """
    try:
        from cryptography import x509
        from cryptography.x509.oid import NameOID, ExtendedKeyUsageOID
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import rsa
    except ImportError:
        return None

    import datetime
    import ipaddress

    ca_cert_p = script_dir / "ia-ca.crt"
    ca_key_p = script_dir / "ia-ca.key"
    srv_cert_p = script_dir / "ia-server.crt"
    srv_key_p = script_dir / "ia-server.key"
    stamp_p = script_dir / "ia-server.hosts"
    # The version prefix forces a regenerate when the cert PROFILE changes (not just the hosts) --
    # v1 certs lacked EKU/KeyUsage/SKI/AKI and Android refused to show them as trusted.
    want = "v2|" + ",".join(sorted(set(hosts)))

    # Reuse the existing cert unless the host set changed (e.g. the laptop got a new LAN IP) --
    # regenerating every run would force a fresh trust prompt on the phone each time.
    if all(p.exists() for p in (ca_cert_p, ca_key_p, srv_cert_p, srv_key_p, stamp_p)):
        try:
            if stamp_p.read_text(encoding="utf-8").strip() == want:
                return srv_cert_p, srv_key_p, ca_cert_p
        except Exception:
            pass

    now = datetime.datetime.now(datetime.timezone.utc)
    not_before = now - datetime.timedelta(days=1)
    # 397 days: Chrome/Safari reject leaf certs valid longer than ~398 days. Local anchors are
    # mostly exempt, but staying under the limit removes a whole class of "still not trusted".
    not_after = now + datetime.timedelta(days=394)   # 395 total with the 1-day backdate

    ca_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    ca_name = x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, "Live Interview Assistant local CA")])
    ca_pub = ca_key.public_key()
    ca_cert = (x509.CertificateBuilder()
               .subject_name(ca_name).issuer_name(ca_name)
               .public_key(ca_pub)
               .serial_number(x509.random_serial_number())
               .not_valid_before(not_before).not_valid_after(not_after)
               .add_extension(x509.BasicConstraints(ca=True, path_length=0), critical=True)
               # A root without keyCertSign/cRLSign is rejected as a signer by Android.
               .add_extension(x509.KeyUsage(
                   digital_signature=False, content_commitment=False, key_encipherment=False,
                   data_encipherment=False, key_agreement=False, key_cert_sign=True,
                   crl_sign=True, encipher_only=False, decipher_only=False), critical=True)
               .add_extension(x509.SubjectKeyIdentifier.from_public_key(ca_pub), critical=False)
               .sign(ca_key, hashes.SHA256()))

    san: List[x509.GeneralName] = [x509.DNSName("localhost")]
    for h in hosts:
        try:
            san.append(x509.IPAddress(ipaddress.ip_address(h)))
        except ValueError:
            san.append(x509.DNSName(h))

    srv_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    srv_pub = srv_key.public_key()
    srv_cert = (x509.CertificateBuilder()
                .subject_name(x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, "Live Interview Assistant")]))
                .issuer_name(ca_name)
                .public_key(srv_pub)
                .serial_number(x509.random_serial_number())
                .not_valid_before(not_before).not_valid_after(not_after)
                .add_extension(x509.SubjectAlternativeName(san), critical=False)
                .add_extension(x509.BasicConstraints(ca=False, path_length=None), critical=True)
                # serverAuth EKU + KeyUsage: without these Android/Chrome will not treat the leaf
                # as a valid TLS server certificate even when the root IS installed and trusted.
                .add_extension(x509.ExtendedKeyUsage([ExtendedKeyUsageOID.SERVER_AUTH]), critical=False)
                .add_extension(x509.KeyUsage(
                    digital_signature=True, content_commitment=False, key_encipherment=True,
                    data_encipherment=False, key_agreement=False, key_cert_sign=False,
                    crl_sign=False, encipher_only=False, decipher_only=False), critical=True)
                # SKI/AKI let the client build leaf -> root reliably instead of guessing.
                .add_extension(x509.SubjectKeyIdentifier.from_public_key(srv_pub), critical=False)
                .add_extension(x509.AuthorityKeyIdentifier.from_issuer_public_key(ca_pub), critical=False)
                .sign(ca_key, hashes.SHA256()))

    enc = serialization.Encoding.PEM
    ca_cert_p.write_bytes(ca_cert.public_bytes(enc))
    ca_key_p.write_bytes(ca_key.private_bytes(
        enc, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
    srv_cert_p.write_bytes(srv_cert.public_bytes(enc) + ca_cert.public_bytes(enc))
    srv_key_p.write_bytes(srv_key.private_bytes(
        enc, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
    stamp_p.write_text(want, encoding="utf-8")
    return srv_cert_p, srv_key_p, ca_cert_p


def escape_html(s: str) -> str:
    return (str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace('"', "&quot;"))


def qr_svg(text: str, box: int = 8, quiet: int = 4) -> Optional[str]:
    """Inline SVG QR for `text`, or None if the optional `qrcode` package isn't installed.

    Built from the raw module matrix rather than qrcode's image factories, so it needs no
    pillow/lxml -- one <rect> per dark module, which any browser renders crisply at any size.
    """
    try:
        import qrcode as _qrcode
    except ImportError:
        return None
    try:
        qr = _qrcode.QRCode(border=quiet, box_size=box,
                            error_correction=_qrcode.constants.ERROR_CORRECT_M)
        qr.add_data(text)
        qr.make(fit=True)
        matrix = qr.get_matrix()
    except Exception:
        return None
    n = len(matrix)
    side = n * box
    rects = []
    for y, row in enumerate(matrix):
        x = 0
        while x < n:
            if row[x]:
                run = 1                      # merge horizontal runs -> far fewer rects
                while x + run < n and row[x + run]:
                    run += 1
                rects.append(f'<rect x="{x*box}" y="{y*box}" width="{run*box}" height="{box}"/>')
                x += run
            else:
                x += 1
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{side}" height="{side}" '
            f'viewBox="0 0 {side} {side}" shape-rendering="crispEdges" role="img" '
            f'aria-label="Pairing QR code">'
            f'<rect width="{side}" height="{side}" fill="#ffffff"/>'
            f'<g fill="#000000">{"".join(rects)}</g></svg>')


class QuietThreadingHTTPServer(ThreadingHTTPServer):
    """ThreadingHTTPServer that doesn't dump a traceback when a client just goes away.

    A phone drops idle sockets constantly -- screen sleep, Wi-Fi power-save, backgrounding the
    tab -- and each one surfaced as a multi-line ConnectionResetError traceback while the server
    sat in readline() waiting for the next keep-alive request. That is normal peer behaviour, not
    an error, and the noise buried real problems. Anything unexpected still prints.
    """

    _BENIGN = (ConnectionResetError, ConnectionAbortedError, BrokenPipeError,
               TimeoutError, ssl.SSLEOFError, ssl.SSLZeroReturnError)

    def handle_error(self, request, client_address):
        exc = sys.exc_info()[1]
        if isinstance(exc, self._BENIGN):
            return
        # A phone that closes mid-handshake shows up as a generic SSLError; still benign.
        if isinstance(exc, ssl.SSLError) and "UNEXPECTED_EOF" in str(exc).upper():
            return
        super().handle_error(request, client_address)

    # Set by serve() for --https. TLS used to wrap the LISTENING socket, which had two costs: the
    # handshake ran on the single thread that accepts every connection (a phone stalling mid-handshake
    # held up the laptop's next request), and a plain http:// visit to the https port got an empty
    # response. Now each connection's first byte is looked at in its own thread (16 Sep 2026).
    tls_context = None
    _tls_hint_shown = False

    def server_bind(self):
        # Windows lets a second server bind a port the first is still listening on when SO_REUSEADDR is
        # set, which http.server does. Measured: two copies bound 8799 together and requests would land
        # on either. Exclusive use makes the second copy fail, so serve() can say so plainly. Other
        # systems keep SO_REUSEADDR, which there only avoids a wait after a restart.
        if hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
            self.allow_reuse_address = False
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
        super().server_bind()

    def finish_request(self, request, client_address):
        try:
            request.settimeout(15)
            first = request.recv(1, socket.MSG_PEEK)
        except OSError:
            return
        if not first:
            return
        is_tls = first == b"\x16"          # every TLS connection opens with a handshake record
        if self.tls_context is not None:
            if not is_tls:
                self._redirect_to_https(request)
                return
            conn = self.tls_context.wrap_socket(request, server_side=True)   # handshake, this thread
            try:
                conn.settimeout(None)
                super().finish_request(conn, client_address)
            finally:
                try:
                    conn.close()
                except OSError:
                    pass
            return
        if is_tls:
            # https:// typed for a plain-http run. There is no certificate to answer with, so the browser
            # will show a TLS error; at least the console says which address works.
            if not QuietThreadingHTTPServer._tls_hint_shown:
                QuietThreadingHTTPServer._tls_hint_shown = True
                print(f"  ! Someone opened https:// on port {self.server_address[1]}, but this run is plain "
                      f"http. Use http://localhost:{self.server_address[1]}/ (or start with --https).",
                      flush=True)
            return
        request.settimeout(None)
        super().finish_request(request, client_address)

    def _redirect_to_https(self, sock):
        """A plain http:// request arrived on the https port: send it to the same address over https.
        307, not 301: a permanent redirect is remembered by the browser and would break http:// the next
        time the app runs without --https."""
        try:
            sock.settimeout(5)
            data = b""
            while b"\r\n\r\n" not in data and len(data) < 16384:
                chunk = sock.recv(4096)
                if not chunk:
                    break
                data += chunk
            lines = data.split(b"\r\n\r\n", 1)[0].decode("latin-1", "replace").split("\r\n")
            parts = lines[0].split(" ") if lines else []
            target = parts[1] if len(parts) >= 2 and parts[1].startswith("/") else "/"
            host = ""
            for line in lines[1:]:
                if line.lower().startswith("host:"):
                    host = line.split(":", 1)[1].strip()
            if not host or any(ch in host for ch in " /\\\r\n"):
                host = "localhost:%d" % self.server_address[1]
            location = "https://" + host + target.replace("\r", "").replace("\n", "")
            body = ('<!doctype html><title>Moved to https</title><p>This app runs on https: '
                    '<a href="%s">%s</a></p>' % (html.escape(location), html.escape(location))).encode("utf-8")
            head = ("HTTP/1.1 307 Temporary Redirect\r\nLocation: %s\r\n"
                    "Content-Type: text/html; charset=utf-8\r\nContent-Length: %d\r\n"
                    "Cache-Control: no-store\r\nConnection: close\r\n\r\n" % (location, len(body)))
            sock.sendall(head.encode("latin-1", "replace") + body)
        except OSError:
            pass


class SessionBus:
    """Server-side fan-out so EVERY connected client (laptop + phone) sees the same session.

    The app used to be single-client in two ways: `/ask` streamed only to the requester, and the
    transcript used ONE queue whose `get()` REMOVED the segment -- so with two devices connected,
    each transcript line reached only whichever one grabbed it first. The bus gives every
    subscriber its own queue and publishes each event to all of them.

    Events carry an `origin` (the client id that caused them) so the originating device can ignore
    its own echo and keep rendering from its fast local stream.
    """

    def __init__(self, maxsize: int = 2000):
        self._subs: List["queue.Queue[Tuple[str, dict]]"] = []
        self._lock = threading.Lock()
        self._maxsize = maxsize

    def subscribe(self) -> "queue.Queue[Tuple[str, dict]]":
        q: "queue.Queue[Tuple[str, dict]]" = queue.Queue(maxsize=self._maxsize)
        with self._lock:
            self._subs.append(q)
        return q

    def unsubscribe(self, q) -> None:
        with self._lock:
            if q in self._subs:
                self._subs.remove(q)

    def subscriber_count(self) -> int:
        with self._lock:
            return len(self._subs)

    def publish(self, event: str, data: dict) -> None:
        item = (event, data)
        with self._lock:
            subs = list(self._subs)
        for q in subs:
            try:
                q.put_nowait(item)
            except queue.Full:
                # A stalled client must never block the answer stream -- drop its event instead.
                pass


def make_handler(cfg: dict, script_dir: Path, access_token: Optional[str] = None,
                 port: int = 8765, scheme: str = "http",
                 config_path: Optional[Path] = None):
    # Which config.json the Setup pane writes back to. --config means it is not always the default,
    # and silently editing the wrong file would be worse than not offering the button.
    cfg_path_for_ui = config_path or default_config_path()
    interview = get_interview_settings(cfg, script_dir)
    overlay_file = script_dir / "interview_overlay.html"
    # The in-memory index lives in a mutable holder so /reindex can hot-swap it while /ask
    # retrieval reads the current value each request. All access is guarded by index_lock.
    # A MISSING index must not stop the server booting. The Settings > Your notes pane exists to
    # get a first-time user from "cloned the repo" to "has an index", and until this it could never
    # be reached: --serve refused to start for want of the very thing that pane builds. Serve with
    # an empty index instead; /ask says what to do, and the Build button fills it in.
    try:
        _boot_index = load_vector_index(script_dir)
    except Exception as e:
        print(f"  ! No usable index yet ({e.__class__.__name__}). Starting anyway -- open Settings "
              f"> Your notes to choose a folder and build one.")
        _boot_index = VectorIndex({"embed_model": "", "dim": 0, "chunks": []})
    index_holder: Dict[str, VectorIndex] = {"obj": _boot_index}
    index_lock = threading.Lock()

    def current_index() -> VectorIndex:
        with index_lock:
            return index_holder["obj"]

    def index_is_empty() -> bool:
        """No index yet. Distinguished from 'nothing matched' because the two look identical to
        retrieval but mean opposite things: an empty index would otherwise produce a confident
        "I don't have hands-on experience with that" for every question ever asked."""
        return not (getattr(current_index(), "rows", None) or [])

    # Shared across all handler instances (ThreadingHTTPServer) via closure.
    listener_holder: Dict[str, Optional[LoopbackTranscriber]] = {"obj": None}
    keepalive = ConnectionKeepalive(cfg, script_dir)
    bus = SessionBus()   # fan-out to every connected device (laptop + phone mirror)
    # Current session state, replayed to every NEW /events subscriber. Without this a device that
    # missed events while suspended (phone screen locked -> Android freezes the page) reconnects
    # into an empty view and stays behind until the next answer.
    session_state: Dict[str, object] = {"listening": False, "device": None, "answer": None,
                                        "scope_capture": False}
    # Trailing final (non-scope) segments, so a GLOBAL hotkey can answer "the question being asked"
    # without any browser involvement. Mirrors the overlay's merge window: consecutive utterances
    # within MERGE_S belong to one spoken question.
    question_parts: List[Tuple[float, str]] = []
    MERGE_S = 3.5

    def current_question() -> str:
        if not question_parts:
            return ""
        picked = [question_parts[-1]]
        for ts, txt in reversed(question_parts[:-1]):
            if picked[0][0] - ts <= MERGE_S:
                picked.insert(0, (ts, txt))
            else:
                break
        return " ".join(t for _, t in picked).strip()

    def _decorate_segment(seg: dict) -> dict:
        seg["scope"] = bool(session_state.get("scope_capture"))
        if not seg["scope"] and not seg.get("partial"):
            question_parts.append((seg.get("ts") or time.time(), seg.get("text") or ""))
            del question_parts[:-12]
        return seg

    def _capture_stopped(reason: str) -> None:
        session_state["listening"] = False
        obj = listener_holder["obj"]
        meter = obj.meter.snapshot() if obj is not None else None
        # An auto-stop is a normal, expected event, not a fault -- flag it separately from a device
        # failure so the overlay can inform rather than alarm.
        auto = "auto-stopped" in (reason or "")
        bus.publish("listening", {"on": False, "error": None if auto else reason,
                                  "notice": reason if auto else None, "meter": meter})
        print(f"  {'*' if auto else '!'} Listening stopped: {reason}")

    def _meter_tick(snap: dict) -> None:
        """Periodic while listening: make an invisible cost visible in minutes, not next month."""
        print(f"  · Listening {snap['elapsed_seconds'] / 60:.0f} min | "
              f"{snap['audio_seconds']:.0f}s audio sent | ~${snap['est_usd']:.4f}")
        bus.publish("stt_meter", snap)

    def get_listener() -> LoopbackTranscriber:
        if listener_holder["obj"] is None:
            obj = LoopbackTranscriber(cfg, script_dir, bus=bus,
                                      decorate=_decorate_segment,
                                      on_stopped=_capture_stopped)
            obj.on_meter = _meter_tick
            listener_holder["obj"] = obj
        return listener_holder["obj"]

    class Handler(BaseHTTPRequestHandler):
        # HTTP/1.1 so keep-alive + clean stream termination work; without this the overlay
        # needed a hard refresh (Ctrl+Shift+R) between answers.
        protocol_version = "HTTP/1.1"
        # SSE writes are tiny and frequent; Nagle would sit on each one waiting for a full segment,
        # adding up to ~40ms per token on the LAN mirror. TCP_NODELAY sends them immediately.
        disable_nagle_algorithm = True

        def log_message(self, *args):  # quieter console
            pass

        def _send(self, code, ctype, body: bytes):
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_json(self, obj: dict, code: int = 200):
            self._send(code, "application/json; charset=utf-8",
                       json.dumps(obj).encode("utf-8"))

        def _begin_sse(self):
            """Start an SSE response. Connection: close guarantees the client's stream
            reader receives a clean end when we return (avoids the stale-keepalive hang)."""
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Connection", "close")
            self.send_header("X-Accel-Buffering", "no")
            self.end_headers()
            self.close_connection = True  # close after this response terminates cleanly

        def _sse(self, event: str, data: dict):
            chunk = f"event: {event}\ndata: {json.dumps(data)}\n\n"
            self.wfile.write(chunk.encode("utf-8"))
            self.wfile.flush()

        def _read_body_bytes(self) -> bytes:
            length = int(self.headers.get("Content-Length", 0) or 0)
            return self.rfile.read(length) if length else b""

        # ---- LAN access gate ----
        # When bound to a non-loopback host (phone-on-Wi-Fi mirror), a random token guards the
        # app so it isn't wide open to everyone on the network. The laptop's own loopback requests
        # are always exempt, so localhost use is unchanged. A remote device authenticates by opening
        # the tokenized link once (?k=<token>), which plants a cookie carried by all later requests.
        def _authorized(self) -> bool:
            # Ongoing requests authenticate by the cookie (planted by _gate on the tokenized "/").
            # A raw ?k= query does NOT authorize arbitrary endpoints — it only plants the cookie.
            if not access_token:
                return True
            if self.client_address[0] in ("127.0.0.1", "::1"):
                return True
            cookie = self.headers.get("Cookie", "") or ""
            return any(part.strip() == "ia_k=" + access_token for part in cookie.split(";"))

        def _is_loopback(self) -> bool:
            return self.client_address[0] in ("127.0.0.1", "::1")

        def _gate(self) -> bool:
            """True if the request may proceed. Otherwise responds (cookie-planting page or 403)."""
            if self._authorized():
                return True
            parsed = urlparse(self.path)
            if parsed.path in ("/", "/index.html") and \
                    parse_qs(parsed.query).get("k", [""])[0] == access_token and overlay_file.exists():
                body = overlay_file.read_text(encoding="utf-8").encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Set-Cookie", f"ia_k={access_token}; Path=/; SameSite=Lax; Max-Age=86400")
                self.end_headers()
                self.wfile.write(body)
                return False
            self._send(403, "text/plain; charset=utf-8",
                       b"Forbidden. Open the tokenized link shown in the server console on this device.")
            return False

        # ---- GET ----
        def do_GET(self):
            if not self._gate():
                return
            path = urlparse(self.path).path   # ignore any ?query (e.g. the ?k= token on "/")
            if path in ("/", "/index.html"):
                if overlay_file.exists():
                    self._send(200, "text/html; charset=utf-8",
                               overlay_file.read_text(encoding="utf-8").encode("utf-8"))
                else:
                    self._send(500, "text/plain; charset=utf-8",
                               b"interview_overlay.html not found next to the script.")
            elif path == "/jd":
                self._send_json({"jd": load_jd(cfg, script_dir)})
            elif path == "/profiles":
                self._handle_profiles_get()
            elif path == "/settings":
                self._send_json(settings_payload(cfg, script_dir))
            elif path == "/providers":
                self._send_json({"providers": providers_public(cfg, script_dir)})
            elif path == "/vault":
                self._handle_vault_get()
            elif path == "/transcript":
                self._handle_transcript_sse()
            elif path == "/events":
                self._handle_events_sse()
            elif path == "/pair":
                self._handle_pair()
            elif path == "/manifest.webmanifest":
                self._send(200, "application/manifest+json; charset=utf-8", json.dumps({
                    "name": "Live Interview Assistant", "short_name": "Interview",
                    "start_url": "/", "scope": "/", "display": "standalone",
                    "background_color": "#0d1117", "theme_color": "#0d1117",
                    "orientation": "portrait-primary",
                    "icons": [{"src": "/icon.svg", "sizes": "any", "type": "image/svg+xml",
                               "purpose": "any maskable"}],
                }).encode("utf-8"))
            elif path == "/icon.svg":
                self._send(200, "image/svg+xml; charset=utf-8",
                           ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 192 192">'
                            '<rect width="192" height="192" rx="34" fill="#0d1117"/>'
                            '<circle cx="96" cy="74" r="26" fill="#58a6ff"/>'
                            '<rect x="86" y="96" width="20" height="34" rx="10" fill="#58a6ff"/>'
                            '<rect x="46" y="140" width="100" height="14" rx="7" fill="#3fb950"/>'
                            '</svg>').encode("utf-8"))
            elif path == "/sw.js":
                # Deliberately network-only: an interview aid must never serve a stale answer or a
                # stale app shell. The worker exists purely to satisfy PWA installability.
                self._send(200, "application/javascript; charset=utf-8",
                           (b"self.addEventListener('install', e => self.skipWaiting());\n"
                            b"self.addEventListener('activate', e => e.waitUntil(clients.claim()));\n"
                            b"self.addEventListener('fetch', e => { /* network-only */ });\n"))
            elif path == "/ca.crt":
                # Install once on the phone (Settings > Security > Install a certificate > CA)
                # to make the mirror a fully trusted secure origin: no warnings, PWA + Wake Lock.
                ca = script_dir / "ia-ca.crt"
                if ca.exists():
                    self.send_response(200)
                    self.send_header("Content-Type", "application/x-x509-ca-cert")
                    self.send_header("Content-Disposition", 'attachment; filename="ia-ca.crt"')
                    body = ca.read_bytes()
                    self.send_header("Content-Length", str(len(body)))
                    self.end_headers()
                    self.wfile.write(body)
                else:
                    self._send(404, "text/plain; charset=utf-8", b"No CA certificate (run with --https).")
            else:
                self._send(404, "text/plain; charset=utf-8", b"Not found")

        # ---- POST ----
        def do_POST(self):
            if not self._gate():
                return
            path = urlparse(self.path).path
            if path == "/ask":
                self._handle_ask()
            elif path == "/jd":
                self._handle_jd_save()
            elif path == "/settings":
                self._handle_settings_save()
            elif path == "/providers":
                self._handle_providers_post()
            elif path == "/vault":
                self._handle_vault_post()
            elif path == "/clarify":
                self._handle_clarify()
            elif path == "/reindex":
                self._handle_reindex()
            elif path == "/screen/read":
                self._handle_screen_read()
            elif path == "/screen/shot":
                self._handle_screen_shot()
            elif path == "/profiles":
                self._handle_profiles_post()
            elif path == "/resume":
                self._handle_resume_post()
            elif path == "/screen/boxes":
                self._handle_screen_boxes()
            elif path == "/screen/fill":
                self._handle_screen_fill()
            elif path == "/listen/start":
                self._handle_listen_start()
            elif path == "/listen/stop":
                self._handle_listen_stop()
            elif path == "/scope/capture":
                self._handle_scope_capture()
            elif path == "/transcribe":
                self._handle_transcribe_debug()
            else:
                self._send(404, "text/plain; charset=utf-8", b"Not found")

        # ---- /vault (first-run setup: inspect a folder, save it, report index state) ----
        def _handle_vault_get(self):
            iv = get_interview_settings(cfg, script_dir)
            info = inspect_vault(iv["vault_path"], script_dir, iv)
            ipath = index_path(script_dir)
            idx = {"exists": ipath.exists(), "name": ipath.name, "chunks": 0, "built": "",
                   "folder_match": False}
            if idx["exists"]:
                try:
                    with index_lock:
                        held = index_holder.get("obj")
                    rows = (getattr(held, "rows", []) or []) if held else []
                    idx["chunks"] = len(rows)
                    idx["built"] = time.strftime("%Y-%m-%d %H:%M",
                                                 time.localtime(ipath.stat().st_mtime))
                    # Is the loaded index built FROM the configured folder? Chunks carry their file
                    # paths, so a sample answers it without changing the index format. The notes
                    # pane shows Refresh for an indexed folder and Build only for a new one.
                    root = os.path.normcase(str(info.get("resolved") or ""))
                    sample = rows[::max(1, len(rows) // 25)][:25]

                    def _under(p) -> bool:
                        pp = Path(str(p or ""))
                        pp = pp if pp.is_absolute() else script_dir / pp
                        return os.path.normcase(str(pp)).startswith(root.rstrip("\\/") + os.sep)

                    # 90%, not a majority: a subfolder holding most of the notes must not look
                    # "already indexed". Not 100%, so one odd path cannot flip a real match.
                    idx["folder_match"] = bool(root and sample and
                                               10 * sum(_under(r.get("path")) for r in sample)
                                               >= 9 * len(sample))
                except Exception:
                    pass
            cp = checkpoint_path(script_dir)
            self._send_json({
                "vault": info,
                "index": idx,
                "interrupted_build": cp.exists(),
                # A folder dialog opens on the machine running the server, so it is meaningless
                # (worse: invisible) for the phone mirror. Offer it only to loopback.
                "can_browse": self._is_loopback(),
                "config_file": str(cfg_path_for_ui),
            })

        def _handle_vault_post(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            if not isinstance(payload, dict):
                payload = {}
            action = str(payload.get("action") or "inspect").strip().lower()
            iv = get_interview_settings(cfg, script_dir)
            if action == "browse":
                if not self._is_loopback():
                    self._send_json({"ok": False, "error":
                                     "The folder picker only works on the computer running the "
                                     "app. Type or paste the path instead."}, 200)
                    return
                picked = pick_folder_dialog()
                if not picked:
                    self._send_json({"ok": False, "error":
                                     "No folder chosen (or tkinter is unavailable -- type the "
                                     "path instead)."}, 200)
                    return
                self._send_json({"ok": True, "vault": inspect_vault(picked, script_dir, iv)})
                return
            if action == "inspect":
                self._send_json({"ok": True,
                                 "vault": inspect_vault(payload.get("path"), script_dir, iv)})
                return
            if action == "save":
                info = inspect_vault(payload.get("path"), script_dir, iv)
                if info.get("error") and not info.get("files"):
                    # Refuse to persist a path that would index nothing. Saving it would leave the
                    # app in the exact state this pane exists to prevent.
                    self._send_json({"ok": False, "error": info["error"], "vault": info}, 200)
                    return
                try:
                    save_vault_path(payload.get("path"), cfg_path_for_ui)
                except Exception as e:
                    self._send_json({"ok": False, "error": f"Could not write config: {e}"}, 200)
                    return
                # The running process holds the OLD path until it restarts; say so rather than
                # letting the next build silently use the previous vault.
                cfg.setdefault("interview", {})["vault_path"] = str(payload.get("path") or "").strip()
                self._send_json({"ok": True, "vault": inspect_vault(payload.get("path"), script_dir, iv),
                                 "note": "Saved. Build the index to use it."})
                return
            self._send_json({"ok": False, "error": "Unknown action."}, 400)

        # ---- /providers (set / clear a key, or list a provider's live models) ----
        def _handle_providers_post(self):
            """Actions: set | clear | list.

            The key never travels back out -- the response carries the same public shape as GET,
            so the UI re-renders from truth rather than from what it just typed."""
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            if not isinstance(payload, dict):
                payload = {}
            action = str(payload.get("action") or "set").strip().lower()
            pid = str(payload.get("provider") or "").strip().lower()
            if pid not in PROVIDERS:
                self._send_json({"ok": False, "error": "Unknown provider."}, 400)
                return
            if action == "list":
                try:
                    models = list_provider_models(pid, provider_settings(pid, cfg, script_dir))
                except Exception as e:
                    self._send_json({"ok": False, "error": str(e)[:400]}, 200)
                    return
                self._send_json({"ok": True, "provider": pid, "models": models})
                return
            if action == "clear":
                try:
                    set_provider_key(pid, "", False, script_dir)
                except OSError as e:
                    # A locked or read-only api_keys.json used to kill the handler thread, and the
                    # page then showed nothing at all: exactly what a broken button looks like.
                    self._send_json({"ok": False,
                                     "error": f"Could not update {KEYS_STORE_NAME}: {e}"}, 200)
                    return
            elif action == "set":
                key = str(payload.get("key") or "").strip()
                if not key:
                    self._send_json({"ok": False, "error": "No key supplied."}, 400)
                    return
                # VERIFY BEFORE STORING. An unusable key that is stored anyway only reveals itself
                # at the worst possible moment, and the store then looks authoritative -- a green
                # dot next to something that cannot work.
                spec = PROVIDERS[pid]
                probe = {"api_key": key, "label": spec.get("short") or spec["label"],
                         "base_url": str((cfg.get(pid) or {}).get("base_url")
                                         or spec.get("base_url") or "").rstrip("/"),
                         "http_referer": "http://localhost", "x_title": "Live Interview Assistant"}
                try:
                    verify_provider_key(pid, probe)
                except Exception as e:
                    self._send_json({"ok": False, "verified": False,
                                     "error": str(e)[:400]}, 200)
                    return
                set_provider_key(pid, key, bool(payload.get("persist")), script_dir)
                if pid == "gemini":
                    # A first run starts without a key, so the startup warm-up was skipped. Pay the
                    # cold handshake now rather than in front of the first question.
                    threading.Thread(target=warm_connection, args=(cfg, script_dir, True),
                                     daemon=True).start()
            else:
                self._send_json({"ok": False, "error": "Unknown action."}, 400)
                return
            # Both screens must agree about which providers are usable.
            bus.publish("providers", {"providers": providers_public(cfg, script_dir),
                                      "origin": str(payload.get("client_id") or "")})
            self._send_json({"ok": True, "verified": action == "set",
                             "providers": providers_public(cfg, script_dir)})

        # ---- /jd (save) ----
        def _handle_jd_save(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            if not isinstance(payload, dict):   # `null` and `[1,2]` are valid JSON
                payload = {}
            _jd = str(payload.get("jd", ""))
            save_jd(cfg, script_dir, _jd)
            _st = load_store(script_dir)
            _st["jd_source"] = "manual"
            save_store(script_dir, _st)
            # Mirror to every device. The JD was the ONE setting never published, so pasting it on
            # the phone left the laptop's JD tab showing the old text -- and any later save from the
            # laptop silently overwrote the new one. Settings have mirrored since v3.3; this did not.
            bus.publish("jd", {"jd": _jd, "chars": len(_jd),
                               "origin": str(payload.get("client_id") or "")})
            self._send_json({"ok": True})

        # ---- /settings (save) ----
        def _handle_settings_save(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            if not isinstance(payload, dict):
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            # Held across load-change-save, so two saves at the same moment (strip clicks, or the
            # laptop and phone together) cannot each start from the old file and drop the other.
            with UI_SETTINGS_LOCK:
                settings = load_ui_settings(script_dir)
                # answer_model: only persist a non-empty, non-deprecated string; ignore anything else.
                if "answer_model" in payload:
                    am = payload.get("answer_model")
                    if isinstance(am, str) and valid_answer_model(am):
                        settings["answer_model"] = am.strip()
                # humanize: coerce to bool if present.
                if "humanize" in payload:
                    settings["humanize"] = bool(payload.get("humanize"))
                # depth: only persist a recognized level.
                if "depth" in payload:
                    d = str(payload.get("depth", "")).lower()
                    if d in VALID_DEPTHS:
                        settings["depth"] = d
                # mode: doer/lead altitude.
                if "mode" in payload:
                    m = str(payload.get("mode", "")).lower()
                    if m in VALID_MODES:
                        settings["mode"] = m
                # role: optional discipline lens; only persist a recognised one.
                if "role" in payload:
                    r = str(payload.get("role", "")).lower()
                    if r in VALID_ROLES:
                        settings["role"] = r
                # grounding: how far the answer may travel beyond the vault (strict/assist/open).
                if "grounding" in payload:
                    g = str(payload.get("grounding", "")).lower()
                    if g in VALID_GROUNDING:
                        settings["grounding"] = g
                # Display/cue toggles — persisted so they mirror across devices.
                for _flag in UI_FLAG_DEFAULTS:
                    if _flag in payload:
                        settings[_flag] = bool(payload.get(_flag))
                # silence_hangover_ms: interviewer-pause duration; clamp to a sane range.
                if "silence_hangover_ms" in payload:
                    try:
                        v = int(payload.get("silence_hangover_ms"))
                        if 200 <= v <= 6000:
                            settings["silence_hangover_ms"] = v
                    except (TypeError, ValueError):
                        pass
                save_ui_settings(script_dir, settings)
            out = settings_payload(cfg, script_dir)
            # Mirror the change to every other device so the strips can't drift apart.
            bus.publish("settings", dict(out, origin=str(payload.get("client_id") or "")))
            self._send_json(out)

        # ---- /scope/capture : mark segments as scoping REPLIES rather than new questions ----
        def _handle_scope_capture(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            session_state["scope_capture"] = bool(payload.get("on"))
            return self._send_json({"ok": True, "on": session_state["scope_capture"]})

        # ---- /clarify (Ask follow-up: 2-3 scoping questions, not vault-grounded) ----
        def _handle_clarify(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            if not isinstance(payload, dict):   # `null` and `[1,2]` are valid JSON
                payload = {}
            question = str(payload.get("question") or "").strip()
            if not question:
                self._send_json({"questions": []})
                return
            self._send_json({"questions": generate_clarify(question, cfg, script_dir)})

        # ---- /reindex (incremental rebuild + hot-swap in-memory index) ----
        def _handle_reindex(self):
            try:
                def _pub(done: int, total: int) -> None:
                    bus.publish("index_progress", {"done": done, "total": total})
                bus.publish("index_progress", {"done": 0, "total": 0, "starting": True})
                new_index, stats = build_index(cfg, script_dir, force=False, progress=_pub)
                # Build the matrix OUTSIDE the lock (it takes ~0.6s), then swap one pointer
                # inside it: /ask can never see a matrix that disagrees with its rows.
                swapped = VectorIndex(new_index)
                with index_lock:
                    index_holder["obj"] = swapped
                bus.publish("index_progress", {"done": stats["embedded"],
                                               "total": stats["embedded"], "finished": True,
                                               "chunks": stats["chunks"]})
                self._send_json({
                    "ok": True,
                    "chunks": stats["chunks"],
                    "embedded": stats["embedded"],
                    "reused": stats["reused"],
                })
            except Exception as e:
                bus.publish("index_progress", {"error": str(e)[:200], "finished": True})
                # HTTP 200 so the UI can surface the message inline.
                self._send_json({"ok": False, "error": str(e)})

        # ---- /ask (SSE) ----
        def _handle_ask(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                self._send(400, "text/plain; charset=utf-8", b"Bad JSON")
                return
            if not isinstance(payload, dict):   # `null` and `[1,2]` are valid JSON
                payload = {}
            question = str(payload.get("question") or "").strip()
            # A SCREEN question legitimately has no spoken part -- the page carries the question
            # ("review this KQL"), and the interviewer may have said nothing quotable. Everything
            # else still requires a question, since there would be nothing to answer.
            # No notes indexed. With a CV active this is CV-ONLY mode (see cv_only_framing): the CV
            # is the evidence and retrieval is skipped. With neither, say the real cause, because
            # otherwise the answer is an honest-sounding "I don't have hands-on experience with
            # that" for literally every question. A screen question carries its own material.
            cv_only = index_is_empty()
            if cv_only and not resume_text(script_dir)[0].strip() and not (
                    payload.get("use_screen") or payload.get("screen_text")):
                self._send_json({"ok": False, "error":
                                 "No notes or CV yet. Import your CV in the Profile tab to answer "
                                 "from it, or open Settings > Your notes to choose your notes "
                                 "folder and build the index."}, 409)
                return
            if not question and not (payload.get("use_screen") or payload.get("screen_text")):
                self._send(400, "text/plain; charset=utf-8", b"Empty question")
                return
            # optional per-request JD override; otherwise use the persisted one
            jd = payload.get("jd")
            if jd is None:
                jd = load_jd(cfg, script_dir)
            # optional per-request humanize override; otherwise use the persisted UI setting
            humanize = payload.get("humanize")
            if not isinstance(humanize, bool):
                humanize = effective_humanize(cfg, script_dir)
            # optional per-request detail level; otherwise use the persisted UI setting
            depth = payload.get("depth")
            if depth not in VALID_DEPTHS:
                depth = effective_depth(cfg, script_dir)
            # optional per-request altitude mode (doer/lead); otherwise the persisted UI setting
            altitude = payload.get("mode")
            if altitude not in VALID_MODES:
                altitude = effective_mode(cfg, script_dir)
            # optional per-request "fast pro" (min thinking budget); otherwise the persisted UI setting
            # optional per-request role lens; otherwise the persisted UI setting ('general' = off)
            role = payload.get("role")
            if role not in VALID_ROLES:
                role = effective_role(cfg, script_dir)
            grounding = payload.get("grounding")
            if grounding not in VALID_GROUNDING:
                grounding = effective_grounding(cfg, script_dir)
            # Screen context (Path A): read the active browser tab over CDP. Opt-in per request, so
            # an ordinary question costs exactly what it did before -- no thread, no poll, no CDP
            # connection unless this flag is set.
            screen_text = str(payload.get("screen_text") or "")
            screen_meta = None
            screen_images: List[bytes] = []
            if payload.get("use_screen") and not screen_text:
                # Path A first: DOM text is complete (inner scrollboxes included) and exact.
                _sr = screen_read_text(cfg, script_dir)
                # Pressing +Frame is an EXPLICIT instruction to look at a picture of the screen, so
                # it must not be silently overruled by a DOM read that happened to succeed. It used
                # to be: frames were only consumed when Path A FAILED, so every buffered frame was
                # captured, stored and then ignored -- "+Frame does nothing" with no way to tell.
                # Now an explicit frame is carried ALONGSIDE the DOM text (which is still the more
                # complete source, so it stays), and the badge reports both.
                _pinned = list(session_state.get("shots") or [])
                if _sr.get("ok"):
                    screen_text = _sr["text"]
                    screen_meta = {"via": "dom", "title": _sr.get("title"), "url": _sr.get("url"),
                                   "chars": _sr.get("chars"), "truncated": _sr.get("truncated"),
                                   "frames_read": _sr.get("frames")}
                    if _pinned:
                        screen_images = _pinned[-MAX_SCREEN_SHOTS:]
                        screen_meta["via"] = "dom+shot"
                        screen_meta["frames"] = len(screen_images)
                        session_state["shots"] = []      # consumed
                else:
                    # Path B: Firefox, a native app, a PDF viewer -- anything CDP cannot reach.
                    # Viewport-limited by nature, which is why it is the fallback and why the meta
                    # records which path was used.
                    _buffered = list(session_state.get("shots") or [])
                    _shot, _err = capture_screen_jpeg()
                    if _shot:
                        _buffered.append(_shot)
                    if not _buffered:
                        self._begin_sse()
                        self._sse("error", {"message": "Screen read failed: "
                                                       + _sr.get("error", "") + " | " + _err})
                        return
                    screen_images = _buffered[-MAX_SCREEN_SHOTS:]
                    screen_meta = {"via": "screenshot", "frames": len(screen_images),
                                   "reason": _sr.get("error", "")}
                    session_state["shots"] = []          # consumed
            elif payload.get("use_screen") and screen_text:
                screen_meta = {"via": "supplied", "chars": len(screen_text)}
            # Explicit "walk me through / what commands" requests let CONCISE break into
            # structured, command-level detail for this one answer.
            detail_requested = wants_detail(question)
            prof = depth_profile(depth, detail_requested)
            # Local, ~0ms response-class label (advisory; drives the opener strip, later the
            # doctrine). Computed on the ORIGINAL question, like wants_detail.
            qclass = classify_question(question)
            # optional conversation history for follow-up awareness (list of {q, a})
            history = payload.get("history")
            if not isinstance(history, list):
                history = []
            history = [t for t in history if isinstance(t, dict)][-6:]
            # Which device asked. Mirrored events carry it so the ORIGINATOR ignores its own echo
            # and keeps rendering from its own (faster) direct stream.
            origin = str(payload.get("client_id") or "")
            # `quiet` keeps an answer OFF the shared bus. Filling four answer boxes fires four
            # /ask calls in a row; without this each one would overwrite the main answer on the
            # phone, so the mirror would end up showing box 4 while you are still reading box 1.
            quiet = bool(payload.get("quiet"))

            def _pub(evt, data):
                if not quiet:
                    bus.publish(evt, data)

            self._begin_sse()
            _pub("question", {"question": question, "origin": origin})
            timer = StageTimer()
            try:
                # One Flash call decides follow-up vs new topic AND (for a follow-up) rewrites the
                # question into a standalone retrieval query. On a NEW TOPIC we drop the prior turns
                # entirely so stale context can't colour retrieval or the answer -- the automatic
                # equivalent of pressing "New topic".
                # With a screen question the spoken part may be empty, so retrieval would embed "".
                # Use the screen text as the retrieval query instead -- that is also what makes the
                # candidate's own notes (KQL, QRadar, troubleshooting) come back for a screen answer.
                # With screenshots there is no text to retrieve on, so the spoken question (if any)
                # is all we have; retrieval simply returns less, which is correct.
                _retrieval_q = question or screen_text[:400] or "code review screenshot"
                search_query, is_followup = condense_query(_retrieval_q, history, cfg, script_dir)
                timer.mark("condense" if history else "condense_skipped")
                if not is_followup:
                    history = []
                rewritten = search_query if (is_followup and search_query.strip().lower()
                                             != question.strip().lower()) else ""
                if cv_only:
                    hits = []                 # nothing to search, so no embedding call either
                else:
                    vindex = current_index()
                    qvec = embed_query(search_query, vindex.embed_model or interview["embed_model"],
                                       get_gemini_settings(cfg)["api_key"], interview["embed_dim"])
                    timer.mark("embed")
                    hits = rank_hits(qvec, vindex, prof["top_k"])
                    timer.mark("rank")
                top_score = hits[0][0] if hits else 0.0
                mode = classify_mode(top_score, interview["min_score"],
                                     interview["adjacent_margin"])
                _prof = active_profile(script_dir)
                _resume_txt, _resume_name = resume_text(script_dir)
                _position = str(_prof.get('position') or '')
                # Provenance gate (see answer_once): cap framing at the top hit's tier.
                ceiling = (experience_ceiling(hits, interview["tier_ceiling_margin"], search_query)
                           if interview.get("vault_tiers") and not cv_only else None)
                base_framing = resolve_framing(mode, ceiling)
                framing = apply_grounding(base_framing, grounding)
                if cv_only and _resume_txt.strip():
                    framing = cv_only_framing(question, grounding)
                # Screen content overrides every framing: the question is about what is on screen,
                # and no grounding mode makes vault recall the right frame for it.
                # An identity question is answered from the CV, not from vault retrieval --
                # that mismatch is what produced an introduction assembled out of technical notes.
                if _resume_txt.strip() and asks_about_background(question):
                    framing = "profile"
                if screen_text or screen_images:
                    framing = "screen"
                grounded = framing == "grounded"
                # See answer_once: sub-threshold chunks must not be fed to 'open' as preferred
                # context, or the answer anchors on irrelevant notes.
                ctx_hits = [] if base_framing == "ungrounded" else hits
                show_sources = framing != "ungrounded" and not (framing == "open" and not ctx_hits)
                experience_probe = asks_about_experience(question)
                # The badge follows what the evidence supports for the subject asked about; the
                # prompt below still uses `framing`, unchanged. See badge_for.
                badge_mode, badge_tier = badge_for(framing, ceiling, experience_probe, hits,
                                                   search_query, _resume_txt,
                                                   notes_used=bool(ctx_hits))
                meta_payload = {
                    "grounded": badge_mode == "grounded",
                    "mode": badge_mode,
                    "framing": framing,
                    "grounding": grounding,
                    "cv_only": cv_only,
                    "ceiling_tier": badge_tier,
                    "top_score": round(float(top_score), 3),
                    "sources": sources_of(hits) if show_sources else [],
                    "rewritten": rewritten,
                    "followup": bool(is_followup),
                    "qclass": qclass,
                    "screen": screen_meta,
                }
                self._sse("meta", meta_payload)
                _pub("answer_meta", dict(meta_payload, origin=origin, question=question))
                messages = build_answer_messages(question, ctx_hits, framing, jd,
                                                  humanize=humanize, depth=depth, history=history,
                                                  detail_requested=detail_requested,
                                                  qclass=qclass, altitude=altitude, role=role,
                                                  experience_probe=experience_probe,
                                                  screen_text=screen_text,
                                                  resume=_resume_txt, position=_position,
                                                  resolved_question=rewritten)
                temperature = temperature_for_mode(framing)
                first = True
                collected: List[str] = []
                # Publish the in-progress answer into the session state so a device that reconnects
                # mid-stream replays what it missed instead of showing a headless token trickle.
                session_state["answer"] = {"question": question, "meta": meta_payload,
                                           "parts": collected, "done": False}
                for piece in generate_answer_stream(messages, cfg, script_dir,
                                                    temperature=temperature,
                                                    images=screen_images or None,
                                                    max_tokens=prof["max_tokens"],
                                                    depth=depth):
                    if first:
                        timer.mark("first_token")
                        first = False
                    self._sse("token", {"t": piece})
                    collected.append(piece)
                    _pub("answer_token", {"t": piece, "origin": origin})
                timer.mark("stream")
                timer.report("ask")
                self._sse("done", {})
                cur = session_state.get("answer")
                if isinstance(cur, dict) and cur.get("parts") is collected:
                    cur["done"] = True
                # Carries the finished answer so mirrors can store history/follow-up context
                # identically to the device that asked.
                _pub("answer_done", {"origin": origin, "question": question,
                                            "answer": "".join(collected), "meta": meta_payload})
            except Exception as e:
                try:
                    self._sse("error", {"message": str(e)})
                except Exception:
                    pass
                _pub("answer_error", {"origin": origin, "message": str(e)})

        # ---- /screen/read : what would we read, and from which tab? ----
        def _handle_screen_read(self):
            if not get_interview_settings(cfg, script_dir)["screen_enabled"]:
                self._send_json({"ok": False, "error": "Screen reading is disabled in config."})
                return
            r = screen_read_text(cfg, script_dir)
            if r.get("ok"):
                # Preview only -- the full text goes to /ask, not over this endpoint's response.
                r = dict(r, preview=r["text"][:400])
                r.pop("text", None)
            self._send_json(r)

        # ---- /profiles : positions, their JD, and which CV to use ----
        def _profile_payload(self) -> dict:
            d = store_public(script_dir)
            _txt, _name = resume_text(script_dir)
            d["active_resume_name"] = _name
            d["active_resume_chars"] = len(_txt)
            d["active_jd_chars"] = len(load_jd(cfg, script_dir))
            return d

        def _handle_profiles_get(self):
            self._send_json(self._profile_payload())

        def _publish_profile(self, origin=""):
            # Same lesson as the JD: a setting that is not published to the bus silently diverges
            # between the laptop and the phone, and the next save from either one overwrites it.
            d = self._profile_payload()
            d["origin"] = origin
            bus.publish("profiles", d)

        def _handle_profiles_post(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            action = str(payload.get("action") or "save")
            store = load_store(script_dir)
            origin = str(payload.get("client_id") or "")
            if action == "save":
                pid = str(payload.get("id") or "") or _new_id("p_")
                rec = {"id": pid,
                       "name": str(payload.get("name") or "Untitled").strip()[:80],
                       "position": str(payload.get("position") or "").strip()[:120],
                       "company": str(payload.get("company") or "").strip()[:120],
                       "jd": str(payload.get("jd") or ""),
                       "resume_id": str(payload.get("resume_id") or "")}
                out = [p for p in store["profiles"] if p.get("id") != pid]
                out.append(rec)
                store["profiles"] = out
            elif action == "delete":
                pid = str(payload.get("id") or "")
                store["profiles"] = [p for p in store["profiles"] if p.get("id") != pid]
                if store.get("active_profile") == pid:
                    store["active_profile"] = ""
            elif action == "get":
                pid = str(payload.get("id") or "")
                for pr in store["profiles"]:
                    if pr.get("id") == pid:
                        self._send_json({"ok": True, "id": pid, "jd": pr.get("jd") or ""})
                        return
                self._send_json({"ok": False, "error": "No such position."})
                return
            elif action == "activate":
                pid = str(payload.get("id") or "")
                store["active_profile"] = pid
                for p in store["profiles"]:
                    if p.get("id") == pid:
                        # Activating a profile applies its JD and its CV -- that is the whole point
                        # of a profile, and it is what stops a stale JD from a previous interview
                        # steering this one.
                        save_jd(cfg, script_dir, p.get("jd") or "")
                        store["jd_source"] = pid
                        if p.get("resume_id"):
                            store["active_resume"] = p["resume_id"]
                        break
                else:
                    save_jd(cfg, script_dir, "")
                    store["jd_source"] = ""
            else:
                self._send_json({"ok": False, "error": "Unknown action."})
                return
            save_store(script_dir, store)
            self._publish_profile(origin)
            d = self._profile_payload()
            d["ok"] = True
            d["jd"] = load_jd(cfg, script_dir)
            self._send_json(d)

        # ---- /resume : import (PDF/Word/markdown), review, save, activate ----
        def _handle_resume_post(self):
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            action = str(payload.get("action") or "")
            store = load_store(script_dir)
            origin = str(payload.get("client_id") or "")

            if action == "import":
                # Convert ONLY -- nothing is saved or activated here. The extracted text goes back
                # to the UI for review first, because a two-column PDF comes out interleaved and
                # silently activating that would poison every answer.
                try:
                    blob = base64.b64decode(payload.get("data") or "")
                except Exception:
                    self._send_json({"ok": False, "error": "Could not decode that upload."})
                    return
                if len(blob) > 8 * 1024 * 1024:
                    self._send_json({"ok": False, "error": "That file is over 8MB — is it a CV?"})
                    return
                name = str(payload.get("filename") or "resume")
                text, warn = resume_to_markdown(name, blob, cfg, script_dir)
                if not text.strip():
                    self._send_json({"ok": False, "error": warn or "No text could be extracted."})
                    return
                self._send_json({"ok": True, "markdown": text[:MAX_RESUME_CHARS],
                                 "chars": len(text), "warning": warn,
                                 "suggested_name": Path(name).stem[:80]})
                return

            if action == "reformat":
                src = str(payload.get("markdown") or "")
                if not src.strip():
                    self._send_json({"ok": False, "error": "Nothing to reformat."})
                    return
                try:
                    settings = get_gemini_settings(cfg)
                except Exception as e:
                    self._send_json({"ok": False, "error": str(e)[:140]})
                    return
                instr = (
                    "Reformat the CV below into clean GitHub-flavoured Markdown: headings for each "
                    "section, bullet lists for bullet points, and the dates kept beside their role. "
                    "This is a FORMATTING pass only -- do not add, remove, summarise, reword or "
                    "reorder any content, and do not invent anything. Every fact, number, employer, "
                    "date and certification in the input must appear in the output. Output only the "
                    "markdown." + chr(10) * 2 + "---" + chr(10) + src)
                body = {"contents": [{"role": "user", "parts": [{"text": instr}]}],
                        "generationConfig": {"temperature": 0}}
                th, out_tok = _thinking_and_output(SCREENSHOT_MODEL, 12000, 512)
                body["generationConfig"]["maxOutputTokens"] = out_tok
                if th is not None:
                    body["generationConfig"]["thinkingConfig"] = th
                try:
                    rr = shared_session().post(
                        "https://generativelanguage.googleapis.com/v1beta/models/"
                        + SCREENSHOT_MODEL + ":generateContent",
                        headers={"x-goog-api-key": settings["api_key"],
                                 "Content-Type": "application/json"},
                        json=body, timeout=300)
                    if rr.status_code != 200:
                        self._send_json({"ok": False,
                                         "error": "Reformat failed (HTTP %d)." % rr.status_code})
                        return
                    dd = rr.json()
                except Exception as e:
                    self._send_json({"ok": False, "error": "Reformat failed: " + str(e)[:120]})
                    return
                out = "".join(pt.get("text", "") for c in dd.get("candidates", [])
                              for pt in c.get("content", {}).get("parts", []))
                out = _strip_code_fence(out)
                if not out.strip():
                    self._send_json({"ok": False, "error": "The model returned nothing."})
                    return
                self._send_json({"ok": True, "markdown": out[:MAX_RESUME_CHARS],
                                 "chars": len(out)})
                return

            if action == "save":
                rid = str(payload.get("id") or "") or _new_id("r_")
                text = str(payload.get("markdown") or "")[:MAX_RESUME_CHARS]
                if not text.strip():
                    self._send_json({"ok": False, "error": "Nothing to save."})
                    return
                (_resume_dir(script_dir) / f"{rid}.md").write_text(text, encoding="utf-8")
                rec = {"id": rid, "name": str(payload.get("name") or "Resume").strip()[:80],
                       "chars": len(text), "source": str(payload.get("source") or ""),
                       "added": time.strftime("%Y-%m-%d %H:%M")}
                out = [r for r in store["resumes"] if r.get("id") != rid]
                out.append(rec)
                store["resumes"] = out
                # First CV in becomes the default, so there is always something to fall back on.
                if not store.get("active_resume"):
                    store["active_resume"] = rid
                if payload.get("activate"):
                    store["active_resume"] = rid
            elif action == "activate":
                store["active_resume"] = str(payload.get("id") or "")
            elif action == "delete":
                rid = str(payload.get("id") or "")
                store["resumes"] = [r for r in store["resumes"] if r.get("id") != rid]
                try:
                    (_resume_dir(script_dir) / f"{rid}.md").unlink()
                except Exception:
                    pass
                if store.get("active_resume") == rid:
                    store["active_resume"] = (store["resumes"][0]["id"] if store["resumes"] else "")
            elif action == "get":
                rid = str(payload.get("id") or "")
                txt, nm = resume_text(script_dir, rid)
                self._send_json({"ok": True, "id": rid, "name": nm, "markdown": txt})
                return
            else:
                self._send_json({"ok": False, "error": "Unknown action."})
                return

            save_store(script_dir, store)
            self._publish_profile(origin)
            d = self._profile_payload()
            d["ok"] = True
            self._send_json(d)

        # ---- /screen/boxes : which answer boxes are on the page, and what is each one asking? ----
        def _handle_screen_boxes(self):
            if not get_interview_settings(cfg, script_dir)["screen_enabled"]:
                self._send_json({"ok": False, "error": "Screen reading is disabled in config."})
                return
            self._send_json(screen_list_boxes(cfg, script_dir))

        # ---- /screen/fill : put an answer into one box, and verify it actually landed ----
        def _handle_screen_fill(self):
            if not get_interview_settings(cfg, script_dir)["screen_enabled"]:
                self._send_json({"ok": False, "error": "Screen reading is disabled in config."})
                return
            try:
                payload = json.loads(self._read_body_bytes() or b"{}")
            except Exception:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            try:
                idx = int(payload.get("idx", -1))
            except Exception:
                idx = -1
            if idx < 0:
                self._send_json({"ok": False, "error": "Which box? (idx missing)"})
                return
            self._send_json(screen_fill_box(cfg, script_dir, idx, payload.get("text", ""),
                                            typing=bool(payload.get("typing")),
                                            cps=float(payload.get("cps") or 22)))

        # ---- /screen/shot : buffer one frame (a long case study needs several) ----
        def _handle_screen_shot(self):
            blob, err = capture_screen_jpeg()
            if not blob:
                self._send_json({"ok": False, "error": err})
                return
            shots = list(session_state.get("shots") or [])
            shots.append(blob)
            # Bounded: keep the most recent frames so a key-mash cannot queue a huge upload.
            session_state["shots"] = shots[-MAX_SCREEN_SHOTS:]
            n = len(session_state["shots"])
            bus.publish("shots", {"frames": n})
            self._send_json({"ok": True, "frames": n, "kb": len(blob) // 1024,
                             "max": MAX_SCREEN_SHOTS})

        # ---- /listen/start ----
        def _handle_listen_start(self):
            listener = get_listener()
            try:
                ok, info = listener.start()
            except Exception as e:  # defensive: never crash the server
                self._send_json({"ok": False, "error": str(e)})
                return
            if ok:
                # Hold the Gemini connection open between questions: an interviewer can easily
                # talk for two minutes, which is long enough for the pool to drop the socket and
                # make the next question pay a cold handshake.
                keepalive.start()
                # Tell every device (so the phone's toggle reflects a laptop start, and vice versa).
                session_state["listening"] = True
                session_state["device"] = info
                limits = {"idle_stop_minutes": listener.idle_stop_s / 60.0,
                          "max_session_minutes": listener.max_session_s / 60.0}
                bus.publish("listening", {"on": True, "device": info,
                                          "meter": listener.meter.snapshot(), "limits": limits})
                self._send_json({"ok": True, "device": info, "limits": limits})
            else:
                self._send_json({"ok": False, "error": info})

        # ---- /listen/stop ----
        def _handle_listen_stop(self):
            listener = get_listener()
            try:
                listener.stop()
            except Exception:
                pass
            keepalive.stop()
            session_state["listening"] = False
            meter = listener.meter.snapshot()
            if meter["calls"]:
                print(f"  · Listening session ended: {listener.meter.summary()}")
            bus.publish("listening", {"on": False, "meter": meter})
            self._send_json({"ok": True, "meter": meter})

        # ---- /transcript (SSE) ----
        def _session_snapshot(self) -> dict:
            _lo = listener_holder["obj"]
            snap = {"listening": bool(session_state.get("listening")),
                    "device": session_state.get("device"),
                    # Without this a device that reconnects mid-session shows no cost until the
                    # next 5-minute tick -- i.e. exactly when you'd want to see it.
                    "stt_meter": _lo.meter.snapshot() if _lo is not None else None,
                    "settings": settings_payload(cfg, script_dir)}
            a = session_state.get("answer")
            if isinstance(a, dict):
                # `parts` is the live list the /ask loop appends to, so a mid-answer reconnect
                # picks up everything streamed so far and then continues from the bus.
                snap["answer"] = {"question": a.get("question"), "meta": a.get("meta"),
                                  "text": "".join(a.get("parts") or []), "done": bool(a.get("done"))}
            return snap

        def _stream_bus(self, wanted: Optional[set] = None, with_snapshot: bool = False):
            """Hold an SSE connection open and forward bus events (optionally filtered).

            The overlay opens these once on page load -- BEFORE listening starts -- and keeps them
            for the page's lifetime, so we must NOT self-end when idle (that made EventSource
            reconnect every ~3s all session). The periodic keep-alive write surfaces a dead client.
            """
            sub = bus.subscribe()
            self._begin_sse()
            # A real `ping` EVENT, not an SSE comment: comments keep the socket warm but are never
            # delivered to JavaScript, so the client had no way to tell a live stream from one that
            # died while the phone slept. The client uses these to detect staleness and reconnect.
            self._sse("ping", {"t": time.time()})
            if with_snapshot:
                self._sse("snapshot", self._session_snapshot())
            last_keepalive = time.time()
            try:
                while True:
                    try:
                        event, data = sub.get(timeout=0.5)
                        if wanted is None or event in wanted:
                            self._sse(event, data)
                    except queue.Empty:
                        pass
                    now = time.time()
                    if now - last_keepalive >= 15:
                        self._sse("ping", {"t": now})
                        last_keepalive = now
            except Exception:
                # client disconnected or write failed; just end
                pass
            finally:
                bus.unsubscribe(sub)

        def _handle_transcript_sse(self):
            # Transcript-only view of the bus (kept as its own endpoint so the existing overlay
            # transcript code is unchanged). Ensure the capture object exists so /listen/start
            # from ANY device drives the same listener.
            get_listener()
            self._stream_bus({"segment"})

        # ---- /pair : scan-to-open QR for the phone mirror ----
        def _handle_pair(self):
            suffix = f"/?k={access_token}" if access_token else "/"
            urls = [f"{scheme}://{ip}:{port}{suffix}" for ip in (lan_ipv4s() or [])]
            primary = urls[0] if urls else f"{scheme}://<this-PC-LAN-IP>:{port}{suffix}"
            svg = qr_svg(primary)
            if svg is None:
                qr_block = ('<p class="warn">Install the optional QR package for a scannable code:'
                            '<br><code>pip install qrcode</code></p>')
            else:
                qr_block = f'<div class="qr">{svg}</div>'
            alts = "".join(f'<li><a href="{u}">{escape_html(u)}</a></li>' for u in urls[1:])
            alt_block = (f'<p class="muted">Other network interfaces (try these if the first '
                         f'does not load):</p><ul>{alts}</ul>') if alts else ""
            # Trust instructions: the padlock needs the CA installed on EACH device separately.
            if scheme == "https":
                trust_block = f"""
<div class="trust">
 <h2>Getting the green padlock</h2>
 <p class="muted">The CA must be installed on <b>each device separately</b> &mdash; installing it on
 the phone does nothing for the laptop, and vice versa.</p>
 <p><b>This laptop (Windows)</b> &mdash; run once in PowerShell, then fully restart the browser:</p>
 <p><code>certutil -addstore -user Root "{escape_html(str(script_dir / 'ia-ca.crt'))}"</code></p>
 <p><b>Android</b> &mdash; download <a href="/ca.crt">ia-ca.crt</a>, then Settings &rarr; Security
 &rarr; Encryption &amp; credentials &rarr; <b>Install a certificate</b> &rarr;
 <b>CA certificate</b> &rarr; Install anyway. Picking &ldquo;VPN &amp; app user certificate&rdquo;
 by mistake will <i>not</i> work. Then fully close and reopen Chrome.</p>
 <p class="muted">Android will warn that the network &ldquo;may be monitored&rdquo; &mdash; that is
 the expected notice for any user-installed CA, and it refers to this certificate only.</p>
 <p class="muted">Note: <code>http://localhost</code> on the laptop is already a secure context, so
 the laptop only needs this if you want the padlock itself.</p>
</div>"""
            else:
                trust_block = ('<p class="muted">Running over plain HTTP &mdash; restart with '
                               '<code>--https</code> for an installable app and a screen that '
                               'stays awake.</p>')
            html = f"""<!doctype html><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pair your phone</title>
<style>
 body{{margin:0;padding:28px;background:#0d1117;color:#e6edf3;
      font-family:-apple-system,"Segoe UI",Roboto,sans-serif;text-align:center}}
 h1{{font-size:19px;margin:0 0 4px}} p{{font-size:13.5px;line-height:1.6}}
 .muted{{color:#8b949e}} .warn{{color:#d29922}}
 .qr{{display:inline-block;background:#fff;padding:14px;border-radius:12px;margin:18px 0}}
 .qr svg{{display:block;width:min(74vw,300px);height:auto}}
 code{{background:#161b22;border:1px solid #30363d;border-radius:6px;padding:2px 6px;
       font-size:12.5px;word-break:break-all}}
 a{{color:#58a6ff}} ul{{list-style:none;padding:0;font-size:12.5px}} li{{margin:4px 0}}
 .trust{{max-width:640px;margin:26px auto 0;text-align:left;border-top:1px solid #30363d;
        padding-top:18px}}
 .trust h2{{font-size:15px;margin:0 0 8px}}
</style>
<h1>Scan to open on your phone</h1>
<p class="muted">Same Wi-Fi as this PC. The link carries the access token.</p>
{qr_block}
<p><code>{escape_html(primary)}</code></p>
{alt_block}
<p class="muted">Token changes each time the server restarts &mdash; rescan after a restart,
or pin it with <code>--token</code>.</p>
{trust_block}"""
            self._send(200, "text/html; charset=utf-8", html.encode("utf-8"))

        # ---- /events (SSE): the shared-session mirror stream ----
        def _handle_events_sse(self):
            # Everything EXCEPT transcript segments: answers, settings changes, listening state.
            # This is what makes the laptop and the phone show the same session.
            self._stream_bus({"answer_meta", "answer_token", "answer_done", "answer_error",
                              "question", "settings", "listening", "stt_meter", "jd", "profiles",
                              "providers", "index_progress"},
                             with_snapshot=True)

        # ---- /transcribe (DEBUG: raw audio/wav body -> transcript) ----
        def _handle_transcribe_debug(self):
            body = self._read_body_bytes()
            if not body:
                self._send(400, "text/plain; charset=utf-8", b"Empty audio body")
                return
            # Cheap shape check before spending an API call. This endpoint takes raw audio/wav, so
            # anything else is a client mistake (400), not a server failure (500) -- and posting
            # JSON here used to bill a transcription request for a guaranteed failure.
            if not (body[:4] == b"RIFF" and body[8:12] == b"WAVE"):
                self._send(400, "text/plain; charset=utf-8",
                           b"Body must be raw audio/wav (RIFF/WAVE header not found).")
                return
            try:
                text = gemini_transcribe_wav(body, cfg, script_dir)
                self._send_json({"text": text})
            except Exception as e:
                self._send_json({"error": str(e)}, code=500)

    # Exposed so serve() can wire a GLOBAL hotkey to the same session state without the browser.
    Handler.ia_current_question = staticmethod(current_question)
    Handler.ia_session_state = session_state
    return Handler


def start_global_hotkey(handler, port: int, scheme: str, combo: str = "<ctrl>+<alt>+a",
                        screen_combo: str = "<ctrl>+<alt>+s",
                        frame_combo: str = "<ctrl>+<alt>+d"):
    """OS-level hotkey that answers the question currently being asked.

    A web page only receives keys while it has focus, so Ctrl+Enter in the overlay cannot help when
    the browser is minimised or the meeting app is in front. This listens at the OS level and, on
    press, POSTs the current transcript question to our OWN /ask over loopback (which the token gate
    exempts). The answer then fans out over the existing bus to every device -- laptop AND phone --
    so no part of the answer pipeline needs restructuring.

    Optional: needs `pynput`. Without it the app is unchanged, just without the global hotkey.
    """
    try:
        from pynput import keyboard
    except Exception:
        return None

    def _fire(use_screen: bool = False):
        try:
            question = handler.ia_current_question()
        except Exception:
            question = ""
        # A screen question often has no usable spoken part ("take a look at this") -- the page IS
        # the question -- so the screen hotkey may fire with an empty transcript. The plain answer
        # hotkey still requires one, since without a question it has nothing to answer.
        if not question and not use_screen:
            return
        payload = {"question": question, "client_id": "global-hotkey"}
        if use_screen:
            payload["use_screen"] = True
        # Carry the last completed turn so a server-initiated answer can still resolve a follow-up.
        prev = handler.ia_session_state.get("answer")
        if isinstance(prev, dict) and prev.get("done") and prev.get("question"):
            payload["history"] = [{"q": prev["question"],
                                   "a": "".join(prev.get("parts") or [])}]
        try:
            with requests.post(f"{scheme}://127.0.0.1:{port}/ask", json=payload, stream=True,
                               timeout=180, verify=False) as resp:
                for _ in resp.iter_content(chunk_size=8192):
                    pass    # drain: every connected device renders it from the bus
        except Exception:
            pass

    def _shot():
        try:
            requests.post(f"{scheme}://127.0.0.1:{port}/screen/shot", timeout=20, verify=False)
        except Exception:
            pass

    try:
        listener = keyboard.GlobalHotKeys({
            combo: lambda: threading.Thread(target=_fire, daemon=True).start(),
            # Ctrl+Alt+S: read the active browser tab and answer from it. Same OS-level path as the
            # answer hotkey, because the whole point is that it works while the overlay is hidden
            # behind a shared screen.
            screen_combo: lambda: threading.Thread(target=_fire, args=(True,), daemon=True).start(),
            # Ctrl+Alt+D: buffer one more screenshot frame WITHOUT answering. Only matters on the
            # screenshot fallback, where a long case study needs scroll-and-capture; the DOM path
            # gets the whole page in one go and never needs this.
            frame_combo: lambda: threading.Thread(target=_shot, daemon=True).start(),
        })
        listener.daemon = True
        listener.start()
        return listener
    except Exception:
        return None


def _port_is_free(host: str, port: int) -> bool:
    s_ = socket.socket(socket.AF_INET6 if ":" in host else socket.AF_INET, socket.SOCK_STREAM)
    try:
        if hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
            s_.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
        s_.bind((host, port))
        return True
    except OSError:
        return False
    finally:
        s_.close()


def _app_already_on(port: int) -> str:
    """The address of a Live Interview Assistant already answering on this port, or ""."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for scheme in ("https", "http"):
            try:
                r = requests.get(f"{scheme}://127.0.0.1:{port}/settings", timeout=2, verify=False)
                if r.ok and "answer_model" in r.json():
                    return f"{scheme}://localhost:{port}"
            except Exception:
                pass
    return ""


def choose_port(host: str, port: int) -> int:
    """The configured port if it is free. If this app already owns it, stop and say where it is. If some
    other program owns it, move to the next free port and say so, rather than failing with a traceback."""
    if _port_is_free(host, port):
        return port
    running = _app_already_on(port)
    if running:
        raise SetupError(f"Live Interview Assistant is already running at {running} . Open that, or stop "
                         f"it first (Ctrl+C in its window).")
    for alt in range(port + 1, port + 11):
        if _port_is_free(host, alt):
            print(f"  ! Port {port} is being used by another program, so this run uses port {alt}.")
            print(f"    Open port {alt} in the browser. A phone paired to {port} needs the new address.")
            return alt
    raise SetupError(f"Ports {port} to {port + 10} are all in use. Start with --port and a free number.")


def serve(cfg: dict, script_dir: Path, port: Optional[int] = None,
          host: Optional[str] = None, token: Optional[str] = None, no_token: bool = False,
          https: bool = False, rotate_token: bool = False,
          config_path: Optional[Path] = None):
    interview = get_interview_settings(cfg, script_dir)
    port = port or interview["port"]
    host = host or "127.0.0.1"
    lan = not is_loopback_host(host)
    # LAN-exposed ⇒ guard with a token unless explicitly disabled; loopback needs none.
    access_token = None
    if lan and not no_token:
        access_token = token or load_or_create_token(script_dir, rotate=rotate_token)

    scheme = "http"
    tls = None
    if https:
        tls = ensure_tls_cert(script_dir, lan_ipv4s() + ["127.0.0.1"])
        if tls is None:
            print("  ! --https needs the 'cryptography' package (pip install cryptography).")
            print("    Continuing over plain HTTP (no PWA install / Wake Lock).")
        else:
            scheme = "https"

    # Every run starts on the configured default model (flash). Pro is the better answer but ~2x
    # slower to first token, so the safe default is the fast one -- switch up mid-interview from the
    # strip when a question turns hard. Without this, last session's pro choice silently persisted.
    _ui = load_ui_settings(script_dir)
    _default_model = interview["answer_model"]
    if _ui.get("answer_model") != _default_model:
        _ui["answer_model"] = _default_model
        save_ui_settings(script_dir, _ui)
        print(f"  Answer model reset to the startup default: {_default_model}")

    port = choose_port(host, port)
    _off = features_off_line(features_off())
    if _off:
        print("  " + _off + " (then restart the app)")
    handler = make_handler(cfg, script_dir, access_token, port=port, scheme=scheme,
                           config_path=config_path)
    try:
        httpd = QuietThreadingHTTPServer((host, port), handler)
    except OSError as e:
        raise SetupError(f"Could not listen on port {port} ({e}). Start with --port and a free number.")
    if tls is not None:
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        ctx.load_cert_chain(certfile=str(tls[0]), keyfile=str(tls[1]))
        httpd.tls_context = ctx
    # Pay the TLS handshake now, not in front of the first interview question (cold: ~26s).
    # No key yet is a first run, not a failure: the page is where the key gets entered, and
    # saving it there warms the connection (see _handle_providers_post).
    try:
        get_gemini_settings(cfg, script_dir)
    except SetupError:
        print(f"  No Gemini key yet. Open the page below and add it in Settings > AI providers & "
              f"API keys, or set {GEMINI_KEY_ENV} and restart.")
    else:
        warm_connection(cfg, script_dir)
    # Self-signed loopback call from the global hotkey would otherwise warn on every press.
    if tls is not None:
        try:
            import urllib3
            urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
        except Exception:
            pass
    hotkey = start_global_hotkey(handler, port, scheme)

    print(f"\nLive Interview Assistant running at: {scheme}://localhost:{port}")
    if tls is not None:
        print(f"  (http://localhost:{port} redirects there)")
    print("Open it in Edge/Chrome, allow the microphone, and start speaking.")
    if hotkey is not None:
        print("  Hotkeys: Ctrl+Alt+A answers the current question from ANY app (global);"
              " Ctrl+Enter does the same when the overlay has focus.")
        print("           Ctrl+Alt+S reads the ACTIVE BROWSER TAB and answers from it -- for a case"
              " study or code review shown on screen. Falls back to a SCREENSHOT when the browser"
              " is not reachable over CDP (Firefox, a native app, a PDF viewer).")
        print("           Ctrl+Alt+D adds one more screenshot frame first -- only needed on the"
              " screenshot fallback, when a case study is longer than one screen.")
    else:
        print("  Hotkey: Ctrl+Enter answers the current question when the overlay has focus."
              "\n  (pip install pynput for a GLOBAL Ctrl+Alt+A that works while minimised.)")
    if lan:
        suffix = (f"?k={access_token}" if access_token else "")
        print(f"\n  [Phone mirror] SCAN TO PAIR -> {scheme}://localhost:{port}/pair")
        print("     (open that on this laptop; scan the QR with your phone camera)")
        ips = lan_ipv4s() or ["<this-PC-LAN-IP>"]
        for ip in ips:
            print(f"     or type: {scheme}://{ip}:{port}/{suffix}")
        if tls is not None:
            print(f"     HTTPS on. For a warning-free, installable app (PWA + screen-stays-awake),")
            print(f"     open {scheme}://{ips[0]}:{port}/ca.crt on the phone ONCE and install it")
            print("     as a CA certificate (Android: Settings > Security > Encryption & credentials).")
        print("     (Windows Firewall may prompt on first run -- allow Python on Private networks.)")
        if access_token:
            print("     The link carries an access token; the laptop's localhost stays open without"
                  " it.\n     The token PERSISTS across restarts, so a paired phone stays paired"
                  " (--rotate-token to revoke).")
        else:
            print("     WARNING: token DISABLED (--no-token) -- anyone on this network can view "
                  "answers and spend API calls.")
        print("     WARNING: bound to the whole LAN -- only do this on a network you trust.")
    print("\nPress Ctrl+C to stop.\n")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nStopping.")
        httpd.shutdown()


# ============================================================
# PERF BASELINE (repeatable; run after every change)
# ============================================================
#
# The point of this is regression-catching, not one-off measurement: the app got slow once from a
# per-request session and a per-query matrix rebuild, and only a measured baseline would have caught
# it. `--benchmark` prints per-stage latency against the REAL index and flags anything over the
# Phase-1 baseline. Keep the question set and thresholds stable so numbers stay comparable.

_BENCH_QUESTIONS = [
    "How would you connect an on-premises datacentre to Azure with 10Gbps and private SQL?",
    "A Linux web app sometimes loads and sometimes times out -- how do you investigate?",
    "What is your experience with Kubernetes?",
    "How do you recover a cloud server hit by ransomware?",
    "What is the vCenter equivalent in Nutanix?",
]
_BENCH_HISTORY = [{"q": "How would you connect on-prem to Azure with 10Gbps and private SQL?",
                   "a": "Hub-and-Spoke with ExpressRoute, Private Endpoints and Private DNS Zones."}]

# Phase-1 measured medians + headroom. A run over these is a regression to investigate.
_BENCH_TARGETS_MS = {"embed": 900, "rank": 15, "condense": 1200, "first_token": 1600}


def _median(xs: List[float]) -> float:
    s = sorted(xs)
    n = len(s)
    if not n:
        return 0.0
    return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2.0


def _stat(xs: List[float]) -> dict:
    """Median plus spread. A lone median hides the thing you most need to see -- whether the run was
    stable or whether one sample was wild -- which is exactly how a noisy number gets mistaken for a
    regression."""
    ms = sorted(x * 1000.0 for x in xs)
    return {"median": _median([x * 1000.0 for x in xs]),
            "min": ms[0] if ms else 0.0, "max": ms[-1] if ms else 0.0, "n": len(ms)}


def benchmark(cfg: dict, script_dir: Path, rounds: int = 3) -> dict:
    """Measure per-stage latency against the real index and print a baseline table.

    Sampling rules, learned from a run that reported 2292ms for a model whose true median is ~1170ms:
      * every stage DISCARDS a warm-up sample. The first call to a given model in a process pays
        set-up the later ones do not, and averaging it in makes a healthy app look slow.
      * time-to-first-token repeats ONE fixed question rather than sweeping several. Different
        questions retrieve different context and take different prompt shapes, so a question mix
        measures the question set as much as the app -- useless for spotting a regression run to run.
      * the answer prompt is built at the CONFIGURED depth, not a hardcoded one, so the benchmark
        measures the thing you actually run.
      * min/max are reported next to the median so a noisy run is visible as noisy.
    """
    print("Loading index + building matrix ...", flush=True)
    t0 = time.perf_counter()
    vindex = load_vector_index(script_dir)
    load_ms = (time.perf_counter() - t0) * 1000.0
    interview = get_interview_settings(cfg, script_dir)
    key = get_gemini_settings(cfg)["api_key"]
    model = vindex.embed_model or interview["embed_model"]
    dim = interview["embed_dim"]

    print("Warming connection ...", flush=True)
    warm_connection(cfg, script_dir, quiet=True)

    embed_t: List[float] = []
    rank_t: List[float] = []
    cond_t: List[float] = []
    ttft_t: List[float] = []
    # The answer model/depth/fast-pro the app is CURRENTLY configured to use.
    _bench_model = effective_answer_model(cfg, script_dir)
    _bench_depth = effective_depth(cfg, script_dir)
    _bench_budget = _pro_budget(_bench_model, cfg, script_dir, _bench_depth)

    embed_query(_BENCH_QUESTIONS[0], model, key, dim)          # warm-up, discarded
    for _ in range(rounds):
        for q in _BENCH_QUESTIONS:
            t = time.perf_counter(); qv = embed_query(q, model, key, dim)
            embed_t.append(time.perf_counter() - t)
            t = time.perf_counter(); rank_hits(qv, vindex, 8)
            rank_t.append(time.perf_counter() - t)

    condense_query("Walk me through the steps for that.", _BENCH_HISTORY, cfg, script_dir)  # warm-up
    for _ in range(rounds):
        t = time.perf_counter()
        condense_query("Walk me through the steps for that.", _BENCH_HISTORY, cfg, script_dir)
        cond_t.append(time.perf_counter() - t)

    # ONE fixed question, repeated. Built at the configured depth so this measures what you run.
    _bench_prof = depth_profile(_bench_depth, False)
    _q = _BENCH_QUESTIONS[0]
    _hits = retrieve(_q, vindex, cfg, script_dir, _bench_prof["top_k"])
    _msgs = build_answer_messages(_q, _hits, "grounded", "", depth=_bench_depth)
    for i in range(rounds + 1):                                # first iteration is the warm-up
        t = time.perf_counter()
        for _piece in generate_answer_stream(_msgs, cfg, script_dir, temperature=0.2,
                                             max_tokens=_bench_prof["max_tokens"],
                                             depth=_bench_depth):
            if i:
                ttft_t.append(time.perf_counter() - t)
            break

    stats = {"embed": _stat(embed_t), "rank": _stat(rank_t),
             "condense": _stat(cond_t), "first_token": _stat(ttft_t)}
    results = {k: v["median"] for k, v in stats.items()}

    def row(label: str, key_: str):
        st = stats[key_]
        m, target = st["median"], _BENCH_TARGETS_MS[key_]
        spread = f"{st['min']:.0f}-{st['max']:.0f}"
        print(f"  {label:<28} {m:8.1f} ms   ({spread} over n={st['n']})"
              f"   (baseline <= {target} ms)  [{'OK' if m <= target else 'SLOW'}]")

    print("\n=== PERF BASELINE ===")
    print(f"  answer model                 {_bench_model:>8}"
          f"   (depth={_bench_depth}"
          + (f", thinking_budget={_bench_budget}" if _bench_budget else "") + ")")
    if _is_thinking_model(_bench_model):
        print("  NOTE: the <=1600ms TTFT baseline was measured on FLASH. Pro thinks before its first")
        print("        token, so a higher TTFT here is the model, not a regression.")
    print(f"  index chunks                 {len(vindex):>8}")
    print(f"  index load + matrix (once)   {load_ms:8.1f} ms")
    row("embed_query (warm)", "embed")
    row("rank_hits (the ranking math)", "rank")
    row("condense_query (follow-up)", "condense")
    row("answer time-to-first-token", "first_token")
    est = results["embed"] + results["rank"] + results["first_token"]
    print(f"  --- new-question TTFT est     {est:8.1f} ms   (embed + rank + first_token)")
    print("=====================\n", flush=True)
    return results


# ============================================================
# CLI
# ============================================================

def main():
    ap = argparse.ArgumentParser(description="Live Interview Assistant: interview answers grounded in your own notes.")
    ap.add_argument("--config", help="Path to config.json.")
    ap.add_argument("--build-index", action="store_true", help="Build/refresh the semantic index.")
    ap.add_argument("--rebuild", action="store_true", help="Force a full re-embed of all chunks.")
    ap.add_argument("--ask", metavar="QUESTION", help="One-shot grounded answer (for prep/testing).")
    ap.add_argument("--serve", action="store_true", help="Launch the live voice overlay.")
    ap.add_argument("--port", type=int, help="Port for --serve (overrides config).")
    ap.add_argument("--host", help="Bind address for --serve (default 127.0.0.1). Use 0.0.0.0 to "
                                   "expose on the LAN for a phone mirror.")
    ap.add_argument("--lan", action="store_true",
                    help="Shortcut for --host 0.0.0.0 (phone-on-Wi-Fi mirror; token-guarded).")
    ap.add_argument("--token", help="Fixed access token for the LAN mirror (default: persisted in ./ia_token).")
    ap.add_argument("--rotate-token", action="store_true",
                    help="Generate a NEW LAN access token, un-pairing previously paired devices.")
    ap.add_argument("--no-token", action="store_true",
                    help="Disable the LAN access token (NOT recommended — opens the app to the network).")
    ap.add_argument("--https", action="store_true",
                    help="Serve over HTTPS with a self-signed cert (needed on the phone for PWA "
                         "install + Wake Lock). Install /ca.crt once to avoid warnings.")
    ap.add_argument("--debug-timing", action="store_true",
                    help="Log per-stage latency (condense/embed/rank/first-token) for each answer.")
    ap.add_argument("--benchmark", action="store_true",
                    help="Measure per-stage latency against the real index (perf baseline).")
    ap.add_argument("--rounds", type=int, default=3, metavar="N",
                    help="Samples per stage for --benchmark (default 3). A warm-up sample is "
                         "always taken and discarded on top of these.")
    ap.add_argument("--preview-tiers", action="store_true",
                    help="Dry run: show tier assignment, exclusions, and tier changes. No writes.")
    ap.add_argument("--migrate-index", action="store_true",
                    help="Convert a legacy all-JSON index to metadata + .npy vectors (no re-embed).")
    args = ap.parse_args()

    script_dir = Path(__file__).parent
    cfg_path = Path(args.config) if args.config else default_config_path()
    cfg = load_config(cfg_path)

    global DEBUG_TIMING
    DEBUG_TIMING = bool(args.debug_timing) or bool(
        cfg.get("interview", {}).get("debug_timing", False))

    did_something = False

    if args.build_index or args.rebuild:
        _index, _stats = build_index(cfg, script_dir, force=args.rebuild)
        did_something = True

    if args.ask:
        result = answer_once(args.ask, cfg, script_dir)
        print("\n" + "=" * 60)
        framed = (f"; answered with the {result['framing']} framing"
                  if result.get("framing") and result["framing"] != result["mode"] else "")
        print(f"Mode: {result['mode']}  (top score {result['top_score']}{framed})")
        if result.get("cv_only"):
            print("No notes indexed yet, so the CV is the only evidence (CV-only mode).")
        print("=" * 60)
        print(result["answer"])
        if result["sources"]:
            print("\nSources:")
            for s in result["sources"]:
                print(f"  - {s['label']}  ({s['score']})")
        did_something = True

    if args.migrate_index:
        migrate_index(script_dir)
        did_something = True

    if args.preview_tiers:
        preview_tiers(cfg, script_dir)
        did_something = True

    if args.benchmark:
        benchmark(cfg, script_dir, rounds=max(1, args.rounds))
        did_something = True

    if args.serve:
        host = args.host or ("0.0.0.0" if args.lan else None)
        serve(cfg, script_dir, args.port, host=host, token=args.token, no_token=args.no_token,
              https=args.https, rotate_token=args.rotate_token, config_path=cfg_path)
        did_something = True

    if not did_something:
        ap.print_help()
        sys.exit(0)


if __name__ == "__main__":
    try:
        main()
    except SetupError as e:
        # A configuration problem, not a crash: print the fix and stop.
        print(chr(10) + "Setup needed:" + chr(10) + "  " + str(e), file=sys.stderr)
        sys.exit(2)
    except KeyboardInterrupt:
        print(chr(10) + "Stopped.", file=sys.stderr)
        sys.exit(130)
